const SESSIONS=[{"slug": "caremall-recon-and-grand-rebirth-pact", "title": "Dungeons and Dragons Campaign Session", "date": "05/28/2026 19:17", "runtime": "3h 46min 53s", "nottaId": "728dba3a-a034-4b28-bee3-d510f898acfc", "url": "https://app.notta.ai/7366972874555052032/dashboard/728dba3a-a034-4b28-bee3-d510f898acfc", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 13613, "subtitle": "A pact sworn, a gate smothered", "logline": "Eight souls swear the Grand Rebirth over an Arcanist feast, then walk into Caramel's spores and find every track leading down to a Feywild gate Vesh sealed shut.", "recap": "Previously on Driftwood Kin…\nThe Ethereal Leaf and Distillery. Smoke curls through silk-wrapped attendants as eight souls sit down to a feast that will change the island forever.\nThe Arcanists spoke — of dwarven homelands lost, of Cauberin gold, of minotaur rage, of a bird-man who sees too far ahead. And the Driftwood Kin spoke back — of oaths sworn not just to themselves, but to the island entire. Of a world with no chains and no masters.\nOne by one, magic flowed. Frost. Embers. Leaves. Black sand. Yellow light. Musical notes. And from the weaving of eight souls, eight bangles were forged — the seal of the Grand Rebirth.\nThen came Caramel. The fortress bled orange spores into the sky like smokestacks. Inside: no bodies. No defenders. No enemies. Only tracks — running inward, running downward, running toward something beneath the earth.\nThey found it. A subterranean river. A barge. A fungal tree knitted through the roots of the world, jamming up the flow of reality itself — sealing a gate to the Feywild. And in the heartbeat before Vesh noticed her, Nyx felt his fear. Not of the people. Not of the party. Of the gate.\nTalon fell. Nyx carried him out. Rune Willow went back in alone.\nThey emerged into the cold air outside Caramel — exhausted, poisoned, and carrying the most important secret on the island.\nThe gate is real. The people went through. And somewhere on the other side of the Feywild, the answer is waiting.", "dm": null, "party": ["Ponzi (Rogue/Tiefling)", "Nyx (Paladin)", "Rune Willow (Bard/Arcane)", "Talon (Cleric/Bard)"], "opens": "Ethereal Leaf and Distillery, concluding discussion with Omarian", "closes": "Outside Caramel, party exhausted, spore samples collected, gate discovered", "cards": {"changed": {"headline": "The Grand Rebirth pact is real", "detail": "The Driftwood Kin and all four Arcanists swore a formal magical oath to establish a free, self-governing island nation — no kings, no dictators, rule by the people — rejecting all five existing nations. Eight interwoven arm bangles were forged from their combined magic as the physical seal.", "t": 2690}, "learned": {"headline": "Feywild gates bypass the Alna Blockade", "detail": "A ring of enchanted ships encircles the island as a \"casting meshed spell\" preventing teleportation onto it — but naturally occurring or torn Feywild gates are \"tears in reality,\" not teleportation magic, and bypass the blockade entirely. This is the mechanism for moving Low Tide's population.", "t": 3681}, "who": {"headline": "Rune Willow", "detail": "Her oath speech — reinterpreting the Driftwood Kin's founding oaths as applying to the entire island — was the session's most powerful RP moment and moved Bayward to forsake Cauberos. She also invented the Runic language, and after the party escaped Caramel she re-entered the spores alone to collect the samples.", "t": 1861}, "cost": {"headline": "2–4 points of exhaustion each, and Rune Willow went back in alone", "detail": "Two members ended at 4 points of exhaustion and two at 2; each long rest removes only 1 point, so full recovery takes multiple days. Talon fell unconscious at 0 HP and cost Nyx 25 points of Lay on Hands and her level 4 Dimension Door. Rune Willow took 3 more exhaustion checks, failing two, to collect the spore samples.", "t": 13569}, "hanging": {"headline": "Where did the people of Caramel go?", "detail": "No bodies anywhere — no defenders, no enemies slain. Every track leads inward, downward, and toward the fungal tree covering the sealed Feywild gate. Did they go through the gate before Vesh sealed it, were they absorbed by him, or did they evacuate via the tower's teleportation circle?", "t": 12909}}, "beats": [{"t": 31, "kind": "social", "title": "Omarian's parting gifts", "line": "The party concluded their meeting with Omarian, a well-connected Tiefling contact who offered to help pursue Caramel before the Feywild and promised affiliate support.", "facets": [["Major NPC", "Omarian (O'Marian) operates out of the Ethereal Leaf and Distillery and is considering Ponzi as an affiliate."], ["Item", "He gave each party member two vials of spore antidote."], ["New lore", "Vetch is growing in influence, including in Ashen Lake."], ["Character", "Omarian has an unnamed group of associates."]]}, {"t": 481, "kind": "plan", "title": "Caramel before the Feywild", "line": "The party debated whether to go to the Feywild or Caramel first; Caramel won, and the embers confirmed it dramatically.", "facets": [["Decision", "Return to Caramel before going to the Feywild, hoping to find survivors and gather spore samples."], ["Decision", "Key argument for Caramel: any survivors won't last if they wait. Key argument for Feywild: the trip takes six months in-world time."], ["Character", "Nyx went to the fireplace, sprinkled ashes and read the embers. Rolled 13. \"To Caramel, says the embers.\""]]}, {"t": 684, "kind": "magic", "title": "The wisp ritual and the Arcanist feast", "line": "Each party member used a spell or cantrip to \"get in\" to the Arcanist Society meeting space via the wisp drinks, then entered an ethereal open space laid out with a grand feast.", "facets": [["Check", "Nyx used Burning Hands (warm wisp), Talon used Feather Fall (slow-rolling liquid), Ponzi used Light (again), Rune Willow used Frostbite (frost-rimmed glass)."], ["Character", "The Arcanists looked at Ponzi and said \"Light again.\" He didn't care. He's been judged before."], ["Environment", "An ethereal open space fading into wispy clouds of smoke, with smoke-elemental attendants wrapped in silk and a large feast table."]]}, {"t": 1226, "kind": "social", "title": "Four Arcanists declare — and are not united", "line": "Each Arcanist stated their position on the plan, and insight checks then revealed they do NOT have consensus on who should ultimately control the island.", "facets": [["Major NPC", "Hanon the Hail (dwarf): fervently in favor — wants to reclaim the ancestral dwarven homeland, separate from Tostra."], ["Major NPC", "Bayward the Wanderer (half-elf): in favor but hesitant about moving against nations other than the Northern Alliance."], ["Major NPC", "Ood the Crafter (black minotaur): simply committed. Cannot wait to hurt the Northern Alliance."], ["Major NPC", "Dakar the Farsighted (Aarakocra): in favor, but warns this will be the inciting incident for island-wide war."], ["New lore", "The five nations: Tostra, Cauberos, Callestus, the Northern Alliance, and Vaan (implied)."], ["Check", "Insight results: 10, 15, 22, 9. The 22 revealed no consensus on island control."]]}, {"t": 1730, "kind": "social", "title": "Rule by the people, and Rune Willow's oath speech", "line": "Talon proposed a nation without kings or dictators; Dakar noted no nation would willingly submit to this, and Rune Willow answered by invoking the Driftwood Kin's founding oaths.", "facets": [["Character", "Rune Willow argued the oaths — no chains, no masters, the wild will endure — now apply to the entire island, not just themselves."], ["New lore", "The founding oaths: no one stands alone; the wild will endure; kindle hope; no chains and no masters."], ["Character", "\"I cannot see any nation that will represent this world as an embodiment for any of those oaths.\""], ["Decision", "The tension between idealism and pragmatism was palpable."]]}, {"t": 2690, "kind": "reveal", "title": "The Grand Rebirth is sworn", "line": "Dakar formally proposed \"a grand mutiny, a grand rebellion, and the establishment of yet another nation — the Grand Rebirth,\" and each member contributed magic.", "facets": [["Decision", "The Driftwood Kin and all four Arcanists swore a formal oath to establish a free, self-governing island nation, rejecting all five existing nations."], ["Item", "Eight interwoven magic bangles were forged from their combined magic as a physical seal of the pact; they fit perfectly on the bicep."], ["Character", "Talon's oath: \"We need to create an island nation that recognizes the good from each of these nations and works towards bringing those together for the good of all people.\" Musical notes became visible and joined the apparition."], ["Decision", "Described as a Phase 1 → Phase 2 transition moment."]]}, {"t": 2957, "kind": "social", "title": "Bayward forsakes Cauberos", "line": "Through conversation with Rune Willow and Nyx, Bayward's Cauberin nationalism yielded to his love of the wild and he forsook Cauberos.", "facets": [["Character", "\"I forsake Cauberos, and I forsake the foulness of it that I carry with me. Instead, I'll hold tight to the wildness of this land and give it to the people who will love it best — its own.\""], ["Environment", "Three leaves cast off his shoulders and joined the center in green magic."], ["New lore", "Cauberos is vast and wealthy and would benefit most from Northern Alliance destabilization; his conversion removes a potential pro-Cauberos voice from the pact."]]}, {"t": 3681, "kind": "lore", "title": "The Alna Blockade — and the way around it", "line": "A ring of enchanted ships encircles the island as a \"casting meshed spell\" preventing teleportation onto it, but naturally occurring or torn Feywild gates are \"tears in reality\" and bypass it entirely.", "facets": [["New lore", "The blockade was established for the \"age of the voyagers\" — years of surface peace before war."], ["Decision", "The tentative grand strategy is to pull the people of Low Tide through a Feywild portal, bypassing the blockade entirely."], ["New lore", "Bayward suggested the gate might be openable from the Feywild side."], ["Decision", "Locate or tear a Feywild gate using Bayward's guidance and weak points in the fabric of reality."]]}, {"t": 3986, "kind": "lore", "title": "The Feywild is reality accentuated", "line": "Hanon described the Feywild as \"our world but accentuated — all the good things are better, all the bad things are worse,\" so studying the spores there will reveal their extremes.", "facets": [["Major NPC", "Bayward has a half-naiad herbalist contact in the Feywild who is the best resource for studying the spores; her name has not yet been determined."], ["New lore", "Distances in the Feywild do not correspond to material plane distances — a 17-mile journey here might be 180 miles there."], ["Decision", "Navigation requires directional guidance, not precise mapping."]]}, {"t": 4334, "kind": "item", "title": "Scrolls, antitoxin, and poison protection", "line": "The Arcanists and Omarian equipped the party for Caramel with scrolls and consumables.", "facets": [["Item", "Scroll of Arcane (Talon), given by Ood: heals only the caster. \"The best thing you can do for others is ensure you're there to keep helping.\""], ["Item", "Scrolls of Revivify x2 (Nyx), given by Hanon; two provided because they couldn't afford more."], ["Item", "Vials of Antitoxin x2 each: bonus action to drink, advantage on saves against the poisoned condition for one hour."], ["Item", "Scrolls of Protection from Poison x4, supplied by Omarian after Ponzi and Nyx reported to him; only Nyx can cast it."]]}, {"t": 4465, "kind": "reveal", "title": "The Runic language", "line": "Talon had been quietly working on a secret language for weeks and presented it to the Arcanists as a gift; Dakar asked to help complete it and refined it with Rune Willow in his tower.", "facets": [["New lore", "Only the eight pact members will know it. Dakar named the language \"Rubik\" (jokingly)."], ["House ruling", "The three non-casters (Talon, Ponzi, Nyx) must make 10 successful DC 15 Intelligence checks, one per day, to learn it fully. DC decreases by 1 for each failure."], ["Environment", "Dakar's Tower in Vattenheim: tomes everywhere, scrolls unfurled, one tapestry hiding stone scarred by wild magic."], ["Item", "Talon and Ood built the spore reliquary — crystal and silver with an enchanted vacuum-seal twist mechanism."]]}, {"t": 5766, "kind": "item", "title": "Black Sand Verdict", "line": "At the Carrasherino arena, a priest of Diune and a smith consecrated Ponzi's daggers using black sand of Diune, a black diamond and a 300gp diamond.", "facets": [["Item", "Black Sand Verdict: paired +1 daggers that constantly shed a stream of black sand which dissolves before touching the ground. Rare, requires attunement."], ["Item", "Weight of Guilt: once per day, after hitting a target with both daggers in one turn, target makes a DC 15 Wisdom saving throw or has movement halved, one attack next turn, and disadvantage on Dexterity saves."], ["Item", "A 300gp diamond sits in the pommel, usable for Revivify."], ["New lore", "Diune is a deity of judgment; the black sand is used in consecration rituals. The Carrasherino arena is an amphitheater in Vattenheim with a forge and a priest of Diune."]]}, {"t": 6635, "kind": "travel", "title": "Brogan Forest to a fortress bleeding spores", "line": "The party retraced their path through Brogan Forest and camped a few miles outside Caramel, where the fortress was visible pouring thick dull orange spores from its octagonal walls like smokestacks.", "facets": [["Environment", "Lichen, moss and fungi on every surface. Main gate closed and barricaded from inside; a breach in the wall to the left of the gate was caused by an explosion from the inside base of the wall."], ["Item", "Talon built a filtration rebreather mask for 16gp of tinkerer supplies (77gp down to 61gp)."], ["Check", "Tinkering check: Intelligence + proficiency, rolled 18. Success."], ["Environment", "The spread appears stable (not exponentially growing) but is severe."]]}, {"t": 7232, "kind": "dread", "title": "The spores don't need you to breathe", "line": "Rune Willow tested spore exposure and felt the poison effects despite not breathing; Nyx then wore the rebreather and scouted the breach in the wall.", "facets": [["House ruling", "Within 50 yards spores begin to fall. Inside the fortress each objective requires a Constitution save: DC 12 exterior, 14 subterranean, 16 deep subterranean. Failure = poison damage (2d8) + 1 exhaustion."], ["House ruling", "Six points of exhaustion = death. Each point of exhaustion is -2 to all rolls. Rebreather grants advantage until the first failure, then breaks."], ["House ruling", "Rune Willow ignores the first point of exhaustion (racial) — takes the damage but not the exhaustion."], ["Check", "Nyx's Divine Sense detected no consecrated or desecrated ground, no undead, fiends or celestials in Caramel."]]}, {"t": 8600, "kind": "scene", "title": "Breaching the wall", "line": "Fire had minimal effect on the lichen and no effect on the spores, and the breach debris was too heavy to move alone — until Talon used Reduce on a vine to open a subterranean passage.", "facets": [["Check", "Nyx's Burning Hands and a Firebolt did minimal damage to the lichen; no change in spores."], ["Environment", "Courtyard overgrown with fungi, collapsed manganelles (mobile catapults) covered in vines, tracks visible in the fungal growth leading into the fortress, not out."], ["Check", "Reduce (Talon) cast on a vine at the breach, shrinking it and collapsing the stone to widen the tunnel entrance."], ["Character", "Ponzi found a locked cellar door at the back of the fortress and picked it."]]}, {"t": 9718, "kind": "clue", "title": "Tracks split in the grand hall", "line": "In the grand hall the tracks split — one path toward a massive heap of destroyed grand tables, the other toward the tower — and Rune Willow found an iron ring hatch door under fungal debris.", "facets": [["Check", "Investigation check (Rune Willow): rolled 22, found the iron ring hatch under debris."], ["Environment", "Subterranean tunnel at the breach: tight squeeze, 4 feet high, fungal vines exploded upward from below — spores are worse underground, this is the origin point."]]}, {"t": 9974, "kind": "combat", "title": "Talon trapped in the rubble", "line": "Talon's foot was caught in collapsing stones during the tunnel descent, taking 7 bludgeoning damage; Nyx failed to free him by hand and used Dimension Door to extract them both.", "facets": [["Check", "Nyx rolled 13 Athletics, setting DC 17 for Talon's Dex save. Talon rolled 3 + 2 = 5, failed."], ["Combat", "Dimension Door can take one willing creature within 5 feet. Level 4 spell — used up for the session."], ["Environment", "The cellar was deeper than normal — \"depth of a cellar beneath a cellar\" — with a hatch door blown upward and rough-cut stone stairs leading further down."]]}, {"t": 10669, "kind": "clue", "title": "Down the second hatch to the river", "line": "Ponzi found a second hatch with rough stone stairs and a wooden lift leading deeper, and descended via a broken enchanted lift to a subterranean cellar with a barge on a slow underground river.", "facets": [["Check", "Perception check (Ponzi): rolled 18, found the hatch door under fungal growth. Rune Willow used Shatter to clear it, scattering debris."], ["Environment", "River chamber ~15 feet tall at its widest, slow-moving underground river, barge docked against stone. The river flows slowly westward, toward Festral likely."], ["Character", "Ponzi barrel-rolled out of the enchanted lift, landed gracefully and immediately started thinking about sailing the barge out. \"We can just take a boat out of here, man.\""]]}, {"t": 12115, "kind": "reveal", "title": "The fungal tree over the Feywild gate", "line": "Ponzi and Rune Willow discovered a fungal tree blocking a subterranean Feywild gate, with all tracks leading toward it.", "facets": [["Check", "Arcana check (Rune Willow): rolled 15, revealing the fungal tree is covering and disabling an extraplanar (Feywild) gate."], ["New lore", "Talon found a teleportation circle in the tower base with a crystal activator, designed for anyone with a bit of magic and costing a level 2 spell slot to activate."], ["Check", "Arcana check (Talon): rolled a dirty 20 (17 + Jack of All Trades + Intelligence) to identify the circle and how to activate it."], ["Decision", "The party now knows the exact location of a sealed Feywild gate beneath Caramel — the key to the Low Tide evacuation plan."]]}, {"t": 12909, "kind": "dread", "title": "No bodies — Caramel is a ghost fortress", "line": "No bodies were found anywhere — no defenders, no enemies slain — and the tracks of the entire population lead to the fungal tree covering the gate.", "facets": [["Environment", "Caramel is effectively a ghost fortress; the population appears to have moved through or toward the Feywild gate."], ["New lore", "Broken bottles and rotted produce in the subterranean cellar appeared exotic, augmented, and \"not quite from the material plane\" — Feywild goods were being stored or traded here."]]}, {"t": 12984, "kind": "boss", "title": "Nyx feels Vesh's fear", "line": "Nyx touched the fungal tree and connected with Vesh's consciousness: his anger is directed at the Feywild gate, not the people of Caramel — he fears it and deliberately sealed it.", "facets": [["Check", "A Natural 20 on a protection roll prevented Vesh from noticing the connection and attacking."], ["Major NPC", "Vesh's consciousness is \"slow burn\" near Caramel — less concentrated than where they previously encountered him. The people of Caramel are \"incidental.\""], ["New lore", "The gate may be openable from the other side; unsealing it from this side would provoke Vesh."]]}, {"t": 13203, "kind": "combat", "title": "Talon goes down, and the party escapes", "line": "Talon fell unconscious at 0 HP from accumulated poison damage and exhaustion; Nyx scooped him up, spent 25 points of Lay on Hands, and the party escaped via the teleportation circle.", "facets": [["Combat", "Talon fell to 0 HP from accumulated poison damage and exhaustion."], ["Character", "As Lay on Hands brought Talon back he felt the warmth of his childhood home — bread baking, his father's pickaxe, the hearth."]]}, {"t": 13423, "kind": "dread", "title": "Rune Willow goes back in alone", "line": "After the party escaped, Rune Willow voluntarily re-entered the spores alone to collect samples for the reliquary — no hesitation, while the party watched.", "facets": [["Check", "Took 3 additional exhaustion checks, failing two, gaining multiple exhaustion points."], ["Item", "Spore samples secured in the reliquary, to be brought to Bayward's herbalist contact in the Feywild."]]}, {"t": 13569, "kind": "rule", "title": "Four exhausted, outside the walls", "line": "The session ended outside Caramel with the party heavily exhausted, samples collected and the gate location known.", "facets": [["House ruling", "Most party members have 2–4 points of exhaustion. Each long rest removes only 1 point; full recovery will take multiple days."], ["House ruling", "Exhaustion at mission end: two members at 4 points, two members at 2 points."], ["House ruling", "The DM allowed antitoxin to heal for 2d8 (negating the specific poison damage) rather than standard rules."], ["Decision", "Record exhaustion points on character sheets before next session."]]}], "threads": [{"u": "hi", "q": "Where are the people of Caramel? Tracks lead to the sealed Feywild gate — most likely they went through, but the gate is now sealed by Vesh. Are they trapped in the Feywild?", "t": 12909}, {"u": "hi", "q": "What does Vesh fear behind the gate? He deliberately sealed it and his anger is directed at the gate itself.", "t": 12984}, {"u": "hi", "q": "The Alna Blockade: the party's entire evacuation plan depends on Feywild gates bypassing it. If the blockade is ever taken down, \"doors wide open.\"", "t": 3681}, {"u": "hi", "q": "Party exhaustion at 2–4 points each — the party cannot function at full capacity and must rest before the Feywild.", "t": 13569}, {"u": "hi", "q": "Can the Caramel Fey gate be safely unsealed from the Fey side without alerting or empowering Vesh?", "t": 12984}, {"u": "md", "q": "Vetch's growing influence — he is expanding his reach, including Ashen Lake. No direct confrontation yet.", "t": 13}, {"u": "md", "q": "Arcanist internal tension: no consensus on who should control the island post-war. This could fracture the Grand Rebirth pact from within.", "t": 1572}, {"u": "md", "q": "Omarian's group identity — he has associates he hasn't revealed. Who are they and what are their capabilities?", "t": 31}], "next": ["Rest and recover from exhaustion (one point per long rest — most members need 2–4 days minimum)", "Report back to Omarian with the decision to go to Caramel first and update on findings", "Make daily Intelligence checks for Runic language learning (Talon, Ponzi, Nyx — 10 checks each, DC 15)", "Plan the Feywild expedition — obtain directional guidance from Bayward", "Locate or tear a Feywild gate (Bayward's guidance + looking for weak points in the fabric of reality)", "Find Bayward's half-naiad herbalist contact in the Feywild", "Deliver spore samples to the herbalist for analysis", "Investigate the possibility of unsealing the Caramel Feywild gate from the other side"], "entities": [{"name": "Ponzi", "kind": "pc", "note": "Rogue/Tiefling. Cast Light again at the wisp ritual. Picked the fortress cellar door, found the second hatch (Perception 18), rode the broken enchanted lift down to the barge, and had his daggers consecrated as the Black Sand Verdict.", "t": 5766, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Nyx", "kind": "pc", "note": "Paladin. Read the embers for Caramel, wore the rebreather and scouted the breach, Dimension Doored Talon out of the rubble, connected with Vesh's consciousness on a Natural 20 protection roll, and spent 25 points of Lay on Hands to revive Talon.", "t": 12984, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Rune Willow", "kind": "pc", "note": "Bard/Arcane. Gave the session's oath speech, invented the Runic language, found the iron ring hatch (Investigation 22), identified the Feywild gate (Arcana 15), and re-entered the spores alone to collect samples. Ignores her first point of exhaustion (racial).", "t": 13423}, {"name": "Talon", "kind": "pc", "note": "Cleric/Bard. Proposed rule by the people, built the rebreather mask and the spore reliquary with Ood, found and identified the tower teleportation circle, and fell unconscious from poison and exhaustion.", "t": 13203, "reveal": "Talon's real name is Tanner."}, {"name": "Omarian (O'Marian)", "kind": "npc", "note": "Well-connected Tiefling operating out of the Ethereal Leaf and Distillery. Considering Ponzi as an affiliate; supplied spore antidote vials and 4 Scrolls of Protection from Poison. Has an unnamed group of associates.", "t": 13}, {"name": "Dakar the Farsighted", "kind": "npc", "note": "Aarakocra Arcanist leader from a land of warring peoples. Warned this move will be the inciting incident for island-wide war, then proposed the Grand Rebirth. Helped Rune Willow complete the Runic language and jokingly named it \"Rubik\".", "t": 1044}, {"name": "Hanon the Hail", "kind": "npc", "note": "Older tattooed dwarf Arcanist. Passionate about reclaiming the dwarven ancestral homeland and separating from Tostra. Gave Nyx two Scrolls of Revivify and described the Feywild as reality accentuated.", "t": 1044}, {"name": "Bayward the Wanderer", "kind": "npc", "note": "Half-elf Arcanist with tanned skin, dark eyes and raven black hair in a tight ponytail. Cauberin by origin; converted by Rune Willow and Nyx and forsook Cauberos. Has a half-naiad herbalist contact in the Feywild.", "t": 1293}, {"name": "Ood the Crafter", "kind": "npc", "note": "Large black minotaur Arcanist. Few words, total commitment. Built the spore reliquary with Talon and gave Talon a Scroll of Arcane.", "t": 1372}, {"name": "Bayward's Feywild Contact (Unnamed)", "kind": "npc", "note": "Half-naiad herbalist living in the Feywild, best contact for studying the spores. Name not yet determined by the DM.", "t": 4046}, {"name": "Priest of Diune (Unnamed)", "kind": "npc", "note": "Stationed at the Carrasherino arena. Prays over weapons before consecration; used black sand of Diune in Ponzi's dagger ritual.", "t": 5766}, {"name": "Vesh", "kind": "creature", "note": "The fungal entity, felt through Nyx's connection rather than physically present. His consciousness is \"slow burn\" near Caramel. His anger is directed at the Feywild gate, not the people — he fears the gate and deliberately sealed it.", "t": 12984}, {"name": "The Grand Rebirth", "kind": "faction", "note": "Formed this session: the Driftwood Kin plus four Arcanists. Goal is a free, self-governing island nation with no kings and no dictators, sealed by magical oath and eight arm bangles.", "t": 2690}, {"name": "The Arcanists", "kind": "faction", "note": "United against the Northern Alliance but divided on the endgame — no consensus on who should ultimately control the island. Dakar is the most visionary; Bayward was the most conflicted.", "t": 1572}, {"name": "The Northern Alliance", "kind": "nation", "note": "Primary antagonist faction with multiple footholds across the island and currently the most likely to win any war. Destabilizing them is the party's primary strategic goal.", "t": 1446}, {"name": "Cauberos", "kind": "nation", "note": "Vast, wealthy nation and Bayward's homeland; positioned to \"swoop in and fill the void\" if the Northern Alliance is destabilized. Bayward has now forsaken it.", "t": 2312}, {"name": "Tostra", "kind": "nation", "note": "The nation Hanon wants separation from; Arcanist composition includes a Tostranian (Hanon).", "t": 2623}, {"name": "Callestus", "kind": "nation", "note": "Referenced as a nation that would be destabilized; Arcanist composition includes a Callestian (Ood).", "t": 1446}, {"name": "Vaan", "kind": "nation", "note": "Nation of \"wild gods,\" dragon-riders and untamed peoples, referenced by Bayward. Includes \"the scum\" — the smallest of the Vaan nations.", "t": 2164}, {"name": "The Alna Blockade", "kind": "faction", "note": "A ring of enchanted ships encircling the island — a \"casting meshed spell\" preventing teleportation onto it. Established for the \"age of the voyagers.\" Naturally occurring or torn Feywild gates bypass it.", "t": 3681}, {"name": "Ethereal Leaf and Distillery", "kind": "place", "note": "The party's base in Vattenheim, containing a hidden ethereal meeting space accessible via wisp drinks, with smoke elemental attendants wrapped in silk.", "t": 977}, {"name": "Dakar's Tower", "kind": "place", "note": "In Vattenheim. Tomes everywhere, scrolls unfurled, tapestries on the walls — one hiding stone scarred by wild magic. Used for Runic language work.", "t": 5197}, {"name": "Carrasherino Arena", "kind": "place", "note": "An amphitheater in Vattenheim with late-night pit fights, a forge and a priest of Diune.", "t": 5746}, {"name": "Brogan Forest", "kind": "place", "note": "The forest path used to travel quickly between Vattenheim and Caramel.", "t": 6635}, {"name": "Caramel", "kind": "place", "note": "Octagonal-walled fortress pouring thick dull orange spores like smokestacks, main gate barricaded from inside, a breach blown outward from the wall's inside base. Now effectively a ghost fortress.", "t": 6816}, {"name": "Subterranean River Chamber", "kind": "place", "note": "~15 feet tall at its widest, with a slow-moving underground river flowing westward, a barge docked against stone, and a fungal tree covering the sealed Feywild gate. All of Caramel's tracks lead here.", "t": 11416}], "gaps": ["The source never names the DM — it refers only to \"the DM\" in third person (e.g. the herbalist's name being undetermined), so `dm` is left null.", "Place-name spelling varies across the source between \"Caramel\" (Layer 1/Layer 2) and \"Caremall\" (the Project Sync section); \"Vetch\" and \"Vesh\" are also both used, as are \"Ood\"/\"Uud\" and \"Omarian\"/\"Umarian\". Names are copied as spelled in the section they came from.", "Bayward's half-naiad herbalist contact has no name — the source states the DM has not written it yet.", "The Project Sync / Status Update section of the note carries no timecodes at all; every `t` in this file comes from the timecoded Layer 1 and Layer 2 sections.", "The source contains 94 distinct timecodes; the 24-beat cap means several timecoded entries were merged into a neighbouring beat's facets and their individual timecodes are not separately represented.", "One character-moment heading in the source reads \"Nyx Waking Up in Nyx's Arms\" but describes Talon waking in Nyx's arms — the body text was followed."], "iso": "2026-05-28", "pretty": "28 May 2026", "audio": true, "legendary": false, "timecodesReliable": true, "n": 16}, {"slug": "city-festival-arrival", "title": "Tabletop RPG Campaign Session: City Festival Arrival", "date": "05/19/2026 19:41", "runtime": "3h 15min 2s", "nottaId": "409b16ec-c515-48c4-ad0f-b84380d5b7a3", "url": "https://app.notta.ai/7366972874555052032/dashboard/409b16ec-c515-48c4-ad0f-b84380d5b7a3", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 11702, "timecodesReliable": true, "subtitle": "Oaths, honesty, and a stranger's chessboard", "logline": "A festival day of celebration, confession and shopping ends with the Driftwood Kin decoding a map to the Feywild and meeting a spymaster over chess.", "recap": "Previously on Driftwood Kin…\nThe Feast of Oaths filled the City of the Wild with the sound of vows and the smell of incense. The party descended from the sky — some with grace, some with thunder — and scattered into the festival like sparks from a fire.\nNix crawled out of a kitchen drenched in sweat, clutching a stolen recipe like a treasure map. Ruel lost arm wrestling matches with the enthusiasm of someone who had never heard the word \"dignity.\" Talent played music through three floors of a tavern, following the most important moments of strangers' lives, until she found herself on a stage she hadn't planned to be on.\nAnd then, in the deep of the night, while the others slept, Talent slipped out alone. She walked to the Luminarkan Theater, climbed onto a dark stage lit only by floating motes of starlight, and she danced. She bladesang until her legs gave out, until the stars multiplied around her, until she staggered to a velvet chair in the upper boxes and let her vision blur for the first time in a long time — not in loneliness, but in peace.\nMorning brought honesty. Ponzi, bound by a deal with Dion, answered questions he had never answered before. His real name is not Ponzi. His parents died when he was six. A charlatan named Wolfgang took him in, taught him everything, and may now want him dead. And somewhere in the deserts of Cauberos, a man who sells water to the dying calls himself the Merchant of Life — and everyone who knows him calls him something else.\nThe party spent the day arming themselves. Talon acquired tools and a crystal lens from Oud the Crafter, and made a deal — her bronze dragon scale, Versalc's needles, and Nyx's divine magic, woven together into something that might let her cross thirty feet in the blink of an eye. Ponzi had his daggers consecrated, embedding diamonds in the handles — one for purity, one for the dark — and one of those diamonds could bring a fallen friend back from the edge of death.\nThey deciphered the Delvers Map. Seven locations in the Underdark, written in ancient Gnomish, tangled like a nightmare. They placed them in order: a basin beneath drowned bones, crags of weeping gas, salt plates, a haunted wood at the center of everything, a swamp of lights, a cloud cavern of danger and sprawl, and at the end — the Bright River Gate. A door to the Feywild. A door to answers.\nAnd then they met Umari. Blue-skinned, silver-eyed, sweet-smelling smoke curling from a long pipe. He played chess with Ponzi, recognized the opening Roon had taught, and listened. The party told him what they knew of Vashj — the fungal entity spreading across the material plane, the orange spores of Karamal, the connection to Lady Shill. Umari's eyes flickered. That last part was new. He gave them antidotes. He promised a Feywild contact. And he left them with a warning wrapped in a compliment: his organization's eyes were already watching.\nTonight, the Arcanist Society waits.", "dm": "Jake", "party": ["Ponzi", "Nix", "Talent/Talon", "Ruel"], "opens": "Mid-action descent into the city after a dramatic waterfall/free-fall sequence.", "closes": "Just before dinner with the Arcanist Society.", "cards": {"changed": {"headline": "Ponzi's past is now known to the party", "detail": "Under the Total Honesty pact Dion arranged, Ponzi gave up his origins in Calestus, his dead noble parents, his street years, his mentor Wolfgang — who may now want him dead — and his knowledge of the Merchant of Life/Death. A significant internal shift in party trust and cohesion.", "t": 1795}, "learned": {"headline": "The Delvers Map is a route to the Feywild", "detail": "Talon translated the ancient Gnomish and eight group checks put seven Underdark locations into order: Basin Beneath the Lake-Drenched Bones, Crags of Weeping Gas, Salt Plates, Haunted Wood, Swamp of Lights, Cloud Cavern of Vanalysis, and the Bright River Gate — the Feywild gate at the end.", "t": 6745}, "who": {"headline": "Ponzi", "detail": "The session turned on him twice: once when the honesty pact stripped his history bare in front of the party, and again when the chess opening Roon taught him earned recognition from Umari and opened the door to an intelligence organization with eyes across the island.", "t": 1795}, "cost": {"headline": "450 gold and a lifetime of privacy", "detail": "Ponzi spent 400g on two diamonds at the Dao's Favor plus a 50g consecration fee, and 200g on potions; Talon spent 76g on supplies and 80g on Candles of the Deep. Ponzi also paid in secrets — everything but his real name, which nobody thought to ask for.", "t": 6115}, "hanging": {"headline": "What does the Arcanist Society want?", "detail": "Dinner is tonight, the agenda is unknown, Oud will supply the meal, and the only guidance is to enter with a different spell than last time — a hint the Arcanists test or observe their visitors.", "t": 11662}}, "beats": [{"t": 120, "kind": "scene", "title": "Descent into the Feast of Oaths", "line": "The session opens mid-action with the party descending into the City of the Wild during the Feast of Oaths festival, each celebrating in their own way.", "facets": [["Environment", "Streets filled with newlyweds, oath-swearers, altars with incense burns, evidence of various rites."], ["New lore", "The Feast of Oaths is a festival in the City of the Wild where oaths are sworn — including marriage vows, oaths to departed loved ones, and tribal allegiances."], ["Environment", "Trifold Tavern: three floors — First Floor (lively, common), Second Floor \"Among Friends, Pipe and Leaf\", Third Floor \"The Fine Grove\" (finest, vines everywhere, fancy wines)."]]}, {"t": 242, "kind": "social", "title": "Party celebrations at the Trifold Tavern", "line": "Ruel challenges tavern patrons to arm wrestling at disadvantage and loses charmingly; Talent plays music floor to floor with Ponzi, ending on the Fine Grove stage for a wedding party.", "facets": [["Check", "Ruel, Athletics at disadvantage: 9. Lost charmingly but enthusiastically; drinks heavily with zero effect but feels warmth."], ["Check", "Talent + Ponzi, Performance: 18 (12 base + 4 CHA + 3 proficiency, Ponzi assist)."], ["Character", "Ponzi ends the night with two bridesmaid names on paper in his breast pocket."]]}, {"t": 409, "kind": "scene", "title": "Nix steals the Cornucopia recipe", "line": "Nix takes a cooking shift at the Cornucopia disguised as a gnomish line cook, waits for her moment, and snatches a recipe.", "facets": [["Check", "Stealth 12 — successful disguise as a gnome line cook."], ["Check", "D100: 80 — Recipe: Tea Marinated Trout, Flaky Biscuits, Sweet Carrots, and Blackberry Pie."], ["Character", "Drenched in sweat, yelled at for poor butchering; crawls out and unfolds a slightly wet but legible recipe. Pure joy."]]}, {"t": 1014, "kind": "scene", "title": "Talent's bladesinging vigil at the Luminarkan Theater", "line": "Talent sneaks out in the middle of the night to the Luminarkan Theater, bladesings alone until near-collapse, and experiences the most peaceful, least-lonely rest of her life.", "facets": [["Environment", "Tall tower with a stone angel statue with outstretched wings; dark main hall with magical motes of starlight (\"mozelites\") illuminating the stage."], ["Check", "Talent, Perception 8 — too tired to focus; allows vision to blur."], ["Character", "The magical motes seem to multiply the longer she bladesings; a profound moment of self-acceptance and rededication."], ["Check", "Ponzi's room alarm, D20 (60% = 8+): 12 — would have alarmed Talent's room; Talent's room less likely alarmed. Talent slips out undetected."]]}, {"t": 1547, "kind": "social", "title": "Morning — the Total Honesty pact is invoked", "line": "The party wakes fully healed and invokes the Total Honesty agreement Dion arranged with Ponzi; each party member gets one question.", "facets": [["Decision", "Dion had arranged for Ponzi to answer questions with total honesty. Each party member gets one question."], ["Rule", "Truth detection by coin ringing — the coin rang on \"Wolfgang\", confirming truth."], ["Environment", "Temporary HP gone, permanent HP back."]]}, {"t": 1795, "kind": "reveal", "title": "Ponzi's origins revealed", "line": "Ponzi reveals his real name is NOT Ponzi, his origins in Calestus, his noble parents' deaths, and his years on the street.", "facets": [["Character", "Born in Calestus (the kingdom whose king calls himself \"the Voice of Heaven\", known for murdering villages). Parents were noblemen who died when he was 6-7. Kicked out with no support."], ["Character", "Languages: Common, Orc, Goblin, Celestial, and Thieves' Cant (spoke only Thieves' Cant for 2.5 years at one point)."], ["Check", "Insight on Ponzi: 9 — inconclusive, but his tone matches his most genuine moments (like when Scar was awakened)."]]}, {"t": 1862, "kind": "lore", "title": "Wolfgang the charlatan", "line": "At 13-14 Ponzi tried to rob a charlatan named Wolfgang, who took pity, brought him into his gang and taught him sleight of hand — and may now be trying to kill him.", "facets": [["New lore", "Wolfgang was the \"Dawson\" (top criminal figure) of their region. Came to this island — Ponzi doesn't know if before, with, or after him."], ["Major NPC", "Wolfgang may now be trying to kill Ponzi. Told Ponzi to stay away from the Merchant of Life/Death."]]}, {"t": 2271, "kind": "lore", "title": "The Merchant of Life/Death and the Mirageum", "line": "The Merchant of Life operates in the deserts of Cauberos, conjuring and selling water to nomads, drying up oases, and punishing free giving through enforcers called the Mirageum.", "facets": [["New lore", "Places magical enchantments preventing others from conjuring water. Ponzi and Wolfgang called him the Merchant of Death."], ["Check", "History 19+1 = dirty 20 — full knowledge of the Merchant of Life/Death and the Mirageum."], ["Character", "Ponzi swears he is unaffiliated with the Merchant of Life."]]}, {"t": 2477, "kind": "social", "title": "\"You still haven't asked my real name\"", "line": "The party's trust in Ponzi visibly grows after the honesty session — but nobody ever asked him his real name, and he says so.", "facets": [["Character", "Nix draws stick-figure Ponzi with sunshine in her notebook."], ["Decision", "Talon's empathy about being kicked out with no support; the general warmth of the scene marks a turning point in party cohesion."]]}, {"t": 3087, "kind": "item", "title": "Shopping at Oud's Oddities", "line": "At Uzz Adades beneath the waterfall, Talon buys 76 gold of tinkering supplies and two Candles of the Deep and is gifted a crystal lens; Ponzi buys healing potions.", "facets": [["Item", "Talon: 76g tinkering supplies (gears, springs, rods, screws, pins, metals, gems); free crystal lens on brass wireframes — \"older eyes can need a little assistance.\""], ["Item", "Candles of the Deep x2 for 80g (discounted from 100g) — not extinguished when immersed in water, still emit light and heat."], ["Item", "Ponzi: 2x Healing Potion (100g) + 1x Greater Healing Potion (100g) = 200g."], ["Major NPC", "Oud works with two hands plus four spectral hands, tinkering on a metallic scorpion-like contraption while a spectral hand leafs through his spellbook."]]}, {"t": 4777, "kind": "social", "title": "Oud hints at something grander than patronage", "line": "Oud declines patronage but hints at a deeper relationship with the Driftwood Kin, and warns them to enter the Arcanist Society dinner with a different spell than last time.", "facets": [["Major NPC", "\"I believe I'm far too selfish of a moment for patronage. I'm afraid that if I were to give you too much assistance, I would demand too much of you.\""], ["Decision", "Oud will supply a meal for the party at the Arcanist Society dinner (Dakar has fine tastes, Hannon's are down-to-earth)."], ["New lore", "\"If you enter into the space with a different spell, the other arcanists will notice positively. Don't use the same spell twice to get in.\""]]}, {"t": 5027, "kind": "magic", "title": "Talon's oath rededication and the teleportation enchantment", "line": "Talon presents Versalc's tattooing needles and a bronze dragon scale, rededicating her oath to protect the party; Oud and Nyx agree to imbue teleportation into her armor or weapon.", "facets": [["Check", "Nyx, Persuasion 14 — Oud is moved and agrees to collaborate."], ["New lore", "Oud believes magic has a heartbeat — the same spell cast by different people produces different results for enchanting."], ["Character", "Nyx reveals she is \"chosen for the rose of the mage.\""], ["Item", "In progress: teleportation-imbued armor/weapon; bronze dragon scale + Versalc's needles; Nyx must cast the spell multiple times."]]}, {"t": 5720, "kind": "scene", "title": "Consecrating Ponzi's daggers at the Wilder Temple", "line": "Ponzi asks the priest of Idis the Huntress to consecrate his plus-one daggers for better purposes; the priest suggests a diamond in each — one for purity, one for the duality of danger.", "facets": [["Major NPC", "Same priest as the party's previous visit; eyes go wide seeing Driftwood Kin — nervous but respectful."], ["Rule", "The Revivify spell requires a 300g diamond, consumed on casting."], ["Decision", "Priest recommends a smith at the Karasharina arena to set the gems; gem sources are Madam Masalia or the Dao's Favor gambling hall."], ["Environment", "Wilder Temple — holy space of Idis the Huntress (Diune's spouse); edict stones and heavy bell still present."]]}, {"t": 6115, "kind": "item", "title": "Delos Dice at the Dao's Favor", "line": "Ponzi gambles for gems at the Dao's Favor and walks out with a 300g Revivify diamond and a 100g black diamond for 400g, plus a 50g consecration fee.", "facets": [["Check", "Delos Dice: Ponzi rolls D6 against the DM's 3D6, 100g off per matching die. Rolled two 6s and a 3 — came out roughly even."], ["Item", "300g Revivify diamond (consumed when Revivify is cast) and 100g black diamond, embedded in the dagger handles."], ["Environment", "Gambling hall with strange treasures from people gambling away valuables."]]}, {"t": 6745, "kind": "clue", "title": "Deciphering the Delvers Map", "line": "Talon translates the Delvers Map from ancient Gnomish and the party runs eight group skill checks to order seven Underdark locations ending at the Bright River Gate.", "facets": [["Check", "Talon, History dirty 20 (19+1) — translated all 7 location names."], ["New lore", "Locations: Basin Beneath the Lake-Drenched Bones, Crags of Weeping Gas, Salt Plates, Haunted Wood, Swamp of Lights, Cloud Cavern of Vanalysis, Bright River Gate."], ["Check", "Talon Perception 15 — Haunted Wood = bottleneck, fed by 2, feeds 2. Nix Insight 21 — Haunted Wood → Swamp of Lights → Bright River Gate. Ruel Perception 25 — Basin = #1."], ["Check", "Nix Faith 6 (burned luck) — Swamp of Lights = blessed; Cloud Cavern = disdain. Talent History 23 — Cloud Cavern = #6. Ruel Survival 18 (burned luck) — Crags connect Basin to Haunted Wood."]]}, {"t": 7266, "kind": "lore", "title": "The Underdark and the Cloud Cavern of Vanalysis", "line": "The map leads through a subterranean world of caves, caverns and massive ecosystems; the Cloud Cavern of Vanalysis has a \"cloud line\" deep in the Underdark — a place of particular danger.", "facets": [["New lore", "Cloud Cavern of Vanalysis is sprawling and dangerous — easy to get lost."], ["Environment", "The Crags of Weeping Gas suggests toxic gas hazards; the Haunted Wood is a bottleneck."]]}, {"t": 7939, "kind": "clue", "title": "\"Lake-Drenched Bones\" rings familiar", "line": "Ruel's perception check on the map notes the phrase \"lake-drenched bones\" rings familiar to the overworld map — the Drowned Crypt may be the entry point to the Underdark.", "facets": [["Check", "Ruel, Perception 25."], ["Decision", "Party suspects the entry point is accessible from the overworld lake — the Drowned Crypt, or a large lake in Vattenheim."]]}, {"t": 9025, "kind": "clue", "title": "The map's unresolved contradiction", "line": "Cloud Cavern is said both to feed into the Haunted Wood and to lead toward the Bright River Gate; Salt Plates and Crags positions remain uncertain.", "facets": [["New lore", "Contradiction noted: Salt Plates and Cloud Cavern both said to feed into Haunted Wood, but Cloud Cavern also said to lead toward Bright River Gate — unresolved."]]}, {"t": 9957, "kind": "social", "title": "Meeting Umari at the Ethereal Leaf & Distillery", "line": "The party finds Umari — a blue-skinned tiefling with silver eyes and a long, sweet-smelling pipe — playing chess in a corner of the distillery; Ponzi loses the first game.", "facets": [["Major NPC", "Tiefling, deep blue skin, dramatic white horns, lean build, dark gray suit, gleaming white shirt (mithril chainmail beneath), metallic silver eyes."], ["Check", "Ponzi, Intelligence 17 — good fundamentals; Umari wins round 1 and introduces himself."], ["Check", "Nix + Ponzi, Perception 18 — the smoke smells strangely sweet. Party Insight 10 — hard to read; very guarded."], ["Environment", "Ethereal Leaf & Distillery: smoky, dimly lit fine establishment; pipe smoking lounge across multiple floors."]]}, {"t": 10354, "kind": "reveal", "title": "Roon's opening and Boson's token", "line": "Ponzi plays the special opening Roon taught him; Umari moves a rook to the centre and says \"Welcome to the chessboard\", then authenticates Boson's chess-piece token.", "facets": [["Character", "The opening attacks extremities rather than the centre — the first 8 moves create a complete circle of pieces around an empty board."], ["Item", "Ponzi produces Boson's token from his sandhand — a knight chess piece with notches; Umari confirms it is the society's signature."], ["Major NPC", "Umari's organization is connected to Dion and Boson: \"This island is yet young, but our eyes are at war.\""]]}, {"t": 10772, "kind": "lore", "title": "Vashj confirmed — and the Lady Shill connection is new", "line": "Umari confirms the fungal entity is Vashj and that his influence is spreading; the party's report that Vashj loved Lady Shill is intelligence his organization did not have.", "facets": [["New lore", "\"This entity is outstretching his hand across the side and his grasp is slowly starting to squeeze it.\" Influence confirmed at Low Tide, underground caverns, Karamal (orange spores) and ocean/lake areas."], ["New lore", "Vashj was a servant to Lady Shill, was in love with her, and seeks to avenge her after her defeat."], ["Major NPC", "\"You've done something quite rare, which is tell one of my lord earths something they don't already know.\""], ["Check", "Party, Persuasion 17, 17, 17 — Umari shares information on Vashj."]]}, {"t": 11315, "kind": "item", "title": "Antidotes and a promised Feywild contact", "line": "Umari gives each party member two antidote vials and promises to work on acquiring a Feywild contact or goal, with more assistance on their return.", "facets": [["Item", "2 antidote vials per member — negates the effects of many poisons, including Vashj's poisonous spores."], ["Check", "Insight on Umari's leaf: 15 — he holds it close to his chest, sentimental or connected to something painful."]]}, {"t": 11429, "kind": "plan", "title": "Feywild first, then Karamal", "line": "The party debates rushing to Karamal where people may be dying versus going to the Feywild first for deeper answers; consensus lands on the Feywild.", "facets": [["Decision", "Feywild first, then Karamal with better knowledge and Umari's support."], ["Decision", "Option B — immediate reconnaissance of Karamal to check for survivors — judged higher risk with limited countermeasures today."]]}, {"t": 11662, "kind": "plan", "title": "The Arcanist Society waits", "line": "The session ends just before dinner with the Arcanist Society — unknown agenda, Oud supplying the meal, and a standing warning to vary the entry spell.", "facets": [["Decision", "Attend dinner with the Arcanist Society — use different entry spells; Oud will supply a meal; unknown agenda."], ["Major NPC", "Oud's hint about using different entry spells suggests the Arcanists test or observe visitors."]]}], "threads": [{"u": "hi", "q": "Vashj's influence is spreading — orange spores at Karamal, confirmed spread to ocean/lake areas. People may be dying in Karamal right now.", "t": 10845}, {"u": "hi", "q": "Where is Wolfgang, and does he want Ponzi dead? He may be on the island.", "t": 1998}, {"u": "hi", "q": "What does the Arcanist Society want from the Driftwood Kin at tonight's dinner?", "t": 11662}, {"u": "md", "q": "Delvers Map contradictions — Cloud Cavern feeds the Haunted Wood AND leads to Bright River Gate; Salt Plates position uncertain.", "t": 9025}, {"u": "md", "q": "Where is the overworld entry point to the Underdark — the Drowned Crypt, or the large lake in Vattenheim?", "t": 9577}, {"u": "md", "q": "What is Ponzi's real name? The party knows it is not Ponzi, but never asked.", "t": 2477}, {"u": "md", "q": "What is Talon's connection to the Luminarkan Theater — why did the mozelites multiply during her bladesinging?", "t": 1339}, {"u": "md", "q": "What is Umari's sweet-smelling leaf — sentimental, or a painful connection?", "t": 11627}], "next": ["Dinner with the Arcanist Society — arrive with different entry spells; listen carefully; unknown agenda", "Finalize Ponzi's dagger consecration at the Karasharina smith", "Begin Talon's teleportation enchantment with Oud and Nyx", "Identify the overworld entry point to the Underdark (Drowned Crypt? Vattenheim lake?)", "Await Umari's Feywild contact", "Confirm party route: Feywild first, then Karamal", "Consider returning to Oud for high-value items after the Arcanist dinner", "Ask Ponzi his real name"], "entities": [{"name": "Ponzi", "kind": "pc", "note": "Changeling with a sandhand; real name unknown. Revealed his origins in Calestus, his mentor Wolfgang, and the Merchant of Life/Death under the Total Honesty pact. Had his plus-one daggers consecrated to Idis the Huntress.", "t": 1547, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Nyx", "kind": "pc", "note": "Spelled \"Nix\" throughout this note. Infiltrated the Cornucopia cooking pits and stole a recipe; offered her divine magic for Talon's teleportation enchantment, revealing she is \"chosen for the rose of the mage\".", "t": 409, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Talon", "kind": "pc", "note": "Also spelled \"Talent\" in this note (the note's own party list reads \"Talent/Talon\"). Bladesang alone at the Luminarkan Theater, translated the Delvers Map, and rededicated her oath to protect the party.", "t": 1014, "reveal": "Talon's real name is Tanner."}, {"name": "Ruel", "kind": "npc", "note": "Listed by the note as a party member of the Driftwood Kin (changeling); lost arm wrestling matches and made the Perception 25 and Survival 18 map checks. Not on the vault's player-character roster, so recorded as npc pending confirmation.", "t": 242}, {"name": "Oud the Crafter", "kind": "npc", "note": "Eccentric artificer/wizard of Uzz Adades in the Falls District; works with two hands plus four spectral hands. Declined patronage but hinted at \"something grander\", and agreed to imbue teleportation into Talon's armour or weapon with Nyx's magic.", "t": 3170}, {"name": "Umari", "kind": "npc", "note": "Tiefling with deep blue skin, white horns and metallic silver eyes; smokes a sweet-smelling pipe. Chess contact connected to Dion and Boson; gave the party antidote vials and promised a Feywild contact.", "t": 9957}, {"name": "Wolfgang", "kind": "npc", "note": "Charlatan and former \"Dawson\" (top criminal) of his region who took Ponzi in at 13-14 and taught him sleight of hand. May now be trying to kill him; possibly on this island.", "t": 1862}, {"name": "The Merchant of Life/Death", "kind": "npc", "note": "Conjures and sells water to the nomadic peoples of Cauberos, dries up oases, and blocks others from conjuring water. Ponzi and Wolfgang called him the Merchant of Death.", "t": 2271}, {"name": "Vashj", "kind": "creature", "note": "Fungal entity, formerly a servant to Lady Shill and in love with her, now spreading fungal influence across the material plane in vengeance. Orange spore variation at Karamal.", "t": 10772}, {"name": "Lady Shill", "kind": "npc", "note": "Evil queen/lady who was defeated. Vashj was her servant and was in love with her — an intimacy Umari's organization did not know.", "t": 10972}, {"name": "Roon", "kind": "npc", "note": "Taught Ponzi chess, including the special opening that earned Umari's respect.", "t": 10227}, {"name": "Boson", "kind": "npc", "note": "Sent Ponzi to find Umari with information on the fungal destroyed city; provided the notched chess-piece token used for authentication.", "t": 10452}, {"name": "Dion", "kind": "npc", "note": "Arranged the Total Honesty agreement with Ponzi and told Nix to be honest with the party. Connected to Umari.", "t": 1680}, {"name": "Priest of Idis the Huntress", "kind": "npc", "note": "Same priest as the party's previous visit at the Wilder Temple; consecrating Ponzi's daggers and recommending the diamond gems for the Revivify mechanic.", "t": 5763}, {"name": "Idis the Huntress", "kind": "deity", "note": "Goddess of the Wilder Temple, described as Diune's spouse. Ponzi's daggers are being consecrated to her.", "t": 5720}, {"name": "Diune", "kind": "deity", "note": "Named only as the spouse of Idis the Huntress.", "t": 5720}, {"name": "Uros", "kind": "asterum", "note": "Named on the loot table as the subject of the books/tomes Ruel bought (\"Books/Tomes (Urus)\", light reading on local lore and Festival of Oaths topics). Source spelling \"Urus\"; appears to be the Asterum Uros. The note gives no further detail.", "t": null, "alias": "Urus"}, {"name": "Driftwood Kin", "kind": "faction", "note": "The party. Now known by name to Umari's organization and accumulating faction allies (Oud, Umari, the Arcanists, the priest of Idis).", "t": 9957}, {"name": "The Arcanists", "kind": "faction", "note": "Recorded in the vault as the Arcanists. Oud is an associate; they have been wanting to meet the Driftwood Kin. Dinner is tonight, agenda unknown.", "t": 4885, "alias": "Arcanist Society"}, {"name": "Umari's Organization (Unknown Name)", "kind": "faction", "note": "Intelligence-gathering organization connected to Dion and Boson with \"eyes across the island\". Provided antidote vials and a promised Feywild contact.", "t": 9957}, {"name": "Wolfgang's Gang", "kind": "faction", "note": "Ponzi's former criminal family, which he left or escaped. Wolfgang may now be hostile.", "t": 1862}, {"name": "The Mirageum", "kind": "faction", "note": "Enforcers for the Merchant of Life/Death who hunt down anyone who gives water freely in Cauberos.", "t": 2327}, {"name": "Callestus", "kind": "nation", "note": "Source spells this \"Calestus\". One of the five sovereign nations. Ponzi's birthplace; its king calls himself \"the Voice of Heaven\" and is known for murdering villages.", "t": 2101}, {"name": "Cauberos", "kind": "nation", "note": "One of the five sovereign nations. Desert land of nomadic peoples travelling between oases, where the Merchant of Life/Death and the Mirageum operate.", "t": 2271}, {"name": "City of the Wild", "kind": "place", "note": "Host of the Feast of Oaths; streets filled with newlyweds, oath-swearers and incense-burning altars. Contains the Trifold Tavern, the Shave District, the Falls District and the Sky District.", "t": 147}, {"name": "Luminarkan Theater", "kind": "place", "note": "Tall tower fronted by a stone angel statue with outstretched wings; dark main hall lit by motes of starlight (\"mozelites\") that multiplied as Talent bladesang.", "t": 1234}], "gaps": ["Nation spellings corrected against the vault's canon: the source writes \"Calestus\" for Callestus. The source's \"Cauberos\" already matches canon.", "The source's \"Project Sync / Status Update Summary\" block treats the Arcanist Society and Umari's organization as corporate stakeholders; that framing was not carried into this record, only the facts.", "\"Urus\" appears only once, as the subject of books/tomes Ruel bought. Recorded as an asterum on the strength of the name (Uros) — the note itself says nothing about what or who Urus is.", "The note's map-deciphering table lists a check as \"Nix (faith/Aces/Vayune)\". \"Aces\" and \"Vayune\" are not explained anywhere in the note and may be garbled transcriptions; no entities were created for them.", "The note uses \"Nix\" and \"Nyx\" and \"Talent\" and \"Talon\" interchangeably; its own party list reads \"Talent/Talon\". Names are kept as the source spells them in beats and recap.", "Ruel is listed by the source as a Driftwood Kin party member (a changeling) but is not on the vault's player-character roster, so is recorded as npc. The Action Items block also writes \"@Guardian (Ruul)\" for work the narrative attributes to Talon — the relationship between Ruel, Ruul and Talon is unresolved in the source."], "iso": "2026-05-19", "pretty": "19 May 2026", "audio": true, "legendary": false, "n": 15}, {"slug": "ponzis-oath-and-feywild-quest", "title": "Campaign Session: Ponzi's Oath and Feywild Quest", "date": "05/19/2026 19:22", "runtime": "18min 25s", "nottaId": "dab239d2-5449-432a-bd6c-f6898069f7f9", "url": "https://app.notta.ai/7366972874555052032/dashboard/dab239d2-5449-432a-bd6c-f6898069f7f9", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 1105, "timecodesReliable": true, "subtitle": "Guilt set down, porcelain replaced with iron", "logline": "Ponzi trades vengeance for justice and loses a hand to gain one, and Rune Willow survives the Asterium's trial to be claimed by the Rose.", "recap": "Previously on…\nThe storm had been building for days — but none of them knew it would end like this.\nPonzi knelt before a goddess he had tried to bargain with, and found that guilt is not a debt you negotiate. It is a weight you choose to carry or set down. He set it down. He chose justice. And when he opened his eyes, his wings were white as bone, and where his infected hand had been — sand, and then flesh, and then something new.\nIn the quiet of the den, Talon followed a trail of glowing fungi into the dark, and found a scroll that would only open for him. Inside: a broken map to something called the Faewell. A fake aid. A warning dressed as a gift.\nAnd then the storm. The Seven Pillars of the Asterium, lightning splitting the sky, every offering burned to nothing — until the last one held. And from the top of the stone, wings spread wide against the full moon, came Aura Viab. Illuminarkan. He did not come to destroy them. He came to test them. He came to be fulfilled.\nThe fight was brutal. The elementals were relentless. And when it was over, light poured into the cracks — and the cracks were filled with iron.\nRune Willow stood in the moonbeam, sword raised, three years of running finally behind her. Accepted. Not by her own choosing — by something older and larger than choice. The Rose had claimed her.\nThey stood on the plateau in the rain, drenched and broken and more whole than they had ever been, while the city below rang its bells and sang its songs, not knowing what had just happened above them.\nThe storm is passing. The veil is thin. And somewhere in the dark, a broken map waits to be assembled.\nWhat happens next is up to them.", "dm": null, "party": ["Ponzi (Pontus)", "Nexi/Nexus", "Talon", "Rune (Rune Willow)", "Platy", "Tawn Phoenix"], "opens": "Wilder Temple / Dayune's approach.", "closes": "Atop the plateau above the city, party preparing to descend and celebrate; Rune and Ponzi at the plateau edge considering a reckless jump.", "cards": {"changed": {"headline": "Rune Willow is accepted by the Rose, and Ponzi walks holy", "detail": "Rune's porcelain was refused by molten holy iron and replaced — a major spiritual and factional shift after three years of avoiding the path. In the same stretch Ponzi's guilt was declared paid, he chose justice over vengeance, severed his infected hand, and came back with white wings and a hand of sand.", "t": 259}, "learned": {"headline": "The Faewell fragment is a warning dressed as a gift", "detail": "The scroll in the den opened only for Talon's oath and held a broken depiction of the Faewell — read as a broken fae gate. If assembled, the note says, it leads to a \"fake aid.\" Someone or something is laying a false trail.", "t": 75}, "who": {"headline": "Rune Willow", "detail": "The session belongs to her trial. She made the offerings, she ended the fight, she was the one the Rose claimed, and the whole back half of the session is the party sitting with what that cost her — three years spent running from it.", "t": 259}, "cost": {"headline": "A hand, three years, and most of the party's hit points", "detail": "Ponzi cut off his own infected hand. Rune carries the grief of three years she believes she wasted. Coming out of the Aura Viab fight one member sat at roughly 15 HP and another at about 24 against a max of 53, and the party chose to defer healing.", "t": 441}, "hanging": {"headline": "What is the Rose, and what does it now require of Rune?", "detail": "The Rose accepts individuals — Aura Viab, now Rune — but its nature, hierarchy, leadership and obligations are entirely unknown, as is its relationship to Uros, who chose Rune and apparently was not disappointed by the lost time.", "t": 131}}, "beats": [{"t": 0, "kind": "reveal", "title": "Ponzi kneels before Dayune", "line": "Ponzi goes to Dayune at the Wilder Temple, chooses to kneel rather than stand, and is told his guilt has been paid and he is called to walk holy — but he still seeks vengeance.", "facets": [["Decision", "The question posed: Vengeance or Justice? Ponzi agrees — he chooses justice."], ["Major NPC", "Dione asks if Ponzi will become what she wished he would be. \"Dayune\" and \"Dione\" appear to be used interchangeably — likely the same deity."], ["New lore", "The holy edicts — divine laws governing behaviour before Dayune. Kneeling before guilt is a prescribed act."], ["Environment", "An attendant makes clear Ponzi should not expect to stand by Dayune's throne room; he is instantly transported into it."]]}, {"t": 27, "kind": "magic", "title": "The severed hand and the white wings", "line": "Ponzi cuts off his infected hand; his wings turn brilliantly white and his hand regrows from the sand.", "facets": [["New lore", "Divine healing tied to the act of choosing justice over vengeance — the transformation is conditional on the spiritual choice."], ["Item", "Ponzi's Sand Hand: regrown from sand; can be heated. Ties to the \"Sandman\" nickname."]]}, {"t": 38, "kind": "social", "title": "Nexi's quiet oath", "line": "Nexi takes private time in contemplation and adds to his oath: to share warmth with the party and give his life for theirs.", "facets": [["Character", "No audience, no performance — a private, sincere deepening of commitment."], ["Decision", "\"Share the warmth with us and give his life for ours\" — aiming to solidify the bonds of the pact."]]}, {"t": 50, "kind": "magic", "title": "The pyrelings bond", "line": "The pyrelings join Nexi and redistribute across the party, changing colour for each bearer — Rune soft yellow, Talon aqua, Pontus deep red. The party now has three hearts.", "facets": [["New lore", "Pyrelings are small fire creatures that bond to party members and change colour based on the individual. Associated with Nyx."], ["Item", "The new pyrelings may leave Nyx to the party should the need arise."]]}, {"t": 62, "kind": "clue", "title": "The fungal trail in the den", "line": "Talon goes to the den wondering whether Zastus is expecting him, and follows a birdcomb trail of fungi into a small rocky tunnel leading deeper.", "facets": [["Environment", "Tiny mushroom light combines with curtains of glowing lichen."], ["Check", "He looks for signs — a book lying open about potential evil fungi."], ["Major NPC", "Zastus: unknown figure connected to the den and potentially to evil fungi. Identity, role and relationship to the party unsolved."]]}, {"t": 75, "kind": "item", "title": "The sealed scroll and the broken Faewell", "line": "Talon finds a sealed scroll inscribed \"What is your oath?\" that opens only when he speaks his oath — inside is a broken depiction of the Faewell.", "facets": [["Item", "Sealed Scroll: opens only when the holder speaks their oath."], ["New lore", "The Faewell — a broken depiction which, if assembled, leads to a \"fake aid.\" The note reads it as a broken fae gate."], ["Decision", "HOOK: the Faewell may be a trap or a test."]]}, {"t": 86, "kind": "scene", "title": "Offerings at the Seven Pillars", "line": "In a raging storm the party reaches the Seven Pillars of the Asterium; Ponzi disperses offerings at each pillar and demands the Asterium claim him or strike him down.", "facets": [["Environment", "Seven pillars used for divine offerings; lightning strikes and destroys offerings — a divine judgment mechanism."], ["Item", "Every offering is exploded by lightning — all rejected. Exception: the gross stone, given last, is not rejected."], ["New lore", "The Asterium — associated with the Seven Pillars, storms and lightning judgment."]]}, {"t": 99, "kind": "boss", "title": "Aura Viab atop the stone pillar", "line": "A robed creature with huge wings stands atop the stone pillar — Aura Viab, also called Aura Veil and Illuminarkan — and splits the clouds to reveal the full moon.", "facets": [["Major NPC", "Splits storm clouds, summons elementals, extremely difficult to hit."], ["Combat", "Tawn Phoenix and Talon are noted as too powerful for this fight — possibly held back or absent from combat."]]}, {"t": 115, "kind": "combat", "title": "The Asterium fight", "line": "Aura Viab summons elementals and the party struggles to hit him; a long, rough fight ensues on open, storm-lashed, lightning-struck ground.", "facets": [["Combat", "Terrain: open plateau and pillar tops during a raging storm."], ["Combat", "Tactics: Aura Viab summoned elementals; the party struggled to hit him directly."], ["Character", "Secret: he was not actually trying to kill the party — the fight was a trial and the fulfilment of his purpose."]]}, {"t": 131, "kind": "reveal", "title": "\"Accepted of the rose\"", "line": "Aura Viab declares \"This is what I was made for, and I am accepted of the rose\"; light pours into the party and fills their cracks with iron, Platy absorbs all three elementals, and Rune ends the fight accepted by the rose.", "facets": [["New lore", "The Rose — a divine or cosmic order that \"accepts\" individuals. Known accepted: Aura Viab, Rune Willow. Full nature, hierarchy and goals unsolved."], ["Combat", "Platy takes up all three elementals."], ["Character", "Rune declared readiness — \"this is what I was made for\" — and was accepted \"of the rose.\""]]}, {"t": 219, "kind": "scene", "title": "The plateau after the storm", "line": "The party stands drenched and injured atop the plateau as the storm reaches its zenith and begins to pass; Rune moves to where the moonbeam is strongest and holds her sword out.", "facets": [["Environment", "High ground above the city, roughly 75–90 feet up, above the sky district, with waterfalls below."], ["Environment", "Chunks of the exploded stone pillar serve as seats; the moon is still visible piercing the storm clouds."], ["Character", "Ponzi sits on a stone chunk; Nexi kneels or stands quietly behind Rune, about 15 feet away."]]}, {"t": 259, "kind": "magic", "title": "Rune Willow refined in molten holy iron", "line": "Rune Willow is accepted and refused by molten holy iron — her porcelain is refused and replaced by iron — and the stone pillar that held the iron explodes.", "facets": [["Item", "Molten Holy Iron: refuses porcelain, fills cracks, refines the bearer. Source: exploded from the stone pillar at the Asterium; chunks remain on the plateau."], ["Character", "Spent three years hiding from her destiny (the Rose/Uros connection); now accepted."]]}, {"t": 441, "kind": "rule", "title": "Counting the damage", "line": "Multiple members are heavily injured — one at roughly 15 HP, another at about 24 HP against a max of 53 — and the party decides to wait to heal and observe first.", "facets": [["Check", "One member was above max earlier due to temporary HP from Nyx's abilities at the start of the fight."], ["Decision", "Healing deferred; observe first."]]}, {"t": 558, "kind": "lore", "title": "The veil is thinner", "line": "The party sits in somber silence reflecting on what happened; the veil is thinner, abilities feel heightened by their oaths, and some feel an unprecedented nearness to Nasdarum.", "facets": [["New lore", "Nasdarum — a distant, impersonal entity (deity or cosmic force) whose direct influence was felt during the Asterium fight."], ["Environment", "The heavier rain breaks to a light, constant rain with distant thunder."], ["New lore", "The \"individualist era\" referenced in relation to the party's oaths is not explained."]]}, {"t": 650, "kind": "plan", "title": "The city rings its bells", "line": "The city beneath the plateau erupts in music, revelry and temple bells, breaking the somber moment; the party decides to descend and celebrate, and Ponzi is dubbed \"Sandman\".", "facets": [["Decision", "Objective: find drink, friends and conversation; process the session's events."], ["Character", "Ponzi is dubbed \"Sandman\" for his sand-regenerated hand."]]}, {"t": 757, "kind": "social", "title": "Three years, and a reframe", "line": "Nexi walks up to Rune and says \"I really thought that was that\"; Rune reflects that she wasted three years, and Nexi offers her another way to see it.", "facets": [["Character", "\"What if it was in the hiding that you found yourself prepared to accept it right now?\""], ["Character", "\"I feel like I wasted three years ago.\" — grief over avoidance."], ["New lore", "\"It didn't seem as though Uros was as disappointed about the loss of time as you might be.\""]]}, {"t": 914, "kind": "social", "title": "Talon calls for celebration", "line": "Talon encourages the party to unburden themselves and celebrate — find drink, find friends, find conversation — and is assigned as chaperone for the reckless plan.", "facets": [["Character", "\"Unburden yourself. I'm with Talon. Let's celebrate this moment. Find drink, find friends, and find conversation.\""], ["Decision", "Talon/Tanner assigned as babysitter/chaperone."]]}, {"t": 967, "kind": "magic", "title": "A hand offered, and iron warmed", "line": "Ponzi lays on hands for one charge, offers Rune his hand as he once did in despair, and then heats the iron on the ground until it radiates heat and takes a blackened glow.", "facets": [["Check", "Ponzi uses 1 charge of Lay on Hands, targeting Rune on the ground."], ["House ruling", "The iron is full iron, not adamantium."], ["Character", "\"I offer my hand, because I did that before, and it was at a peak moment of despair, but I'll offer my hand again with that same smile.\" She takes it."]]}, {"t": 1064, "kind": "plan", "title": "The reckless jump", "line": "Rune says to do something reckless; Ponzi walks to the plateau edge and looks over a 75–90 foot drop, and Nexi offers featherfall for the jump. The session ends there.", "facets": [["Decision", "Nexi has Featherfall available and offers it for the planned jump."], ["Environment", "Plateau height 75–90 feet, above the sky district, with waterfalls below."], ["House ruling", "Fall damage rules referenced but not resolved in transcript."]]}], "threads": [{"u": "hi", "q": "What is the Rose? Who leads it? What are its obligations for Rune and Aura Viab?", "t": 131}, {"u": "hi", "q": "What did Rune avoid learning in her three lost years, and what catching up must be done?", "t": 811}, {"u": "hi", "q": "What does Dione specifically wish Ponzi to become, and what does walking holy entail going forward?", "t": 14}, {"u": "md", "q": "What is the Faewell? Why is the depiction broken, and what is the \"fake aid\" it leads to?", "t": 75}, {"u": "md", "q": "Who is Zastus? What is his connection to the fungi and the den — ally or threat?", "t": 62}, {"u": "md", "q": "What does it mean that the pyrelings may leave Nyx to the party? What is Nyx's role?", "t": 50}, {"u": "md", "q": "What is Nasdarum's direct interest in the party, and what did the influence during the Asterium event signify?", "t": 585}, {"u": "lo", "q": "Will Rune and Ponzi jump off the plateau, and what are the consequences?", "t": 1064}], "next": ["Resolve the plateau jump (featherfall ready — Nexi has it)", "Enter the city and find a place to celebrate and decompress", "Rune: begin pursuing Rose/Uros knowledge — find a contact or text", "Talon: investigate the Faewell fragment — do NOT assemble blindly", "Talon: return to the den and determine Zastus's role and the fungi threat", "Full party: heal up before any further action", "Nexi: clarify pyreling/Nyx relationship and what \"leaving Nyx to the party\" means", "Ponzi: explore new divine abilities and obligations (walking holy, white wings, sand hand)"], "entities": [{"name": "Ponzi", "kind": "pc", "note": "Also written \"Pontus\" in this note. Knelt before Dayune, chose justice over vengeance, severed his infected hand and gained white wings and a hand of sand; dubbed \"Sandman\".", "t": 0, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Rune Willow", "kind": "pc", "note": "Made the offerings at the Seven Pillars, ended the Aura Viab fight, and was accepted by the Rose — her porcelain refused and replaced by molten holy iron after three years of avoiding the path.", "t": 259}, {"name": "Talon", "kind": "pc", "note": "Spelled \"Talon\" and once \"Talon/Tanner\". Followed the fungal trail in the den and opened the sealed scroll with his oath, finding the broken Faewell depiction. Noted as too powerful for the Asterium fight.", "t": 62, "reveal": "Talon's real name is Tanner."}, {"name": "Nyx", "kind": "pc", "note": "Written throughout this note as \"Nexi\" and \"Nexus\"; the note's own Project Sync block heads the workstream \"Nyx/Nexus\". Deepened the pact oath, holds the pyrelings, and offers featherfall for the plateau jump.", "t": 38, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Platy", "kind": "npc", "note": "Listed by the source in the party roster. Took up all three of Aura Viab's summoned elementals during the fight. Not on the vault's player-character roster, so recorded as npc pending confirmation.", "t": 131}, {"name": "Tawn Phoenix", "kind": "npc", "note": "Listed by the source in the party roster as present but too powerful for the Asterium fight; held back during combat. Not on the vault's player-character roster, so recorded as npc pending confirmation.", "t": 115}, {"name": "Dayune / Dione", "kind": "deity", "note": "Deity presiding over a throne room reached by divine vision. Declared Ponzi's guilt paid and called him to walk holy, demanding a choice between vengeance and justice. The note says the two spellings are likely the same deity.", "t": 0}, {"name": "Nasdarum", "kind": "deity", "note": "Described by the note as a distant, impersonal entity — deity or cosmic force — whose direct influence the party felt during the Asterium fight. Several members had never felt nearness to Nasdarum before.", "t": 585}, {"name": "Aura Viab", "kind": "creature", "note": "Robed winged being atop the stone pillar, also called \"Aura Veil\" and \"Illuminarkan\". Split the storm clouds, summoned elementals, and revealed the fight was his purpose: \"This is what I was made for, and I am accepted of the rose.\"", "t": 115}, {"name": "Zastus", "kind": "npc", "note": "Unknown figure connected to the den and potentially to the evil fungi. Talon wondered whether Zastus was expecting him. Identity, role and relationship to the party unsolved.", "t": 62}, {"name": "Pyrelings", "kind": "creature", "note": "Small fire creatures that bond to party members and change colour for each bearer — Rune soft yellow, Talon aqua, Pontus deep red. Associated with Nyx; may leave Nyx to the party if needed.", "t": 50}, {"name": "The Asterium", "kind": "asterum", "note": "The source's FACTIONS section lists this as \"a divine institution or force\" tied to the Seven Pillars that tests worthiness through lightning judgment. Reclassified as an asterum — an angelic patron figure — not a faction. Source spelling \"Asterium\".", "t": 86}, {"name": "Uros", "kind": "asterum", "note": "The source's FACTIONS section lists Uros as \"a faction or divine force\" that Rune was drawn to but avoided for three years. Reclassified as an asterum — the angelic patron who chose Rune and \"was not as disappointed about the loss of time as you might be\".", "t": 792}, {"name": "The Rose", "kind": "faction", "note": "A divine or cosmic order that \"accepts\" individuals. Known accepted: Aura Viab and, newly, Rune Willow. Nature, hierarchy and goals unsolved; the note also writes it as \"Uros/Uros of the rose\".", "t": 131}, {"name": "Driftwood Kin", "kind": "faction", "note": "The party. The note records no explicit Driftwood Kin activity this session, but flags the spiritual transformations as possible internal milestones.", "t": null}, {"name": "Wilder Temple", "kind": "place", "note": "Site of Ponzi's divine vision; an attendant enforces protocol before Dayune's throne room, which is reached by vision or spiritual transport.", "t": 0}, {"name": "The Den", "kind": "place", "note": "Talon's investigation site — a birdcomb trail of fungi leads to a small rocky tunnel going deeper, lit by tiny mushroom light and curtains of glowing lichen.", "t": 62}, {"name": "The Seven Pillars of the Asterium", "kind": "place", "note": "Storm-exposed outdoor site of seven pillars used for divine offerings, where lightning destroys what is rejected. One large pillar held the holy iron and exploded during the fight.", "t": 86}, {"name": "The Plateau (Above the City)", "kind": "place", "note": "High ground roughly 75–90 feet above the city, at the foot of the Sky District, with waterfalls below and chunks of exploded stone pillar on the ground.", "t": 219}, {"name": "The Faewell", "kind": "item", "note": "A broken depiction found inside Talon's sealed scroll, interpreted as a broken fae gate. If assembled it leads to a \"fake aid\" — possibly a trap or a test.", "t": 75}, {"name": "Sealed Scroll", "kind": "item", "note": "Found by Talon in the den. Inscribed \"What is your oath?\" and opens only when the holder speaks their oath. Contains the broken Faewell depiction.", "t": 75}, {"name": "The Gross Stone", "kind": "item", "note": "Ponzi's last offering at the Seven Pillars and the only one not destroyed by lightning. Its acceptance triggered Aura Viab's appearance; the nature of the stone is unclear.", "t": 99}, {"name": "Molten Holy Iron", "kind": "item", "note": "Refuses porcelain, fills cracks and refines the bearer. Exploded from the stone pillar at the Asterium and transformed Rune Willow; chunks remain on the plateau. Ruled full iron, not adamantium.", "t": 259}, {"name": "Ponzi's Sand Hand", "kind": "item", "note": "Regrown from sand after Ponzi severed his infected hand. Can be heated — it made the ground iron radiate heat with a blackened glow.", "t": 27}], "gaps": ["The source's FACTIONS & POWER STRUCTURES block lists \"The Asterium\" and \"Uros\" as factions. Both are Asterums — angelic patron figures — not factions, and have been reclassified here. Source spellings kept: \"Asterium\", \"Uros\".", "No sovereign nation is named anywhere in this note, so no nation entities were recorded and no nation spellings needed correcting.", "This 18-minute recording is a compressed narration of the session rather than live play, so the timecodes sit very close together early on — nine distinct moments inside the first two minutes. They rise monotonically in narrative order, none exceeds the 18min 25s runtime, and they match the transcript pane exactly, so they are recorded as reliable.", "The source lists a faction literally named \"Hello\" at 00:09:45, described as \"a distant, impersonal cosmic entity or deity\" — the same timecode and description the note gives for Nasdarum. Treated as a transcription artefact for Nasdarum; no \"Hello\" entity was created.", "The note writes Nyx as \"Nexi\" and \"Nexus\" and refers to this character as \"he\", while its own Project Sync block heads the workstream \"Nyx/Nexus\". Recorded as Nyx on that basis, but the identification is the note's, not independently confirmed.", "Platy and Tawn Phoenix are listed by the source in the party roster but are not on the vault's player-character roster, so both are recorded as npc."], "iso": "2026-05-19", "pretty": "19 May 2026", "audio": true, "legendary": false, "n": 14}, {"slug": "festival-planning-night-before", "title": "Festival Planning and Night Before Activities", "date": "05/05/2026 19:43", "runtime": "4h 18min 7s", "nottaId": "62237256-72f5-4ae3-adec-91755e1e0178", "url": "https://app.notta.ai/7366972874555052032/dashboard/62237256-72f5-4ae3-adec-91755e1e0178", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 15487, "subtitle": "Iron veins in porcelain beneath the storm", "logline": "The party spent the night before the Festival of Oaths at the Trifold Tavern, swore oaths at their Esterum temples, then fought Aurovail at the Seven Pillars.", "recap": "Previously on our campaign...\nThe Festival of Oaths arrived with storm and revelation. As lightning split the sky above the Seven Pillars, Rune Willow stood defiant before the assembled might of the Esterum, her carefully gathered offerings scattered by divine judgment—all save one. The stone of Uros remained, and with it came Aurovail, the terrible angel of the Unmaker.\nWhat began as a test of worthiness became a crucible of transformation. Ponzi, marked by justice, wielded his new sand hand against elemental fury. Nyx, bound by deeper oaths, channeled protective flames that danced between his companions. Talon, armed with forbidden knowledge of Feywild gates, struck with bardic inspiration. And Rune Willow, no longer hiding from her destiny, met divine fire with arcane storm.\nWhen the battle's crescendo came, iron flowed like liquid starlight into porcelain cracks, and Aurovail's voice rang across the storm-torn plains: \"Witness the accepted of Uros!\" The Unmaker had chosen his vessel, and the Driftwood Kin stood forever changed beneath the watching moon.", "dm": null, "party": ["Ponzi (rogue)", "Nyx (paladin)", "Talon (bard)", "Rune Willow (wizard/warlock)"], "opens": "Night before the festival at the tavern.", "closes": "Rune Willow accepted by Uros after battle with Aurovail.", "cards": {"changed": {"headline": "Rune Willow was accepted by Uros", "detail": "The Uros pillar exploded and iron veins filled the cracks in Rune Willow's porcelain body; Aurovail declared \"Witness the accepted of Uros\" — she is officially chosen by the Unmaker. She was restored to half hit points and regained her highest spell slot mid-trial. The whole party came away divinely backed: Ponzi as \"arm of justice\" for Dion, Nyx as enhanced protector through Aces, Talon as knowledge-seeker for Zastas.", "t": 14692}, "learned": {"headline": "The Feywild holds hyperbolic counterparts of the corruption", "detail": "A fungi researcher studied material plane specimens by observing their extreme Feywild counterparts — Feywild versions are \"hyperbolic\", more severe, drastic and easily observable, so you study the extremes to understand the mundane versions. Talon's torn map, once reconstructed, reveals a Feywild gate location for exactly this: studying extreme fungal counterparts and countering Vesh.", "t": 981}, "who": {"headline": "Rune Willow, who stopped hiding", "detail": "She went into the festival believing tomorrow might be her last day as-is, then demanded recognition at the Seven Pillars — \"My name is Rune Willow... where is my blessing?\" and \"I'm done hiding from him\" — and fought back against the divine test instead of accepting unmaking. Aurovail's trial was aimed at her, and the session ended on her acceptance.", "t": 9218}, "cost": {"headline": "Every offering burned but one, and three gifts left at three temples", "detail": "Lightning obliterated all of Rune Willow's assembled offerings except the magic-infused stone at the Uros pillar. Ponzi lost his cursed flesh hand at Dion's temple. Nyx buried his treasured bronze hammer at the Aces hearth. Talon left a potion of greater healing in the Deep Chapel. The sand hand also loses sand when contributing to divine rituals and may fail if the oath is broken.", "t": 8766}, "hanging": {"headline": "The Feywild gate map is still in pieces", "detail": "The map was deliberately misassembled and needs proper reconstruction before it will reveal the gate coordinates. Urgency is HIGH — the Vash threat continues growing — and reassembly is nontrivial with a risk of misrouting, plus time dilation and environmental extremes to prepare for.", "t": 8122}}, "beats": [{"t": 0, "kind": "scene", "title": "Last night at the Trifold Tavern", "line": "The party gathered at the Trifold Tavern for the final night before the Festival of Oaths.", "facets": [["Character", "Rune Willow expressed fear about potential unmaking, believing tomorrow might be her last day"], ["Character", "Ponzi experienced nightmares and visions related to his deceased wife Rose and the coin from Dion"], ["Character", "Nyx provided comfort and healing to distressed party members"], ["Character", "Talon studied his fungal research book throughout the night"]]}, {"t": 251, "kind": "lore", "title": "The storm grows as the veil thins", "line": "The festival storm grows throughout the day as the veil becomes thinner.", "facets": [["New lore", "Lords of creation's power leaks through, crescendos at nightfall"], ["New lore", "Pattern follows the storm's natural progression"]]}, {"t": 929, "kind": "dread", "title": "Vash's northern expansion", "line": "War with the Northern Lions is inevitable and the fungal corruption keeps spreading beyond Caramel.", "facets": [["Threat", "Historian's help needed for conflict"], ["Threat", "Party needs enhanced power to face the threat level"], ["Threat", "Time pressure increasing"]]}, {"t": 981, "kind": "lore", "title": "Study the extremes to understand the mundane", "line": "A fungi researcher studied material plane specimens by observing their extreme Feywild counterparts.", "facets": [["New lore", "Feywild versions are \"hyperbolic\" — more severe, drastic, easily observable"], ["New lore", "Method: study extremes to understand mundane versions"]]}, {"t": 1151, "kind": "clue", "title": "Rose's adamantine sheath", "line": "Rose had an adamantine-ornamented dagger sheath — metal of use, not beauty — and stopped mid-attack as if receiving divine command.", "facets": [["Check", "Ponzi's 25 perception: detailed analysis of Rose's dagger sheath materials"], ["Clue", "Ponzi never saw her worship any Esterum, but evidence suggests connection"], ["Clue", "Mystery of her sudden stop during the robbery attempt"]]}, {"t": 3911, "kind": "travel", "title": "Festival day: each to their own temple", "line": "On festival day the party split, each member going to their Esterum for a determination.", "facets": [["Decision", "Ponzi: petition Dion for judgment and direction"], ["Decision", "Nyx: deepen the protective oath at the Aces hearth"], ["Decision", "Talon: delve for Zastas-guided knowledge to counter Vesh's fungal threat"], ["Decision", "Rune Willow: seek determination from the Esterum — acceptance vs. unmaking"]]}, {"t": 4798, "kind": "lore", "title": "Obsidian sand of time", "line": "Black sand that flows with the passage of time, the marker of Dion's blessing.", "facets": [["New lore", "Used in holy symbols and judgment halls"], ["New lore", "Can form replacement body parts for those chosen by Dion"], ["Check", "Multiple religion checks identified the obsidian sand's properties and significance"]]}, {"t": 4902, "kind": "social", "title": "Kneeling at the guilty stone", "line": "Ponzi chose to kneel at the \"guilty\" stone and undergo the judgment ritual under Dion's priest.", "facets": [["Major NPC", "Dion's Priest — broad-shouldered, heavy black cloak with green shimmer, guide for judgment rituals"], ["Quote", "\"He will have no hiding\" — the priest, regarding Dion's judgment"], ["Major NPC", "The priest was fearful after witnessing Ponzi's transformation"]]}, {"t": 5283, "kind": "social", "title": "Ponzi chooses justice over vengeance", "line": "Ponzi confronted Dion about taking everything from him, then forsook vengeance in favor of serving justice for Rose's death.", "facets": [["Quote", "\"I will serve you\" — acceptance of the divine role"], ["Decision", "Commit to truth-telling and exposing lies; honor Rose's memory through just action"], ["Character", "Wings manifested as white plumage during the vision; the priest witnessed and recoiled"], ["Quest", "ACTIVE: Justice for Rose — must serve Dion's justice, not personal revenge"]]}, {"t": 6108, "kind": "item", "title": "The sand hand", "line": "Ponzi lost his cursed flesh hand and gained an articulated obsidian black-sand construct in its place, becoming an \"arm of justice\".", "facets": [["Item", "Reorients in any direction, enhanced dexterity, can absorb and conceal objects in the palm (e.g. a coin)"], ["Item", "Pain immunity on blade contact"], ["Item", "Tied to Dion's power, may fail if the oath is broken; loses sand when contributing to divine rituals"], ["House ruling", "Divine transformation mechanics: a functional sand appendage with enhanced abilities"]]}, {"t": 6559, "kind": "social", "title": "My warmth be their warmth", "line": "Nyx deepened his oath at the Aces hearth, vowing to guard Rune Willow, Ponzi and Talon as chosen family.", "facets": [["Quote", "\"May my warmth be their warmth and my life for theirs\""], ["Character", "Buried his treasured bronze hammer at the hearth as ultimate sacrifice"], ["Combat", "Enhanced lay-on-hands and protective abilities"]]}, {"t": 6894, "kind": "item", "title": "Three piratelings", "line": "Nyx's oath produced three small flames, originating from his glaive, each connected to a party member.", "facets": [["Item", "Colors: soft yellow (Rune Willow), blue-green (Talon), pink (Ponzi)"], ["Item", "A second account of the same moment gives the colors as soft warm yellow (Rune Willow), aqua (Talon), deep red (Ponzi)"], ["Item", "Piratelings can lead to lost party members"], ["Character", "Represents deepened commitment and supernatural connection across the Driftwood Kin"]]}, {"t": 7355, "kind": "social", "title": "The Deep Chapel priest", "line": "An elderly man studying a gigantic tome acknowledged Talon's delving with an understanding nod.", "facets": [["Major NPC", "Deep Chapel Priest — guardian of Zastas temple knowledge"]]}, {"t": 7508, "kind": "social", "title": "Knowledge for the common people", "line": "Talon committed to using power for \"common people and those being kept down\", focused on helping the people of Caramel and fighting the corruption.", "facets": [["Character", "Exchanged a valuable potion for knowledge"], ["Decision", "Upon affirming an altruistic oath — knowledge to benefit common folk and allies — the scroll's seal melted"], ["Quest", "ONGOING: Caramel Investigation — are the residents under fungal corruption captive, and can they be saved?"]]}, {"t": 7641, "kind": "rule", "title": "A 23 investigation opens the hidden chamber", "line": "Talon followed subtle fungal cues into a hidden lichen-lit chamber and discovered a sealed scroll.", "facets": [["Check", "Talon's 23 investigation: discovered the hidden chamber and the map's significance"], ["Environment", "Accessible through a narrow rocky tunnel requiring squeezing; glowing lichen provides violet light"], ["Environment", "Contains scrolls on mushroom beds (uncorrupted fungi)"], ["Item", "Left a potion of greater healing as a reciprocal gift"]]}, {"t": 8122, "kind": "item", "title": "The torn Feywild gate map", "line": "The scroll held a deliberately misassembled map that, properly reconstructed, reveals a Feywild gate location.", "facets": [["Item", "Torn and reassembled map showing a Celtic knot circle with vibrant forest"], ["Item", "Purpose: locate a gate to the Feywild for enhanced power against Vash and for studying extreme fungal counterparts"], ["Quest", "ACTIVE: Feywild Gate Assembly — map acquired, needs puzzle-solving; urgency HIGH"], ["Decision", "Could shift the balance of power against Vash and open a new realm for exploration and allies"]]}, {"t": 8766, "kind": "scene", "title": "Lightning takes every offering but one", "line": "Rune Willow placed her collected gifts at each Esterum pillar during the raging storm, and lightning destroyed all of them except the magic-infused stone at the Uros pillar.", "facets": [["Environment", "Seven Pillars: tall pale stone pillars on the plains above Vattenheim"], ["Environment", "Each inlaid with holy metal veins: gold, iron, rose gold, adamantine, mithril, silver, bronze"], ["Environment", "Central dais cracked and lifted during Aurovail's manifestation"], ["Character", "She had acknowledged tomorrow could be her last day as-is and resolved to seek a decisive outcome"]]}, {"t": 9218, "kind": "social", "title": "Where is my blessing?", "line": "Rune Willow demanded recognition from the Esterum despite her fear.", "facets": [["Quote", "\"My name is Rune Willow... where is my blessing?\""], ["Quote", "\"I'm done hiding from him\" — character growth moment"], ["Character", "Fought back against the divine test instead of accepting unmaking"]]}, {"t": 9397, "kind": "boss", "title": "Aurovail manifests", "line": "Aurovail, a Luminarchan angel of the Unmaker, appeared — a massive winged figure in robes with luminescent skin of swirling magic — initially hostile, summoning elementals and attacking the party.", "facets": [["Major NPC", "Role: agent/angel of Uros the Unmaker, tester of worthiness"], ["Major NPC", "Motivation: determine if Rune Willow is worthy of Uros's acceptance"], ["New lore", "Luminarchan Order: angels serving the Unmaker, reality-warping, acting as divine agents and testers"], ["Threat", "Angels of the Unmaker are now aware of the party; Aurovail's approval may bring other divine tests"]]}, {"t": 10147, "kind": "magic", "title": "Divine enhancements come online", "line": "The gifts sworn that day all took effect at once during the trial.", "facets": [["Combat", "Talon: augmented bless (no concentration), double bardic inspiration"], ["Combat", "Nyx: 21 temp HP to all, doubled lay-on-hands effectiveness"], ["Combat", "Ponzi: uncanny dodge for party members, judgment mark sneak attack"], ["Combat", "All: +1d4 to saves and attacks from bless"]]}, {"t": 10568, "kind": "combat", "title": "The Aurovail battle", "line": "A Luminarchan angel with AC 18+, massive HP and multiple legendary actions, fought across cracked pillars under altered gravity.", "facets": [["Combat", "Disintegrating Iron (35 force damage); Elemental Fury (24 fire damage to all)"], ["Combat", "Arcane Brilliance (blinds, disadvantage on saves/attacks); prism lance (radiant); arcane fist (force)"], ["Combat", "Elemental summoning (earth, fire, water elementals); Luminous Tether links party members for shared damage"], ["Combat", "Talon's Command \"Halt\" immobilized all elementals for a round; effective use of Shatter"], ["Environment", "Terrain: cracked pillars, altered gravity (triple jump, feather fall)"]]}, {"t": 13893, "kind": "rule", "title": "Combat rulings", "line": "The table settled how the angel's tether, wards and the altered gravity worked.", "facets": [["House ruling", "Luminous tether: shared radiant damage between linked targets"], ["House ruling", "Elemental immunity: Aurovail immune to damage while elementals alive"], ["House ruling", "Gravity alteration: triple jump distance, automatic feather fall"], ["House ruling", "Haste effect granted to Rune Willow during the climactic moment"], ["Combat", "Effective tactic: eliminate the summoned elementals first to strip the Luminarchan's protective interference, then concentrate fire"]]}, {"t": 14692, "kind": "reveal", "title": "Witness the accepted of Uros", "line": "The Uros pillar exploded, iron veins filled Rune Willow's porcelain cracks, and Aurovail declared her accepted.", "facets": [["Quote", "\"Witness the accepted of Uros\""], ["Item", "Iron-Veined Porcelain: restored to half hit points, highest spell slot restored"], ["Environment", "Seven Pillars permanently altered (Uros pillar destroyed); gravity effects may persist in the area"], ["Character", "Divine manifestation witnessed by any observers"]]}, {"t": 14916, "kind": "combat", "title": "Wail of the Grave clears the field", "line": "Ponzi's Wail of the Grave destroyed all the elementals simultaneously and Aurovail shifted from enemy to ally/tester.", "facets": [["Combat", "Rune Willow's acceptance triggered mid-combat power restoration"], ["Combat", "Rune Willow channeled Nyx's flame, Ponzi's poison vial and Talon's splinter dart into empowered strikes"], ["Combat", "Party coordination with divine gifts and bardic inspiration"], ["Combat", "Radiant damage underperformed on the angelic target; non-radiant (force/sonic/elemental) and control effects proved valuable"]]}], "threads": [{"u": "hi", "q": "Can the torn Feywild gate map be correctly reassembled to reveal the gate coordinates?", "t": 8122}, {"u": "hi", "q": "Are the people of Caramel captive under the fungal corruption, and can they be saved?", "t": 7508}, {"u": "hi", "q": "How does the party meet Vash's northern expansion and the coming war with the Northern Lions?", "t": 929}, {"u": "md", "q": "What was Rose's true connection to the Esterum, given the adamantine sheath and her sudden stop?", "t": 1151}, {"u": "md", "q": "Will Ponzi hold to Dion's justice rather than regress to vengeance — and what do his recurring coin omens mean?", "t": 5821}, {"u": "md", "q": "Was Rune Willow's prior vision of the mirror shattering and blue light a fear or an omen?", "t": null}, {"u": "lo", "q": "What becomes of the Urbanist Society's missing member and the commitments made to help \"low tide\"?", "t": 22}], "next": ["Assemble the Feywild Gate Map — critical for gaining power against Vash; sequence reassembly, validate against known geography, identify ingress/egress anchors.", "Plan the Caramel investigation — determine if the Feywild route is viable for rescue.", "Explore divine abilities — test and understand the new powers and their limitations.", "Investigate Rose's connection — follow up on the adamantine dagger clues.", "Prepare for the Vash conflict — war with the Northern Lions is approaching.", "Maintain divine oaths — ensure party actions align with sworn purposes or risk losing the divine gifts.", "@Talon: reconstruct the torn map and propose a safe route and timeline for a reconnaissance foray; continue the fungal research plan and list required samples, tools and safeguards.", "@Nyx: draft protection protocols (activation rules, fallback signals) and prepare a non-radiant damage kit for arcane/angelic engagements."], "entities": [{"name": "Rune Willow", "kind": "pc", "note": "Wizard/warlock. Feared unmaking, demanded a blessing at the Seven Pillars, and was proclaimed \"Accepted of Uros\"; porcelain cracks now reinforced with iron veins.", "t": 14692}, {"name": "Ponzi", "kind": "pc", "note": "Rogue, also given as Ponzi (Asher). Knelt at the \"guilty\" stone, chose justice over vengeance, lost his cursed flesh hand and became Dion's \"arm of justice\".", "t": 5283, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Nyx", "kind": "pc", "note": "Paladin. Swore a deeper hearth oath — \"my warmth be their warmth; my life for theirs\" — buried his bronze hammer and gained three piratelings.", "t": 6559, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Talon", "kind": "pc", "note": "Bard. Delved the Deep Chapel, affirmed an altruistic oath and secured the torn Feywild gate map for Zastas.", "t": 7641, "reveal": "Talon's real name is Tanner."}, {"name": "Aurovail", "kind": "npc", "note": "Luminarchan angel, massive winged figure in robes with luminescent skin of swirling magic; agent of Uros the Unmaker and tester of worthiness. Declared Rune Willow accepted and departed after the battle. Also spelled Auroveil.", "t": 9397}, {"name": "Dion's Priest", "kind": "npc", "note": "Broad-shouldered, heavy black cloak with green shimmer; guide for judgment rituals. Fearful after witnessing Ponzi's transformation. \"He will have no hiding.\"", "t": 4902}, {"name": "Deep Chapel Priest", "kind": "npc", "note": "Elderly man studying a gigantic tome; guardian of Zastas temple knowledge. Acknowledged Talon's delving with an understanding nod.", "t": 7355}, {"name": "Uros", "kind": "asterum", "note": "The Unmaker, master of magic and arcane forces. Claimed Rune Willow through Aurovail. Esterum.", "t": null}, {"name": "Dion", "kind": "npc", "note": "The Judge, dispenser of justice and divine judgment. Also given as Dayan. Ponzi's patron.", "t": null}, {"name": "Aces", "kind": "npc", "note": "The Tender, protector and nurturer. Also given as Aesus. Nyx's hearth.", "t": null}, {"name": "Zastas", "kind": "npc", "note": "The Delver, seeker of hidden knowledge. Talon's patron.", "t": null}, {"name": "Rose", "kind": "npc", "note": "Ponzi's deceased wife. Carried an adamantine-ornamented dagger sheath and stopped mid-attack as if receiving divine command; Ponzi never saw her worship any Esterum.", "t": 1151}, {"name": "Vash", "kind": "npc", "note": "Expanding north; war with the Northern Lions inevitable and fungal corruption spreading. Also spelled Vesh.", "t": 929}, {"name": "The Esterum Hierarchy", "kind": "faction", "note": "Eight Esterum, each with specific temples, rituals and divine agents. Also spelled Asterum.", "t": null}, {"name": "Luminarchan Order", "kind": "faction", "note": "Angels serving the Unmaker; reality-warping divine agents and testers. Aurovail represents this faction's power.", "t": 9397}, {"name": "Northern Lions", "kind": "faction", "note": "War with them is described as inevitable.", "t": 929}, {"name": "Urbanist Society", "kind": "faction", "note": "Missing member; led by Descartes and Farsighted. Commitments made to help \"low tide\"; other urbanists need more time to decide.", "t": 22}, {"name": "Driftwood Kin", "kind": "faction", "note": "The party. Now holds divine legitimacy, enhanced abilities and supernatural bonds between members.", "t": null}, {"name": "Trifold Tavern (Fallen Roost)", "kind": "place", "note": "Where the party spent the night before the Festival of Oaths.", "t": 0}, {"name": "Wilder Temple", "kind": "place", "note": "Four levels dedicated to eight Esterum. Third level: Dion (judge) and Aydas (dying spouse). First level: Aces and Buying (tender) — a simple garden with hearth. Circular holy spaces with specific religious artifacts.", "t": 4379}, {"name": "Deep Chapel", "kind": "place", "note": "Zastas temple with a hidden chamber beneath it, reached through a narrow rocky tunnel; glowing lichen gives violet light, scrolls rest on beds of uncorrupted fungi.", "t": 7741}, {"name": "Seven Pillars of Esterum", "kind": "place", "note": "Tall pale stone pillars on the plains above Vattenheim, each inlaid with holy metal veins: gold, iron, rose gold, adamantine, mithril, silver, bronze. Central dais cracked and lifted; the Uros pillar was destroyed.", "t": 8838}, {"name": "Caramel", "kind": "place", "note": "Residents under fungal corruption; their fate is unknown and a Feywild connection is possible.", "t": 7508}, {"name": "Feywild", "kind": "place", "note": "Holds \"hyperbolic\" counterparts of material plane fungi; reachable via the gate shown on Talon's map.", "t": 981}, {"name": "Ponzi's Sand Hand", "kind": "item", "note": "Obsidian sand replacement for the lost flesh hand: reorients in any direction, enhanced dexterity, absorbs objects into the palm. Tied to Dion's power, may fail if the oath is broken; loses sand when contributing to divine rituals.", "t": 6108}, {"name": "Feywild Gate Map", "kind": "item", "note": "Talon's torn map showing a Celtic knot circle with vibrant forest; locates a gate to the Feywild. Needs proper reassembly to function.", "t": 8122}], "gaps": ["Proper nouns are spelled inconsistently within the source itself and both spellings are preserved here: Esterum/Asterum, Dion/Dayan, Aces/Aesus, Vash/Vesh, Aurovail/Auroveil, piratelings/pyratelings.", "The pirateling colors are given twice and disagree: \"blue-green (Talon), pink (Ponzi)\" in one section, \"aqua (Talon), deep red (Ponzi)\" in another. Rune Willow's is yellow in both.", "No DM is named anywhere in the source.", "Several sections are marked \"Throughout\" instead of carrying a timecode — The Esterum Hierarchy, Divine Backing Gained, Divine Expectations, Party Status Elevation — so those facts carry no t.", "Rune Willow's prior vision of a mirror shattering and blue light is referenced only as something to debrief; the vision itself is never described or timecoded.", "Party classes are given only in the SESSION INFO block; no levels, HP totals or ability scores appear anywhere."], "iso": "2026-05-05", "pretty": "5 May 2026", "audio": true, "legendary": false, "timecodesReliable": true, "n": 13}, {"slug": "journey-to-vattenheim-misty-fortress", "title": "Campaign Adventure: Journey to Vattenheim and the Misty Fortress", "date": "05/02/2026 19:23", "runtime": "3h 12min 18s", "nottaId": "9ff7c864-cdfa-4dd7-83e1-fbca0ee7964b", "url": "https://app.notta.ai/7366972874555052032/dashboard/9ff7c864-cdfa-4dd7-83e1-fbca0ee7964b", "template": "D&D Session Noters: V3", "hasTimecodes": true, "timecodesReliable": true, "durationSec": 11538, "subtitle": "One yes, three maybes, a storm coming", "logline": "The Driftwood Kin clean up for the Feast of Oaths, drink their way into the Arcanists' pocket dimension, and pitch a sanctuary city — Ude alone says yes.", "recap": "Previously on Driftwood Kin…\nThe city of Vattenheim rose before them like a dream carved from stone and wild — six towers of light stretching out from the heart of the city like rays of a sun that had never learned to set. The Driftwood Kin, cleaned and dressed for the first time in months, stepped out of Madam Asalia's bathhouse and into the festival air, each of them carrying the weight of everything they'd seen and everything they still had to do.\nIn the smoke-filled warmth of the Ethereal Leaf, they found Ude — the minotaur artificer, the crafter, the man who had given them their wagon and asked for nothing in return. He told them of the Arcanist Society, of five mages who stood outside the nations, who watched and waited and knew too much. And then, with hands that buckled solid wood, he told them of Vox Animus — a settlement born from generosity, burned by Kalestis, and of Sahara the Red Maiden, taken so that the survivors could never rally.\nThe party solved the puzzle of the wisp — a spell, any spell, cast from the hand and heart, not from a wand — and one by one they stepped through into the pocket dimension of the Arcanists. They met Dakar the Farsighted, who sees the coming war and cannot yet choose a side. They met Baywood the Wanderer, who has walked the Feywild and knows the fungi are watching. They made their case for Low Tide, for a sanctuary city, for a spectacle that would tell the Northern Alliance that they do not hold all the power.\nUde said yes. The others said: we shall see.\nAnd now the Feast of Oaths approaches. The storm is coming. The veil grows thin. And the Driftwood Kin stand on the edge of something that cannot be undone.", "dm": null, "party": ["Nix", "Rune-will (Rulal)", "Ponzi", "Talon"], "opens": "Exiting Madam Asalia's bathhouse in the Sky District, Vattenheim", "closes": "Subterranean rooms with red crystal hearths at the Trifold Tavern, long rest taken, Feast of Oaths two nights out", "cards": {"changed": {"headline": "Ude the Crafter is committed", "detail": "The party formally pitched the Low Tide evacuation and sanctuary-city plan to the Arcanist Society. Ude committed personally regardless of what the others decide — the first external ally formally bound to the cause, offering crafting, enchanting, and advocacy inside the Society.", "t": 10905}, "learned": {"headline": "Vox Animus was burned to kill uncontrolled power", "detail": "Ude revealed that Vox Animus — a settlement founded by winners of a race who gave away their keep to build a community — was burned by Kalestis specifically to eliminate authentic, uncontrolled power, and Sahara the Red Maiden was taken in the attack to prevent survivors from rallying. It gives the Low Tide plan historical precedent and tells the party exactly what Kalestis does to communities like the one they want to build.", "t": 5934}, "who": {"headline": "Ude the Crafter", "detail": "The minotaur artificer carried the whole session: he named the Arcanist Society, demonstrated the weather orb, opened the wisp puzzle, told the Vox Animus story with hands that buckled solid wood, and was the only Arcanist to say yes. Rune-will reminds him of Sahara, which is what cracked him open.", "t": 1403}, "cost": {"headline": "A full day burned for one commitment", "detail": "Persuasion 11 at the Arcanist meeting bought nothing from Dakar, Baywood or Hand-in-the-Hill. Ude poofed the party out mid-conversation before they were finished. Rune-will spent 100 gold at the bathhouse and Nix 75 on a pipe he felt ripped off by; Nix burned a whole downtime night as an oven slave and learned nothing.", "t": 11019}, "hanging": {"headline": "Llama has not been asked yet", "detail": "The entire Low Tide plan depends on whether Llama wants this to happen, and the party must consult them before returning to the Arcanists for a full commitment. Behind that sit Sahara's unknown location and a war Dakar has already seen coming.", "t": 11081}}, "beats": [{"t": 56, "kind": "dread", "title": "The road behind, and Caramel's taunt", "line": "Loose ends from home — a rose planted near Scar, the giant elk left on guard — and behind them Caramel, sealed and fortified, which overnight left a mushroom message calling the party cowards.", "facets": [["Character", "Ponzi planted a rose near Scar in Ruined's greenhouse — the Low Tide connection maintained."], ["Environment", "The giant elk guardian was left to guard the party's home base (the keep/grove)."], ["Environment", "Caramel is painfully quiet — gate closed and fortified, dull orange spores billowing up from inside, everything covered in moss and lichen, prepared for defense but no evidence of battle or movement. No bodies. It feels undead."], ["Threat", "The fungal intelligence knows the party exists and is taunting them. Left unresolved — the party will need a plan for Caramel before returning."]]}, {"t": 185, "kind": "travel", "title": "Vattenheim, City of the Wild", "line": "The party stepped out of Madam Asalia's bathhouse into the Sky District, and the DM laid out the whole city — six shining rays reaching from the Sunrise Citadel on aqueduct bridges.", "facets": [["Environment", "Packed stucco buildings in earthen cream and muted blues, communal living, rooftop gardens, built into a cave system with a Cave Side and a Bright Side. Districts: Sky, Falls, Den (Cave Side); Shade, Dawn (Bright Side)."], ["Environment", "Sunrise Citadel — central circular building, seat of the Sassen Council (protectors), six aqueduct bridges branching to six towers."], ["New lore", "The Six Shining Rays: Combat = Karash Arena; Faith = Wilder Temple; Steed = Windrider Hall; Beauty = Courtyard Tower; Murph = Trifold Tavern; Magic = Luminarcon Theater."], ["Environment", "Windrider Hall: an arcane gate opened mid-bridge and three dozen riders sprinted across on horseback to cheers below."], ["Environment", "Trifold Tavern — three stacked taverns: Fallen Roost Feast Hall (cornucopia ring table fed by gnome kitchens below, fighting pits), Among Friends Pipe and Weave, Fine Grove Wine House."]]}, {"t": 748, "kind": "social", "title": "Dressed for the festival", "line": "Each member described their festival attire coming out of the bathhouse — and Talon's bolo tie turned out to be a bomb.", "facets": [["Character", "Rune-will (Rulal): dark blue to delicate feminine fancy robes and gloves, 100 gold spent at the bathhouse."], ["Character", "Nix: shepherd/harvest aesthetic robes in red, bronze and wheat detail, fox-inspired."], ["Character", "Ponzi: dark/black colours with a hint of red rose, low-key, not showy."], ["Character", "Talon: gray suede shirt, black leather jacket, tuxedo tails, bolo tie."], ["Item", "Talon's bolo tie is braided heavy-duty cord with a slow-burning fuse braided in near the end; the bolo piece is hollowed and holds enough explosive to decapitate someone or blow a door off. The party's reaction: \"Who are you?\""]]}, {"t": 1236, "kind": "social", "title": "The half-orc and the changeling boy", "line": "The two strays Nix picked up off the streets were set up with a room at the Fallen Roost; Talon gave the half-orc a DK coin and bread.", "facets": [["Character", "The half-orc fell asleep at the bathhouse and was carried on."], ["Decision", "FLAG: Phase 1 milestone — the first displaced people actively sheltered by the party. Potential future recruits for the sanctuary city."]]}, {"t": 1403, "kind": "social", "title": "Ude and the clockwork weather orb", "line": "Inside the Ethereal Leaf and Distillery they found Ude working on a clockwork weather-reading orb with six arcane duplicate hands, and thanked him for the wagon.", "facets": [["Major NPC", "Ude the Crafter — large black-furred minotaur, bone-white horns, spectacles, bow tie, double-breasted vest, sleeves rolled up. Artificer, enchanter, tinkerer."], ["Environment", "The Ethereal Leaf is an upscale smoking lounge — heavily cushioned spaces, big fluffy couches, attendants supplying pipes, leaves, drinks and sealed notes. The female attendant recognised the party and welcomed them without impediment."], ["Item", "Clockwork Weather Orb: a small ball of silver, brass and steel. Whisper a time and location, hold it over a map, and the metal rearranges to show weather. Demonstrated a storm coming in two nights and clear skies over Austin Lake."], ["New lore", "Ude explained teleportation ranges from short hops to full planar travel, and discussed pocket dimensions."]]}, {"t": 2071, "kind": "clue", "title": "Kalestis's navy, and Low Tide fading", "line": "Ude confirmed Kalestis's navy is growing and, with Tostraen dragonrider air support, the Northern Alliance would be the strongest force in the New World.", "facets": [["New lore", "The Alliance may be fracturing, forcing Kalestis to shore up the navy."], ["Threat", "Traffic from Low Tide has decreased — people are finding their way topside less. The window to act may be closing."]]}, {"t": 2227, "kind": "social", "title": "Nix's speech on Low Tide", "line": "Nix argued that the people trapped in Low Tide could change the world, just as the party was once trapped and couldn't escape without help.", "facets": [["Character", "\"Who is trapped on Low Tide right now that could make any difference in the world?\""], ["Major NPC", "Ude, moved: \"Rumba, you remind me a great deal of a friend of mine. Perhaps I'll find her again.\" Joy mixed with pain."]]}, {"t": 2389, "kind": "reveal", "title": "The Arcanist Society named", "line": "Ude named the five: Dakar the Farsighted (leader), Ude the Crafter, Baywood the Wanderer, and the missing Sahara the Red Maiden — mages who stand outside all national allegiance.", "facets": [["Faction", "Five powerful mages operating outside national allegiance, holding a pocket dimension in the Ethereal Plane. They observe, study and occasionally act."], ["Faction", "The Society is currently fractured by grief over Sahara's capture. Dakar leads but refuses quick decisions."], ["New lore", "Their meeting place was left a mystery — a pocket dimension."]]}, {"t": 2548, "kind": "item", "title": "Pipes, poisons and small purchases", "line": "The pipe attendant showed Ponzi the full selection while the party spent down at the Ethereal Leaf.", "facets": [["Item", "Cherry Assassin's Pipe (Ponzi): cherry wood, blackened metal at rim and bowl, with a hidden second bowl and thumb-hole — covering the hole draws from one leaf, uncovering the other. Ideal for poisoning a target's smoke."], ["Item", "Pipe of Smoking Monsters (Nix): wrought silver, dragon's claw and octopus tentacle wrapping the stem. Exhaled smoke can be shaped into small illusions. 75 gold — Nix felt ripped off."], ["Item", "Bronze Leather Flask (Nix): simple leather flask with bronze intricate wavy designs, 5 gold."], ["Major NPC", "Pipe Attendant: pointed elven ears, dark green vest, silver tie."]]}, {"t": 3611, "kind": "magic", "title": "The wisp puzzle", "line": "To reach the Arcanists you order a \"wisp\", cast a spell on the glass — any authentic casting, from the hand and not from a wand — and drink. Rune-will cracked it first with Identify.", "facets": [["House ruling", "The spell must be cast from the hand or body, not from a wand. Rune-will: Identify. Talon: Zone of Truth. Nix: an accidental Lay on Hands. Ponzi: Light."], ["Check", "Rune-will's Constitution save on the wisp drink: rolled 7 (total ~9). Neck twitching, nerve endings stimulated, like drinking energy. Not harmful, just intense."], ["Environment", "The pocket dimension: fine marble floors, tall-backed chairs, wavering hearth light with no findable source, wisps of tobacco smoke fog, a space that feels indeterminate in size. It sits in the Ethereal Plane."]]}, {"t": 4419, "kind": "magic", "title": "One by one, through the glass", "line": "Talon toasted \"take us to room\" under Zone of Truth and vanished, leaving Nix and Ponzi in disbelief; Ponzi finally got through on Light, having accidentally cast it on the attendant.", "facets": [["Character", "Nix got in by accidentally casting Lay on Hands. Ponzi: \"Finally!\""], ["New lore", "The pocket dimension currently holds up to about 10 people but can expand; roughly 2–3 dozen people know of it. Ude holds sway there — it is safe and controlled."], ["Decision", "LOW thread: the party now knows how to enter the pocket dimension, and that knowledge would be dangerous in the wrong hands."]]}, {"t": 4747, "kind": "plan", "title": "Gifts for the gods", "line": "Rune-will has a full list of offerings prepared for multiple Isterum, and Ude mapped out which gods are honoured where during the Feast of Oaths.", "facets": [["New lore", "The Isterum — 14 gods in 7 pairs: Eretos & Ileana, Eidys & Vaidun, Ramaeus & Vaidus, Eraso & Veila (Sunrise Citadel), Uros & Imera (Luminarcon Theater), Zastas & Kaiser (Deep Chapel, Den District), Dion & unknown spouse."], ["Decision", "Ude's advice: offerings with personal attachment, story or value beyond gold carry the most weight. Rune-will is struggling most with Dion."], ["Check", "Rune-will rolled a 7 on which Isterum she is drawn to — the 7th — and is being coy about the result. Ude noticed. Ponzi rolled 17, above the DM's hidden DC."]]}, {"t": 5254, "kind": "lore", "title": "The Feast of Oaths and the coming storm", "line": "Ude explained the Feast: the night the veil between creation and the Isterum is thinnest, always accompanied by a great storm, when oaths large and small have real power.", "facets": [["New lore", "The saying: \"The Feast of Oaths — you become bound and free.\""], ["Environment", "The weather orb showed a massive storm two nights out — wild storm clouds shot through with sparks of magical energy. Both a spiritual event and a literal weather threat."], ["Check", "Talon touched the orb with Mending and rolled 28 Arcana. Ude called it \"very precise\" and thanked him; the orb responded positively."]]}, {"t": 5699, "kind": "reveal", "title": "Ponzi's coin-flash vision", "line": "As Ponzi said he doesn't know much about the Isterum, he was hit with flash-visions of walking a grand hall toward a massive figure on a throne.", "facets": [["Character", "His connection to the divine is awakening involuntarily — he's \"learning more lately.\""], ["Decision", "Nix wants to deepen his oath to Aesus; Ude suggested something smaller and specific — a name, task, or act of service — rather than another grand oath. Talon has longstanding ties to Zastas (the Delver) and may swear at the Deep Chapel."]]}, {"t": 5845, "kind": "social", "title": "Persuasion 22 — Ude opens up", "line": "Rune-will rolled 19 with advantage (she reminds Ude of Sahara) for a 22, and Ude opened up completely and committed to helping.", "facets": [["Check", "Persuasion 22 — advantage granted because Rune-will reminds Ude of Sahara."], ["Decision", "Long-term hook opened: find a way to put a thorn in Kalestis's side — the first step toward rescuing Sahara and Wrath."]]}, {"t": 5934, "kind": "lore", "title": "Vox Animus and the Red Maiden", "line": "Ude told them of Vox Animus — a settlement founded by winners of a race who gave away their keep to build a community, burned by Kalestis to eliminate authentic, uncontrolled power.", "facets": [["New lore", "Built by the sea near Ude's tower. A remnant survived. Sahara the Red Maiden was taken in the attack to prevent survivors from rallying."], ["Major NPC", "Ude's hands buckled the solid wood armchair. \"Kalestis likes his control. The Red Maiden is not able to be controlled. So they took her.\""], ["Faction", "None of the Five Nations intervened when Vox Animus was burned — all insulating, building up strength, waiting for war. \"Friends are hard to come by when everyone is only protecting themselves.\""], ["Character", "After the emotional meeting Ude simply dismissed the party from the pocket dimension mid-conversation. \"I had more to say to Ude, I'm not going to lie.\""]]}, {"t": 7211, "kind": "scene", "title": "Downtime: the gnome kitchen, the dice, the band", "line": "A full downtime day — Nix shapeshifted into a gnome to infiltrate the Trifold Tavern's kitchens, Ponzi cleaned up at the tables, and Talon joined a band at the Fallen Roost.", "facets": [["Check", "Nix failed his Constitution save, worked the ovens all night as a slave, then rolled 7 on Sleight of Hand to steal a recipe page — smeared with sweat, the gnome's apron slapped down on his hands. Learned nothing. \"I just wanted a recipe.\""], ["Major NPC", "Gnomish Head Chef (Fallen Roost): female gnome, filthy apron, brash and fast-talking, manages the subterranean kitchens under the cornucopia table."], ["Check", "Ponzi rolled 90 on the percentile die (above DC 35), then 6d20 for winnings — 47 gold."], ["Check", "Talon rolled 22 performance (18 + 4) to an easy crowd and earned 16 gold in tips. The changeling boy shapeshifted a fake Talon beard onto his face and danced along."], ["Character", "Ponzi gained proficiency in a musical instrument during the long rest, inspired by watching Talon perform."]]}, {"t": 8157, "kind": "clue", "title": "Wrath, Seavey and Kalestis's prisoners", "line": "An older thread resurfaced: Seavey, a prior campaign character, was searching for a monk named Wrath — the love interest of another character, captured by Kalestis alongside Sahara.", "facets": [["Character", "Wrath's rescue is now implicitly tied to Sahara's."]]}, {"t": 8324, "kind": "scene", "title": "The temple circuit", "line": "The party spent the downtime day walking Vattenheim's temples and came away with tokens from three different gods.", "facets": [["Environment", "Wilder Temple: a four-story tower dedicated to the Isterum, its top level hung with animal trophies, enshrined hunting weapons, edict stones and an animantine bell — Dion's section."], ["Item", "Vial of Sand (Rune-will): a single grain of sand in a vial, received at the Wilder Temple from Dion's section. Significance unknown."], ["Environment", "Deep Chapel of Zastas (Den District): dark, small, ominous, lit by bioluminescent fungi in jars and glass vases. Priests give silver armbands for gifts or poetry left."], ["Item", "Silver Armbands x2 (Rune-will) for leaving a book of poetry — one for Zastas, one for Kaiser. Talon rolled 18+10 = 28 Persuasion and was given a book joyfully: \"Studies of the Wild Things Neither Dead or Alive: Studies in the Feywild\", with a mushroom on the cover."], ["Character", "Rune-will stood outside the Luminarcon Theater for 10 minutes staring at the angel above the doors, terrified of Luminarcons, before going in. Thin streams of water began orbiting her — Imera's token. She chose to let it swirl rather than bottle it. Ponzi left 5 gold and watched it multiply visually like koi splitting."]]}, {"t": 9384, "kind": "social", "title": "The full Arcanist Society convenes", "line": "After sunset the party returned and met all four present Arcanists at once.", "facets": [["Major NPC", "Dakar the Farsighted — Arakakra bird folk, ~6 feet, white and black speckled plumage, elaborate blue/silver/gold/purple robes, light blue gold-rimmed crystal spectacles. Divination wizard and leader; exceptionally difficult to read. The more he knows, the muddier his recommendations become."], ["Major NPC", "Baywood the Wanderer — half-elven, tan skin, dark eyes, tight raven-black ponytail, rugged shirt and vest with a book harness. Performs wild magic shows at the Luminarcon Theater. Pessimistic about the plan, not antagonistic."], ["Major NPC", "Hand-in-the-Hill — elderly dwarf, magical tattoos over his body, stark white hair, wild multi-layered robes, bright green eyes. Strong destructive magic and adept at repairing what he destroys. His eyes sparked with fire at the idea of rebellion."], ["Check", "Party insight checks to read the Arcanists' reactions: 13, 20, 17, 17. The DM assigned each player one Arcanist to read."]]}, {"t": 10314, "kind": "lore", "title": "The fungi are one thing", "line": "Baywood confirmed the island's fungal threat is widespread and linked — all fungi communicating back to a single source, able to form creatures and act as spy-eyes.", "facets": [["New lore", "Spores act as distributed eyes. The fungi can temporarily form into creatures but not fully autonomous persistent beings, as yet observed."], ["New lore", "Baywood suggested the answers lie in the Feywild — and Talon's new book is specifically about Feywild fungi. The party is being pointed at a Feywild arc."], ["Threat", "The central source of the network is unknown and potentially very powerful. Baywood withheld some sensitive information."]]}, {"t": 10480, "kind": "lore", "title": "Dakar's cosmology", "line": "Dakar gave a full planar briefing: Material Plane, then the mirror planes, the Elemental Planes, the Ethereal Plane — where they were currently sitting — and the Outer Planes beyond.", "facets": [["New lore", "Material Plane → Feywild (beauty reflection) / Shadowfell (terror reflection) → Elemental Planes (Fire, Air, Water, Earth, plus merging strips) → Ethereal Plane (pocket dimensions, invisible travel, lost civilizations adrift) → Outer Planes (Upper = blessing, Lower = punishment and prison, eternal realms of departed souls)."], ["New lore", "Mount Celestia: a plane of pure good and righteous law, an ever-ascending mountain. The living may reach the foothills but cannot ascend further."], ["New lore", "Dion the Judge rules the lower prison planes — Limbo, Carceri, Helheim, Pandemonium — and determines where souls go. He does not rule the upper planes. \"Quite a mystery.\""]]}, {"t": 10905, "kind": "plan", "title": "The Low Tide pitch — and Ude says yes", "line": "The party formally pitched the Low Tide evacuation: move its people to a llama (island), build a sanctuary city, make it a spectacle against the Northern Alliance. Ude committed personally.", "facets": [["Decision", "Ude is the first external ally formally committed to the cause — he will help with crafting, enchanting, and working on the other Arcanists."], ["Decision", "Ude is torn between his innate caution and his rage over Kalestis's actions; he tends to sit on the outside gaining knowledge slowly, and his rage is pushing him against his own nature."], ["New lore", "The concept: a beacon city for the displaced, preserving the island's wild character, executed as visible spectacle to counter the Northern Alliance's narrative of control."]]}, {"t": 11019, "kind": "social", "title": "\"We shall see what comes next\"", "line": "Rune-will made the closing case and rolled 11 on persuasion. Dakar declined to commit — the door not slammed, but nothing secured — and the party retired to the Trifold Tavern.", "facets": [["Check", "Persuasion 11. Dakar: \"We shall see what comes next. We cannot see enough yet.\""], ["Decision", "Dakar, Baywood and Hand-in-the-Hill have heard the pitch but not committed. Dakar needs more information before deciding."], ["Decision", "Next step: consult Llama about the Low Tide evacuation plan before returning to the Arcanists for a full commitment."], ["Environment", "The party took subterranean rooms with red crystal hearths at the Trifold Tavern and long rested. Tomorrow is downtime; the Feast of Oaths is the day after."]]}], "threads": [{"u": "hi", "q": "Where is Sahara the Red Maiden and how do they get her back? Held by Kalestis. Ude is consumed by it. The party has now made it a priority but there is no plan for extraction.", "t": 5934}, {"u": "hi", "q": "How close is the war? Kalestis's navy is growing, the Alliance may fracture, and Dakar has seen it coming very soon — with the party directly in its path.", "t": 2071}, {"u": "hi", "q": "Is the window on Low Tide closing? Traffic from Low Tide is decreasing and people are finding their way topside less.", "t": 2144}, {"u": "hi", "q": "What is Caramel now? Fortified, spore-covered, no bodies, and it left a mushroom message calling the party cowards — the fungal intelligence knows they exist.", "t": 87}, {"u": "md", "q": "Where is the fungal network's single source? All island fungi link back to one place; Baywood has been studying it and withheld sensitive information.", "t": 10314}, {"u": "md", "q": "Will the Arcanists commit? Three of four present are non-committal; Dakar says \"we shall see.\" The party needs Llama's answer and a stronger case.", "t": 11019}, {"u": "md", "q": "Where is Wrath? Captured by Kalestis, sought by Seavey, and his rescue is now implicitly tied to Sahara's.", "t": 8157}, {"u": "md", "q": "Which Isterum is Rune-will drawn to? She rolled a 7 — the 7th — and is being coy about it. Ude noticed.", "t": 5060}], "next": ["Attend the Feast of Oaths — the storm night, the thinnest veil between creation and the Isterum.", "Nix deepens his oath to Aesus — something smaller and specific (a name, task, or act of service) rather than another grand oath.", "Rune-will presents her gifts to the appropriate Isterum at their honored locations — she has a full list and has been preparing.", "Ponzi explores his Isterum connection — the coin-flash visions suggest something is awakening.", "Talon visits the Deep Chapel of Zastas — he is connected to Zastas (the Delver) and may want to swear a specific oath.", "Return to the Arcanist Society after the Feast of Oaths to continue discussions — Ude has committed, need to work on the others.", "Consult Llama about the Low Tide evacuation plan before returning to the Arcanists for a full commitment.", "Investigate the Feywild connection to the fungal threat — Talon's book is a starting point."], "entities": [{"name": "Ude the Crafter", "kind": "npc", "note": "Large black-furred minotaur artificer/enchanter/tinkerer with bone-white horns, spectacles, bow tie and double-breasted vest. Arcanist Society. Deeply grieving Sahara's capture and enraged at Kalestis. Personally commits to the Low Tide plan.", "t": 1403}, {"name": "Dakar the Farsighted", "kind": "npc", "note": "Arakakra (bird folk) divination wizard, leader of the Arcanist Society. ~6 feet, white and black speckled plumage, elaborate robes, crystal spectacles. Has seen the coming war clearly. \"We shall see what comes next.\"", "t": 9471}, {"name": "Baywood the Wanderer", "kind": "npc", "note": "Half-elven field mage with a book harness. Performs wild magic shows at the Luminarcon Theater. Has walked the Feywild and researched the island's fungal threat. Pessimistic about the Low Tide plan but not hostile.", "t": 9432}, {"name": "Hand-in-the-Hill", "kind": "npc", "note": "Elderly dwarf mage, magical tattoos, stark white hair, wild multi-layered robes, bright green eyes. Destructive magic, also adept at repairing what he destroys. Finds the rebellion's risk exciting.", "t": 9415}, {"name": "Sahara the Red Maiden", "kind": "npc", "note": "The missing fifth Arcanist. Patron and protector of Vox Animus, bonded deeply with its three founders. Captured by Kalestis during the burning to prevent survivors from rallying. Location and condition unknown.", "t": 5934}, {"name": "Gnomish Head Chef", "kind": "npc", "note": "Female gnome in a filthy apron running the subterranean kitchens under the Fallen Roost's cornucopia table. Brash, fast-talking, no-nonsense. Put Nix to work at the ovens.", "t": 7025}, {"name": "Pipe Attendant", "kind": "npc", "note": "Ethereal Leaf attendant with pointed elven ears, dark green vest and silver tie. Showed Ponzi the Cherry Assassin's Pipe and the Pipe of Smoking Monsters.", "t": 2548}, {"name": "Madam Asalia", "kind": "npc", "note": "Owner of the Sky District bathhouse where the party cleaned up. Not directly described.", "t": 644}, {"name": "Half-Orc", "kind": "npc", "note": "Large half-orc Nix picked up off the streets. Fell asleep at the bathhouse, set up in a room at the Fallen Roost, given a DK coin and bread by Talon.", "t": 1236}, {"name": "Changeling Boy", "kind": "npc", "note": "Small changeling child Nix picked up. Danced along to Talon's music wearing a shapeshifted fake Talon beard.", "t": 7710}, {"name": "The Arcanists", "kind": "faction", "note": "Five mages outside national allegiance holding a pocket dimension in the Ethereal Plane. Fractured by Sahara's capture. Ude committed; the rest are non-committal.", "t": 2389, "alias": "Arcanist Society"}, {"name": "The Northern Alliance", "kind": "nation", "note": "Kalestis's growing navy plus Tostraen dragonrider air support — together the strongest force in the New World. May be fracturing. Burned Vox Animus and captured Sahara.", "t": 2071, "alias": "Northern Alliance"}, {"name": "Sassen Council", "kind": "faction", "note": "Protectors of Vattenheim, meeting in the Sunrise Citadel. Seat of rule for the city.", "t": 247}, {"name": "The Isterum", "kind": "faction", "note": "Fourteen gods in seven pairs, active in the world. The Feast of Oaths is a real event where the veil thins and oaths have power. Luminarcons are celestial servants of Uros — \"unmakers\", \"blinding light that blocks out foul things.\"", "t": 4858}, {"name": "Five Nations", "kind": "faction", "note": "All insulating and building up strength, waiting for war. None intervened when Vox Animus was burned.", "t": 6103}, {"name": "Vattenheim", "kind": "place", "note": "City of the Wild. Stucco buildings in earthen cream and muted blues, rooftop gardens, built into a cave system with Cave Side (Sky, Falls, Den Districts) and Bright Side (Dawn, Shade Districts).", "t": 209}, {"name": "Sunrise Citadel", "kind": "place", "note": "Central circular building, seat of the Sassen Council, with six aqueduct bridges branching to the Six Shining Rays.", "t": 247}, {"name": "Ethereal Leaf and Distillery", "kind": "place", "note": "Upscale smoking lounge in the Sky District. Order a \"wisp\", cast a spell on the glass, drink, and translate into the Arcanists' pocket dimension.", "t": 1320}, {"name": "Arcanist Society Pocket Dimension", "kind": "place", "note": "Fine marble floors, tall-backed chairs, hearth light with no findable source, indeterminate size. Located in the Ethereal Plane. Holds ~10, expandable.", "t": 3611}, {"name": "Deep Chapel of Zastas", "kind": "place", "note": "Dark, small, ominous temple in the Den District lit by bioluminescent fungi in jars. Priests give silver armbands for gifts or poetry.", "t": 8484}, {"name": "Luminarcon Theater", "kind": "place", "note": "Beautiful tower with a wide base and brilliant blue roof, magical dancing lights, altars holding magically protected items, the sound of crashing waves throughout.", "t": 472}, {"name": "Wilder Temple", "kind": "place", "note": "Four-story tower dedicated to the Isterum. Top level holds animal trophies, enshrined hunting weapons, edict stones and an animantine bell in Dion's section.", "t": 8324}, {"name": "Trifold Tavern", "kind": "place", "note": "Three stacked taverns — Fallen Roost Feast Hall, Among Friends Pipe and Weave, Fine Grove Wine House. The party took subterranean rooms with red crystal hearths.", "t": 613}, {"name": "Caramel", "kind": "place", "note": "The spore city. Fortified, sealed, covered in moss and lichen, dull orange spores billowing out, no bodies, feels undead. Left a mushroom message calling the party cowards.", "t": 87}, {"name": "Vox Animus", "kind": "place", "note": "A settlement founded by winners of a race who gave away their keep to build a community by the sea near Ude's tower. Burned by Kalestis. A remnant survived.", "t": 5964}, {"name": "Clockwork Weather Orb", "kind": "item", "note": "Ude's small ball of silver, brass and steel. Whisper a time and place, hold it over a map, and the metal rearranges to show the weather.", "t": 1691}], "gaps": ["The source never names the DM — it refers only to \"the DM\" in third person, so `dm` is left null.", "Character names are spelled inconsistently across the note's sections: the timecoded D&D sections use \"Nix\" and \"Rune-will (Rulal)\", while the untimecoded Project Sync section uses \"Nyx\" and \"Rune Willow\". Both spellings are preserved as they appear.", "NPC and place spellings also vary: \"Baywood the Wanderer\" / \"Bayward the Wanderer\"; \"Hand-in-the-Hill\" / \"Hand-in-the-Hail\"; \"Kalestis\" / \"Kalestas\"; \"Luminarcon Theater\" / \"Luminarkan Theater\" / \"Luminarking Theater\"; \"Zastas\" / \"Zastis\"; \"Dion the Judge\" / \"Dyun the Judge\"; \"Vattenheim\" / \"Vattheim\"; \"Ahlama\" / \"Llama\"; \"Ude\" / \"Uud\". Names are copied as spelled in the section they came from.", "The note lists the Six Shining Rays' domains inconsistently — the timecoded LORE entry gives \"Murph = Trifold Tavern\" while the Project Sync section gives \"Trifold Tavern (Mirth)\"; \"Murph\" appears to be a transcription error for \"Mirth\".", "\"Llama\" is treated in the source as both a place (an island to move Low Tide's people to) and something the party must consult for an answer; the note never resolves which.", "The Project Sync / Status Update section of the note carries no timecodes at all; every `t` in this file comes from the timecoded QUICK DIGEST and FULL DETAILED NOTES sections."], "iso": "2026-05-02", "pretty": "2 May 2026", "audio": true, "legendary": false, "n": 12}, {"slug": "pocket-wind-introduction-and-testing", "title": "Pocket Wind Magical Item Introduction and Testing", "date": "04/23/2026 19:35", "runtime": "3h 16min 9s", "nottaId": "04d14155-aa7c-48db-8fc9-d26e9de0e893", "url": "https://app.notta.ai/7366972874555052032/dashboard/04d14155-aa7c-48db-8fc9-d26e9de0e893", "template": "D&D Session Noters: V3", "hasTimecodes": true, "timecodesReliable": true, "durationSec": 11769, "subtitle": "The keep followed its friend home", "logline": "A wind in a pocket, a dome of living water, a keep that walked to Scar — and a fortress full of spores that killed Periwink on contact.", "recap": "\"Previously on Driftwood Kin…\"\nThe shrine answered — but not with words. A breath of wind, shifting between mouse and maiden and nothing at all, settled into Broomwillow's pocket. The Pocket Wind. A messenger. A mystery. A non-answer that might be the only answer she'll ever get.\nThey rode west along the Alder River as the sun began to fall, and there — where the river split — the world split with it. Water leapt skyward, weaving itself into a dome of living lattice miles wide, catching the dying light like a prism, scattering color across the hills. Inside: warm air, oversized flowers, mist, and the distant silhouettes of colossal elk with antlers of bronze.\nThey camped outside. Broomwillow painted. And in the deep of the night, with a natural twenty and a breath she didn't know she was holding, she saw it — the ground inside the dome rising and falling. Breathing. Scar's chest, somewhere in the mist, still alive.\nAt dawn they crossed the lowered river and entered the grove. Nyx knelt before the great central elk, placed his hands on the earth, and felt the ground breathe beneath his fingers. And then — not with a flash or a crack, but growing from the blessed soil like something that had always been there — Driftwood Tower rose. The keep had followed its friend home.\n\"There you are, bud,\" Nyx said, his hand on Scar's chest.\nThey left the grove with damp clothes and full hearts, a field mouse with emerald eyes nesting in Talon's hood, and a letter from Giovanni that arrived as an origami bird: Quest of Elmore. Quest of death. The Voyagers' motto.\nKaer Maul was a fortress that had become a tomb. Orange spores billowed from a wall that had exploded outward from within. No bodies. No survivors. No foot traffic leaving. Periwink dove in and came back as nothing. They retreated. And in the morning, thirty feet from camp, a mushroom patch had grown overnight — spelling a single word: COWARDS.\nNyx burned it.\nThey cut through the Brolin Forest on a dried riverbed, Ponzi's visions of a dead dwarf explorer guiding them around the mud, Talon's reduce spell shrinking the wagon through the tightest passages, Periwink navigating the branching paths from above. They emerged into the cold, wet, and close.\nVattenheim rose before them at dusk — half-swallowed by a cliffside, lit from within, adorned with the banners of a dozen peoples of Va. The City of the Wild opened its gates.\nAnd somewhere in the Falls District, in a tower that hung upside down from the ceiling of the cliff, a window opened. A voice in Broomwillow's head: \"Oh hello, hello. You've arrived. I think I can see you.\"\nThe festival is days away. The answer — or the death — is coming.", "dm": null, "party": ["Broomwillow (Brunie/Rune Willow)", "Nyx", "Ponzi", "Talon (Talendir)"], "opens": "The Shrine of Arasil, receiving the Pocket Wind", "closes": "Madame Asalia's Bathhouse, Sky District, Vattenheim — clean, dressed, and due at the Ethereal Leaf", "cards": {"changed": {"headline": "Driftwood Keep now stands in a sacred grove", "detail": "The keep teleported out of Nastra Antheon and grew from the blessed soil of the lattice dome's grove, taking the greenhouse — and Scar — with it. It is a permanent relocation, guarded by giant elk, and it turns the keep into a possible mobile waypoint between the sacred groves of Vael.", "t": 4182}, "learned": {"headline": "Scar is alive", "detail": "A natural 20 on the third watch gave a divine vision: the memory of burying Scar, torn in half and kept alive by the Tender's magic, and then the ground inside the dome rising and falling with his breathing. At dawn it was confirmed — his face and shoulders emerged from the greenhouse dirt, breathing.", "t": 2953}, "who": {"headline": "Broomwillow", "detail": "She asked Arasil the question and got a wind instead of an answer, laid down a vow that she will be chosen at Vattenheim or die, saw Scar breathing, opened up her Low Tide plan to the party, gathered the displaced in a strange city, and gave in to a steam illusion of coming home. Every thread this session runs through her.", "t": 893}, "cost": {"headline": "Periwink, Kaer Maul, and a very expensive bath", "detail": "Periwink was snuffed out on contact with the spores (re-summonable, but the lesson cost a familiar). Kaer Maul was abandoned with 40–50 people unaccounted for. Talon burned 2 spell slots on Reduce crossing the forest. The bathhouse ran 2,000 gold for Broomwillow, 200 for Talon, 100 for Nyx and 75 for Ponzi — and Ponzi's glove only hides the hand, it does not heal it.", "t": 7313}, "hanging": {"headline": "Who, if anyone, has claimed Broomwillow?", "detail": "The Pocket Wind is an ambiguous answer from Arasil's shrine — a non-answer, a deflection, or a subtle confirmation. The Festival of the Asterim is days away and she has bound her life to the outcome.", "t": 798}}, "beats": [{"t": 109, "kind": "item", "title": "The shrine answers with a wind", "line": "Broomwillow asked Arasil, Lord of all the Asterim, whether any Asterim had claimed her — and received the Pocket Wind, a shifting wind creature that carries letters to any named creature on the same plane.", "facets": [["Item", "It appears as a mouse, a small feminine winged form, a ball of wind — constantly shifting. It folds letters into origami (lotus, elongated rose stem, bird), stays with the recipient until they reply, gets impatient, and blows in ears."], ["Check", "Broomwillow cast Identify on it to determine its properties. She wrote \"Hello\" to Nyx; Nyx replied \"How do you do?\" — confirming the loopback mechanic."], ["New lore", "Arasil is about \"power, nobility, and decisiveness, not riddles\" — Nyx argues he would have given a clear answer if it were him. The gift may be a non-answer, a deflection, or a subtle confirmation."], ["Environment", "At the Shrine of Arasil, Broomwillow used staff charges to flower the shrine in yellow and gold."], ["Decision", "The Pocket Wind is still unnamed — Broomwillow felt she lacked the authority to name it."]]}, {"t": 564, "kind": "magic", "title": "Testing the Pocket Wind on Giovanni", "line": "Broomwillow wrote to Giovanni asking after his wellbeing and telling him to use the sending stone on receipt, to time the delivery. The answer came back at roughly twelve hours.", "facets": [["Major NPC", "Giovanni: \"Still subtle danger here but mounting. Looking for my next venture. Hope you're safe.\""], ["House ruling", "Pocket Wind delivery time ~12 hours, distance dependent; same plane of existence only."], ["Decision", "Ponzi's ~25-word reply: \"We're safe. Dawson is on the hunt.\" The party deliberately left out their destination so as not to tip Dawson off."]]}, {"t": 893, "kind": "dread", "title": "Broomwillow's death vow", "line": "She told the party she will be chosen by an Asterim at Vattenheim or she will die — then climbed straight back onto her horse.", "facets": [["Character", "\"I will be accepting one or the other — an answer or death. Why? I am through with wondering if I'm truly alive or not. And the living received the blessing of an Asterim should they choose it. I will be chosen or I will be dead.\""], ["Threat", "The Festival of the Asterim is days away. That is the deadline."]]}, {"t": 1193, "kind": "travel", "title": "The lattice dome at the fork of the Alder River", "line": "Where the Alder River branches, water leaps skyward and weaves itself into a dome of living lattice miles wide — warm, misted, full of oversized flora and giant elk.", "facets": [["Environment", "Interior: warm and temperate, dense waist-high foliage, heavy mist (~quarter-mile visibility), light rain, oversized flora. At the centre a column of luminescent water drops from overhead and turns to mist 80 feet above the ground, with a giant elk about 20 feet tall and bronze-damascus antlers beneath it."], ["Check", "The wand detected the magic as primal/celestial and could not classify it — \"the magic of nature or of angels.\" Talon rolled 18 perception and spotted small creatures in the grass and a colossal elk ~15 feet tall deep inside."], ["Decision", "The party camped outside overnight and entered at dawn to preserve visibility and comfort. Broomwillow took first and second watch, painting the dome."], ["Character", "Divine Sense read the ground as blessed, reminiscent of Valien the Tender, with a familiar resonance to Scar's prior grove. Talon, after Broomwillow said the dome reminded her of Scar: \"He would want you to go in there.\""]]}, {"t": 1895, "kind": "social", "title": "Boys' night on second watch", "line": "Nyx woke Ponzi and Talon during second watch to talk about Broomwillow's vow — and the state of Ponzi's left hand.", "facets": [["Character", "Nyx: \"I'm going to need you boys to step up with me and ensure that she continues to search for an answer even if she doesn't have one in Vattenheim.\" Ponzi: \"I'm afraid of the disappointment. She already knows the answer. She's just afraid to accept it.\" Talon: \"Sounds like it's spoken out of understanding if not empathy.\""], ["Threat", "Ponzi's left hand is deteriorating — he shields it in sleep and is in consistent pain. Nyx laid hands on him for 1 point. Root cause unknown."], ["Check", "Nyx tried to steal Ponzi's socks mid-meeting (roll 13) against Ponzi's passive perception 16. Ponzi felt it and slapped Nyx's hand away with his left hand — and winced."]]}, {"t": 2953, "kind": "reveal", "title": "A natural twenty, and Scar is breathing", "line": "On the third watch a natural 20 brought a divine vision: the memory of burying Scar, torn in half and kept alive by the Tender's magic — and then the ground inside the dome rising and falling with his breath.", "facets": [["Character", "Watch continued in silence afterward. An expression of awe with a tear rolling down the cheek — \"not necessarily sorrow.\""], ["Check", "Watch perception rolls across the night: Broomwillow 16 (painted the animals), Broomwillow 17+8 = 25 (the dome reflecting starlight), the Nat 20 divine vision, Talon 14 on the final watch (reflective eyes in the dome, no threat)."]]}, {"t": 4140, "kind": "reveal", "title": "Scar in the greenhouse", "line": "Nyx knelt before the great central elk, put his hands on the earth and felt the ground breathe. Scar's face and shoulders emerged from the dirt — alive, breathing, in the greenhouse.", "facets": [["Environment", "The party crossed the lowered riverbed at dawn and entered the warm, temperate dome. Multiple giant elk with bronze-damascus antlers walked peacefully among them as guardians of the grove."], ["New lore", "Scar is half-alive, buried in the greenhouse and kept that way by the magic of the Tender. The ground rises and falls with his chest."], ["Character", "Nyx, hand on Scar's chest: \"There you are, bud.\" Scar's mouth lifted in a slight smile."]]}, {"t": 4182, "kind": "magic", "title": "Driftwood Tower rises from the blessed soil", "line": "The keep teleported from Nastra Antheon into the sacred grove inside the dome — not with a flash, but growing from the earth as though it had always been there.", "facets": [["Decision", "This is a permanent change to the party's home base: the keep, the greenhouse and Scar now sit inside a sacred grove of Vael/the Tender, guarded by giant elk."], ["Character", "Talon's insight: \"Your home isn't following you. Your friend is.\""], ["Character", "Nyx to Broomwillow after the boys' night: \"I know it might not be the answer you were looking for, but don't stop looking. It's out there somewhere.\""]]}, {"t": 4631, "kind": "scene", "title": "What they planted in the blessed soil", "line": "Nyx replanted a sacred rose near Scar and tiny roots reached up and grafted onto it — and the party started to wonder how far the keep could follow.", "facets": [["Item", "Talon picked a burnt orange gladiolus in the dome and gave it to Nyx for his gift count."], ["New lore", "Nyx's hypothesis: the keep may be able to travel between sacred groves of Vael — \"perhaps all across the island, or maybe the world.\" Needs testing."]]}, {"t": 5012, "kind": "plan", "title": "Dawson closing, and the Low Tide plan", "line": "Dawson is tracking the party through six different things and was within a day of Alama; the keep's teleport bought distance. In the same conversation Broomwillow finally shared her Low Tide plan.", "facets": [["Threat", "Dawson is actively hunting. He has resources and intelligence and will close the gap."], ["Decision", "Broomwillow: \"I can trust you all enough with this information... Ever since we left Low Tide last time... I haven't been able to shake Low Tide from my mind... Why don't we remove Low Tide from under the thumb of the Northern Alliance?\" Ponzi: \"No chains, no masters.\""], ["New lore", "The plan: relocate Low Tide's population to Alama, potentially via planar gate magic. Obstacles: a route through or under the Celestial City, planar gate magic, Alama's cooperation, and Low Tide's willingness. The party was supportive but has no solution yet."], ["Faction", "The Northern Alliance controls Low Tide and extracts money from its population. Its people are free, not prisoners — but economically trapped, and any physical aid will be countered."]]}, {"t": 5586, "kind": "item", "title": "Nat 20 tinkering: the Splinter Dart", "line": "Using tinkering and his fife measurements, Ponzi rolled a natural 20 (25 total) and crafted a reusable multi-target Splinter Dart that came out carrying more magic than he put into it.", "facets": [["Item", "Fires and explodes outward to hit multiple opponents; recoverable and reusable. Detect magic confirmed conjuration school — more magic than Ponzi put in."], ["Item", "Ponzi also crafted a batch of poisons during the keep stay, and carries an Enchantment Breaker Ring and a Poison of Sleep (black with a white streak), both acquired from the hag."]]}, {"t": 5937, "kind": "lore", "title": "The Veins of Yavanna, identified and planted", "line": "A natural 20 nature check gave Ponzi a full reading of the red root: iron content, primal rather than manufactured magic, and it touches the life force of a person.", "facets": [["New lore", "In an alchemist's hands it can be worked into potions and poisons replicating Hold Person, Paralyze, Charm Person, Suggestion and Geas — the command spell, where disobedience causes damage for a month."], ["Item", "Planted in the sacred greenhouse, where blessed soil may allow it to be cultivated. It previously caused alarm in Alama — \"get that out of here.\""]]}, {"t": 6206, "kind": "travel", "title": "Leaving the dome — a mouse and a letter", "line": "The giant elk stood watch as the party left. Clothes damp from the mist, the cold hit immediately outside — and a field mouse with emerald green eyes had followed Talon out, nesting in his hood.", "facets": [["Character", "Talon tried to speak with it (animal handling 6) — it cocked its head and burrowed deeper. \"If he talks to me, I'll take it. If he doesn't, that's a ball I expect.\" It still needs a name (not Mickey)."], ["New lore", "Giovanni's reply arrived mid-travel as an origami bird: \"Quest of Elmore\" — Quest of Death, the Voyagers' motto. The age of Voyagers is dying as war approaches the new world. The party are among the last."]]}, {"t": 6441, "kind": "dread", "title": "Kaer Maul, closed and blown outward", "line": "A small stone fortress at the edge of the Brolin Forest with no smoke, no activity, gates barred with spiked barriers — and one wall section blown outward from the inside.", "facets": [["Check", "Talon 18 perception (reliable talent, advantage) and Ponzi 22 spotted the fortified gate, the spiked barriers, and that the wall was a detonation from within, not a battering ram."], ["Environment", "Dull orange spores billowing from the blasted section. Dead and decayed lichen, moss and fungi covering every surface — still actively emitting spores. No bodies, no movement, no foot traffic leaving."], ["Check", "Luck spent (12): no embersap or Vesh residue found. Broomwillow's Divine Sense detected no living beings or fiends inside. Periwink's aerial recon (16) mapped 4–5 main spaces, a courtyard, a tower and a three-story back portion."]]}, {"t": 7313, "kind": "combat", "title": "Periwink dies in the spores", "line": "Periwink was sent into the spores to test them. The constitution save failed, vision went black, roots covered everything — snuffed out on contact.", "facets": [["Combat", "Not permanent death — the familiar can be re-summoned. The effect was described as roots covering vision, not poison damage: rapid overgrowth and suffocation."], ["Decision", "The party retreated rather than enter, agreeing to return only with expert knowledge of the spores. Broomwillow painted the scene for a future expert to identify."], ["Item", "Bronze scales from Alevegond were rigged onto a rope perimeter alarm around camp."], ["New lore", "A settlement of 40–50 people is unaccounted for. The spores are Vesh-adjacent but duller and more necrotic than anything the party has met before — an \"undead version of growth.\""]]}, {"t": 7990, "kind": "dread", "title": "COWARDS", "line": "Overnight a mushroom patch grew thirty feet from camp, spelling a single word. Nyx burned it away with ember magic.", "facets": [["Threat", "The first direct communication from Vesh. It suggests awareness of the party's location, intelligence and intent — and that Vesh wants them to enter Kaer Maul."], ["House ruling", "Exhaustion was referenced: each point reduces d20 tests by 2× the level and speed by 5 feet per level, removed only by long rest, level 6 is death. Nyx considered an extra watch and chose not to take the point before a potential battle."]]}, {"t": 8530, "kind": "travel", "title": "The Brolin Forest riverbed", "line": "The party took a dried riverbed through the dense forest to save time and cleared it on four successes.", "facets": [["Check", "Periwink perception 18 navigated the branching riverbed; Nyx athletics 13 pushed the wagon through river rock; Ponzi nature 15 — visions of a dead dwarf explorer — avoided the mud patches; Talon perception 15 picked the choke points for Reduce, burning 2 spell slots."], ["Environment", "~10 miles of forest. Hazards: branching riverbed, wagon-churning river rock, deep mud, an underground river still filtering through gravel that surfaced near the exit — the party waded through icy water."], ["Check", "Ponzi and Talon with advantage (14+8 = 22) identified the correct river crossing south of Vattenheim."]]}, {"t": 9134, "kind": "travel", "title": "Vattenheim at dusk", "line": "They crossed a large wooden bridge and saw the City of the Wild — half-nestled into a cliffside, citadel dome above, dozens of Va banners, the city plunging into and hanging from the cliff.", "facets": [["Check", "A wild elf gate guard with curling ram horns granted entry after Broomwillow referenced the Va banners (6+7 = 13, +10 for the reference, ~17 effective). \"None will open his gates to you but do not betray the trust of the city of the wild. Come, driftwood. Come, friends of Va.\""], ["Environment", "Districts: Outer Wall, Inner Wall, Dawnside, Sow District, Reap District, Sky District (top of the cliffside) and Falls District (hanging upside down from the cliffside ceiling), with the Sunrise Citadel dominating. Eclectic population — wild elves with animal characteristics, satyrs, dwarves, humans as a minority, a woman made of flowing water."], ["New lore", "Vattenheim is a city of the Va Confederacy, a confederacy of many peoples of the wild lands. One banner is familiar to Broomwillow from her time in Va — the group is not yet identified."]]}, {"t": 9637, "kind": "social", "title": "Ude answers from the upside-down tower", "line": "The Pocket Wind carried a letter to Ude's tower in the Falls District, and he answered by sending stone — a voice in Broomwillow's head directing them to the Ethereal Leaf and Distillery.", "facets": [["Major NPC", "\"Oh hello, hello. You've arrived. I think I can see you. Meet me at the Ethereal Leaf in the distance. It's here, nearby, below the tower.\" Chess player, information broker, operating from a fine tower in the wealthiest district."], ["New lore", "The Festival of the Asterim is days away. Its symbol is a circle with three lines from the centre and a smaller circle on one side, tinted by the specific Asterim. Evidence throughout the city: religious symbols on clothing, dedicated flower bins for Vael the Tender, a mastercraft pot bearing Myes the Smith's symbol."]]}, {"t": 9859, "kind": "social", "title": "Gathering the displaced", "line": "Walking to the Ethereal Leaf, Broomwillow — in fox-tinted wild elf form — gathered homeless people in Vattenheim and replaced a child's stolen bread with her own. \"Come, be warm, be fed.\"", "facets": [["Character", "The little boy's hair flashed to match Broomwillow's red fox-tinted hair when she gave him the bread. Possible shapeshifter or changeling child — he recognised something in her."], ["Major NPC", "A massive, hulking half-orc with greenish skin, a broad smile and tusks joined the group and followed them to the bathhouse. \"Nice to meet you!\" \"I like more salt, but it's good.\""], ["Decision", "Nyx drew light guard attention aiding the poor but there was no incident."]]}, {"t": 10546, "kind": "scene", "title": "Madame Asalia's bathhouse", "line": "Turned away from the Ethereal Leaf for failing the dress code, the party was sent to a marble bathhouse fed by a waterfall from the cliffside — and spent freely.", "facets": [["Major NPC", "Madam Asalia: wild elf with slender antlers, auburn hair, extremely fine clothes, and a nictitating membrane that blinks sideways. She runs the bathhouse with a perfumer, seamstress and painters."], ["Check", "Bathhouse costs: base 15 gold per person. Broomwillow 2,000 gold (princess treatment plus painters). Talon 200 gold (fine treatment and clothing). Nyx 45 gold for himself and 2 guests plus a 55 tip — 100 total. Ponzi 75 gold for bath, glove, perfumer and seamstress."], ["Item", "Ponzi was fitted with a glove masking his deteriorating left hand, perfumed to mask the scent — a cosmetic fix only."]]}, {"t": 10930, "kind": "reveal", "title": "The steam illusions show them what they want", "line": "Enchanted steam in the pools formed each member's deepest desire, for those who did not resist.", "facets": [["Check", "Charisma saves: Broomwillow Nat 1 — gave in. Nyx 18 — resisted. Ponzi failed — gave in. Talon chose to resist."], ["Character", "Broomwillow saw the loving acceptance of someone separated from a parent for years, afraid to come back and welcomed in as if she never left — the homecoming of the prodigal son. Her greatest desire is to be chosen by an Asterim and welcomed home."], ["Character", "Nyx saw the shape of his wife's flowing hair beginning to form and resisted — \"she's not there\" — wary after recent hallucinations. His mind went instead to the vision cast at the castle of Olive Gand: Nyx in the middle of a great multitude with Scar fully restored beside him and a little girl at his side, smiling."], ["Character", "Ponzi saw a quiet, peaceful gathering of the Driftwood Kin and a dozen more people they'd helped, with music and food. \"Developer of a peaceful world around me.\""]]}, {"t": 11466, "kind": "clue", "title": "Asalia fishes, and the night ends", "line": "Broomwillow rolled 19 insight and caught Madame Asalia fishing — coded language and dropped words with meaningful looks, mannerisms Ponzi recognised from his own guild.", "facets": [["Threat", "Possible Thieves' Guild or spy network ties. Affiliation and intent unknown. She also suggested painters to adorn Broomwillow's porcelain skin."], ["Decision", "The session ended at the bathhouse, with the party due to return to the Ethereal Leaf and Distillery in fine clothes to meet Ude."]]}], "threads": [{"u": "hi", "q": "What happened to Kaer Maul's 40–50 people? No bodies, no foot traffic leaving, the wall blown outward from inside. Are they alive? Transformed?", "t": 7055}, {"u": "hi", "q": "Who claimed Broomwillow? Is it Arasil? Another Asterim? The Pocket Wind is ambiguous and the festival is the deadline.", "t": 798}, {"u": "hi", "q": "How long before Dawson closes the gap? He is tracking the party through 6+ means and was only temporarily distanced by the keep's teleport.", "t": 5012}, {"u": "hi", "q": "What is wrong with Ponzi's left hand? Deteriorating, consistently painful, shielded in sleep. The bathhouse glove is cosmetic only and the root cause is unknown.", "t": 1977}, {"u": "md", "q": "Why does Vesh want them inside Kaer Maul? \"COWARDS\" is the first direct communication — it is watching, and it is inviting.", "t": 7990}, {"u": "md", "q": "What is threatening Giovanni? \"Subtle danger here but mounting.\" Does he need extraction?", "t": 564}, {"u": "md", "q": "Can Scar be fully revived, and what does the Tender require for it?", "t": 4140}, {"u": "md", "q": "How would Low Tide actually be moved? The plan exists but there is no execution path — it needs planar gate magic or an equivalent.", "t": 5096}], "next": ["Get dressed in fine clothes and return to the Ethereal Leaf and Distillery to meet Ude", "Learn what Ude knows — information broker, chess player, Falls District tower", "Investigate the Festival of the Asterim — find opportunities for Broomwillow to seek her answer", "Explore Vattenheim's districts — especially the Falls District (Ude's tower) and the underground portions", "Identify the Va banner Broomwillow recognized — who is this group and what is her connection?", "Monitor Madame Asalia — is she Thieves' Guild? What does she want?", "Send update to Giovanni — assess his danger level and whether extraction is needed", "Research Vesh spores — find an expert on fungus/spores to plan a Kaer Maul counter-operation"], "entities": [{"name": "Pocket Wind", "kind": "item", "note": "Shifting wind creature — mouse, small winged feminine form, ball of wind. Carries letters to any named creature on the same plane, folds them into origami, stays with the recipient until they reply, gets impatient. ~12-hour delivery. Gift from Arasil's shrine. Unnamed.", "t": 109}, {"name": "Arasil", "kind": "npc", "note": "Lord of all the Asterim. Broomwillow asked at his shrine whether any Asterim had claimed her and received the Pocket Wind. About \"power, nobility, and decisiveness, not riddles.\"", "t": 798}, {"name": "Scar", "kind": "pc", "note": "Alive — torn in half and buried breathing in Driftwood Keep's greenhouse by the magic of the Tender. The ground rises and falls with his chest. His presence is what drew the keep to the grove.", "t": 4140}, {"name": "Giovanni", "kind": "npc", "note": "Alive, in subtle but mounting danger, looking for his next venture. Holds the paired sending stone and is now reachable by Pocket Wind. Replied with \"Quest of Elmore\" — the Voyagers' motto.", "t": 564}, {"name": "Ude", "kind": "npc", "note": "Chess player and information broker in an upside-down tower in Vattenheim's Falls District. Answered the Pocket Wind letter by sending stone and directed the party to the Ethereal Leaf and Distillery. Spelled Oud/Ubi in the Project Sync section.", "t": 9504}, {"name": "Madam Asalia", "kind": "npc", "note": "Wild elf with slender antlers, auburn hair, extremely fine clothes and a sideways nictitating blink. Runs the Sky District bathhouse. Fishing for information with coded language — possible Thieves' Guild or spy ties.", "t": 10593}, {"name": "Dawson", "kind": "npc", "note": "Tracking the party through \"six different things\" and was within a day of Alama before the keep's teleport gave them distance. Actively hunting.", "t": 5012}, {"name": "Periwink", "kind": "creature", "note": "The party's familiar. Flew aerial recon over Kaer Maul, then dove into the spores and was snuffed out — vision black, roots covering everything. Not permanent death.", "t": 7313}, {"name": "Wild Elf Gate Guard", "kind": "npc", "note": "Long elven ears, ram horns curling up and down, a two-part helm rejoining at the crown. Granted entry after the Va banner reference. \"Come, driftwood. Come, friends of Va.\"", "t": 9245}, {"name": "Ethereal Leaf Hostess", "kind": "npc", "note": "Elven woman with a sideways nictitating blink. Turned the party away for a dress code violation and sent them to Madame Asalia's Bathhouse.", "t": 10293}, {"name": "Half-Orc Street Companion", "kind": "npc", "note": "Massive, hulking, greenish skin, broad smile, tusks. Joined Broomwillow while she gathered the displaced and followed the party to the bathhouse.", "t": 10045}, {"name": "Street Child", "kind": "npc", "note": "Little boy caught stealing bread; his hair flashed to match Broomwillow's red fox-tinted hair when she replaced it. Possible shapeshifter or changeling.", "t": 9859}, {"name": "Jeff", "kind": "npc", "note": "Dead, as far as the party knows. Dawson is \"probably really playing it on thick for everybody else\" regarding his death.", "t": 607}, {"name": "Vesh", "kind": "faction", "note": "Responsible for Kaer Maul's destruction via orange spores. Sent the party a direct taunt — \"COWARDS\" — as a mushroom patch. Operates through corruption and indirect means rather than direct attack.", "t": 7990}, {"name": "The Asterim", "kind": "faction", "note": "The divine pantheon. Arasil (Lord of all Asterim), Vael/the Tender (growth, nature, sacred groves), Myes the Smith (great crafter). The Festival of the Asterim is days away in Vattenheim.", "t": 798}, {"name": "Va Confederacy", "kind": "faction", "note": "A confederacy of many peoples of the wild lands. Vattenheim is a major Va city, adorned with dozens of Va peoples' banners. Broomwillow has history in Va.", "t": 9222}, {"name": "The Northern Alliance", "kind": "nation", "note": "Controls Low Tide and extracts money from its population. Its people are free but economically trapped; any physical aid will be countered.", "t": 5138, "alias": "Northern Alliance"}, {"name": "Sacred Lattice Dome", "kind": "place", "note": "Miles-wide dome of woven riverwater at the fork of the Alder River. Warm, misted, oversized flora, giant elk with bronze-damascus antlers, a central column of luminescent water. Primal/celestial magic. Sacred ground of Vael/the Tender.", "t": 1193}, {"name": "Driftwood Keep", "kind": "place", "note": "Relocated from Nastra Antheon into the sacred grove inside the dome. Greenhouse holds Scar, a grafted rose, and the planted Veins of Yavanna. Giant elk stand watch outside.", "t": 4182}, {"name": "Kaer Maul", "kind": "place", "note": "Small stone fortress at the edge of the Brolin Forest. Gate barred with spiked barriers, one wall section blown outward from inside, interior choked with dull orange spores and decayed lichen. No bodies. 40–50 people unaccounted for.", "t": 6441}, {"name": "Vattenheim", "kind": "place", "note": "City of the Wild. Half-nestled into a cliffside with the Sunrise Citadel above. Districts: Outer Wall, Inner Wall, Dawnside, Sow, Reap, Sky (top of the cliff) and Falls (hanging upside down from the cliffside ceiling).", "t": 9162}, {"name": "Brolin Forest", "kind": "place", "note": "Dense dark forest crossed on a dried riverbed — ~10 miles of branching bed, wagon-churning river rock, deep mud, and an underground river that surfaced near the exit.", "t": 8400}, {"name": "Giant Elk", "kind": "creature", "note": "Multiple elk ~15–20 feet tall with bronze-damascus antlers inhabiting the dome. Guardians of the grove; they walked peacefully among the party after the keep arrived.", "t": 4046}, {"name": "Splinter Dart", "kind": "item", "note": "Ponzi's nat-20 craft. Fires and explodes outward to hit multiple opponents, recoverable and reusable, carrying conjuration magic beyond what he put in.", "t": 5666}, {"name": "Veins of Yavanna", "kind": "item", "note": "Red root with iron content and primal magic that touches the life force of a person. Workable into potions replicating Hold Person, Paralyze, Charm Person, Suggestion and Geas. Planted in the sacred greenhouse.", "t": 5833}, {"name": "Talon's Field Mouse", "kind": "creature", "note": "Emerald-green-eyed field mouse that followed Talon out of the dome after his fife playing and nests in his hood. Still needs a name (not Mickey).", "t": 6272}], "gaps": ["The source never names the DM — it refers only to \"the DM\", so `dm` is left null.", "The note contradicts itself on who rolled the natural 20 divine vision on watch: the Layer 1 digest and \"Broomwillow's Watch Vision (Nat 20)\" credit Broomwillow, while the mechanics list and \"Nyx's Vision (Nat 20 Watch)\" credit Nyx. The beat and card are written without attributing the roll to either.", "Character names vary across the note's sections: \"Broomwillow\" / \"Brunie\" / \"Rune Willow\" / \"RuneWillow\" for the same character; \"Talon\" / \"Talendir\"; \"Nyx\". Both timecoded and untimecoded sections were kept as spelled.", "Place and NPC spellings vary: \"Vael\" / \"Valien the Tender\"; \"Alama\" / \"Olama\"; \"Brolin Forest\" / \"Brolen Forest\"; \"Asterim\" / \"Aces\"; \"Ude\" / \"Oud\" / \"Ubi\"; \"Madam Asalia\" / \"Madame Asalia\". Names are copied as spelled in the section they came from.", "The NPC INDEX entry for Ude is corrupted in the source — the entry's heading reads only \"arm\", though its body clearly describes Ude's upside-down Falls District tower and sending-stone reply.", "The Project Sync section credits the Splinter Dart to Talon, while every timecoded section credits it to Ponzi. The timecoded attribution (Ponzi) was used."], "iso": "2026-04-23", "pretty": "23 Apr 2026", "audio": false, "legendary": false, "n": 11}, {"slug": "chess-piece-secret-society", "title": "Chess Piece and Secret Society Introduction", "date": "04/13/2026 20:45", "runtime": "1h 14min 16s", "nottaId": "c86ac790-897a-47d5-93c4-17bdab403e68", "url": "https://app.notta.ai/7366972874555052032/dashboard/c86ac790-897a-47d5-93c4-17bdab403e68", "template": "D&D Session Noters: V3", "hasTimecodes": true, "timecodesReliable": false, "durationSec": 4456, "subtitle": "A knight passed, a scar shared", "logline": "Runewillow hands Ponzi the chess society's knight, a priestess in Olama takes his pain into her own hand, and a whistling shrine stops them in the hills.", "recap": "Previously on Driftwood Kin…\nThe long rest was almost over when Runewillow moved through the dark camp without a word, set down a chessboard, and looked at Ponzi. No explanation. Just pieces. And then, quietly, a secret — a society hidden in the language of chess, and a knight piece that had been weighing on her since the day she received it. She pressed it into his hands. It belonged with him.\nThey returned to Olama with the horses they'd stolen in the night, and faced the woman they'd wronged. She was waiting. She always was. They paid what they owed, and then some — gold, bread, and the truth. She let them keep the horses.\nAt the Temple of Aileena, Ponzi walked into a place he'd never been, hat in hand, no idea what he was doing. The high priestess saw his ruined hand and said: come. She washed it. She prayed over it. And then she bit down on a wooden dowel, grabbed his hand, and walked into his pain with him. She felt the stab. She felt the door. She felt the moment he almost didn't come back — and the hand of his wife holding him in the dark. When it was over, she was on the floor, and she had a scar on her palm that hadn't been there before. \"That should have killed you,\" she said. Ponzi put his diamond on the altar.\nTalon sat alone in the temple and felt nothing. An old man who smelled of flour put a hand on his head and left a loaf of bread beside the diamond. It wasn't nothing.\nThey left Olama behind — the city of the blind, the roses, the bread, the scars — and rode north into the hills. The wind was sharp and cold. And then they heard it: a pure, unbroken whistle, cutting through the grass. On the top of the next hill, a stone spire. Three arms reaching into the sky. Elvish words carved into the stone: May the wind carry his song wherever it may go. And beneath it all, the hum of conjuration magic, waiting.", "dm": null, "party": ["Runewillow (Rune Willow)", "Ponzi", "Talon", "Nix"], "opens": "End of a long rest at camp, post-rescue of Ponzi", "closes": "The whistling stone shrine on a hill south of Caramall, conjuration magic humming", "cards": {"changed": {"headline": "Ponzi is the chess society's liaison now", "detail": "Runewillow decided the notched knight piece and the society connection belong with Ponzi more than with herself, taught him the covert opening, and transferred the piece into his inventory along with her chessboard on loan. The society's attention may now shift toward him.", "t": 1}, "learned": {"headline": "Ponzi's hand carries a mark, and he should be dead", "detail": "Priestess Akira identified the silver magical stitching from Talon's healing as bearing the mark of \"Zastas the Delta\", and after walking into his pain concluded flatly that the poison should have killed him — implying he has been close to the judgment hall in a way that is spiritually significant.", "t": 1460}, "who": {"headline": "Priestess Akira", "detail": "The high priestess of the Temple of Aileena the Bride saw a stranger's ruined hand, washed it, prayed over it, then bit down on a wooden dowel and shared his pain exactly — ending on the floor with a new scar on her own palm and the verdict \"that should have killed you.\" She is also the one who pointed the party at Vattenheim.", "t": 1368}, "cost": {"headline": "A diamond, a scar, and 350 gold", "detail": "Ponzi gave up his one diamond on the temple altar. Akira now permanently carries a scar from his pain. The party spent 350 gold on healing potions, gave the stable woman 10 extra gold plus bread, and Runewillow left the blind tattoo artist a fire bundle, bread and 10 gold — and gave away her last stick of incense, which she needs to summon her familiar.", "t": 35}, "hanging": {"headline": "What is the shrine for?", "detail": "The session stops in front of a three-armed stone spire humming with conjuration magic, inscribed in Elvish — \"May the wind carry his song wherever it may go\" — bearing symbols that resemble Arasil the Ruler or Vela the Devoted. Nobody knows whose it is, what it does, or whether touching it is safe.", "t": 3944}}, "beats": [{"t": 1, "kind": "social", "title": "A chessboard set down without a word", "line": "On the final watch before the long rest, Runewillow crossed the dark camp, set up a portable chessboard and taught Ponzi chess — then told him about the secret society hidden in its opening moves.", "facets": [["Decision", "She decided the notched knight piece and the society connection belong with Ponzi more than with herself, and transferred it from her inventory to his. She left the portable chessboard with him on loan."], ["Character", "Runewillow: \"I am relieved to have you back in the group. I'm glad you are somewhat okay.\" Ponzi: \"It's good to be back. Thank you guys for coming to get me. I never said it properly.\""], ["Character", "Talon watched from a distance and sensed Runewillow's tension with Ponzi easing slightly."]]}, {"t": 98, "kind": "lore", "title": "A society that speaks in chess", "line": "The secret society is connected to chess pieces and identifies its members through specific opening moves — a thieves' cant played on a board.", "facets": [["New lore", "Playing the opening exposes you. If the opponent responds in kind, they are in the society; if they exploit the exposure, they are just a good chess player."], ["New lore", "The notched knight piece came from the chess player in Olama and is meant to be delivered to a contact in Vattenheim; the notch identifies it."], ["Faction", "UNSOLVED: the society's full scope, membership, goals and hierarchy are unknown."]]}, {"t": 144, "kind": "social", "title": "Ponzi lies about his parents", "line": "Asked why he never learned chess, Ponzi claimed his parents died before he could. Runewillow saw through it immediately.", "facets": [["Check", "Insight — she saw through it on the spot (high roll implied)."], ["Character", "The lie is the revealing part: why fabricate a tragic backstory for something as simple as not knowing chess?"]]}, {"t": 356, "kind": "rule", "title": "Talon can't learn chess secondhand", "line": "Talon tried to pick up the lesson from a distance at disadvantage and rolled a 7 — he does not learn chess.", "facets": [["Check", "Intelligence check at disadvantage, result 7 — failed."], ["Character", "He did, however, observe the exchange and read the easing tension between Runewillow and Ponzi. Runewillow's chessboard stays with Ponzi as a teaching tool."]]}, {"t": 460, "kind": "scene", "title": "Long rest completed", "line": "The party finished the long rest with all resources recharged.", "facets": [["Character", "Session start point: end of a long rest at camp, post-rescue of Ponzi. Party present: Runewillow, Ponzi, Talon, Nix."]]}, {"t": 550, "kind": "social", "title": "Facing the stable woman in Olama", "line": "The party rode back into Olama with the horses they had taken in an emergency, and the stable woman was outside tending horses. She recognised them at once.", "facets": [["Major NPC", "She acknowledged the payment and note they had left but said: \"That's not exactly how transactions work.\" Pragmatic, firm but fair, not vindictive."], ["Check", "Persuasion to purchase the horses: 13 — only slightly persuaded, but she accepted. \"Bygones be bygones.\" The party added 10 gold and a loaf of bread; she noted the bread was overdoing it."], ["Environment", "She called the wagon \"a bit of a technological marvel\" and said it was in perfect condition — but that strange folk had been around the wagon area, and that a two-wheeled cart belonging to enemies was stolen or destroyed nearby. The party confirmed they had likely destroyed it."], ["Environment", "Olama: small city, horse stable on the outskirts, general goods store, tattoo shop, two temples (Aileena, Eratos). No apothecary and no magic item shop."]]}, {"t": 1039, "kind": "lore", "title": "The other temple in Olama", "line": "Olama's second temple belongs to Eratos, described as a champion or healer deity. The party did not visit it.", "facets": [["New lore", "Suzelaina is Eratos' wife."]]}, {"t": 1223, "kind": "item", "title": "Runewillow's last stick of incense", "line": "Runewillow gave Ponzi her last stick of incense to offer at the temple.", "facets": [["Item", "She needs incense to summon her familiar again — and the diamond went on the altar instead, so the incense came back to her."]]}, {"t": 1239, "kind": "scene", "title": "The Temple of Aileena the Bride", "line": "Blooming rose gardens outside, tall lead-light windows within, and individual alcoves for private worship rather than a communal hall.", "facets": [["New lore", "Aileena the Bride is the Lady of Love. Her temple uses incense burned at weddings, everlasting roses, and intimate individual alcoves. Her magic smells of flowers and roses."], ["Environment", "An offerings altar — where Ponzi's diamond and the baker's bread ended up — and a rose garden that is the source of the everlasting roses given to worshippers."]]}, {"t": 1368, "kind": "social", "title": "Akira sees the hand", "line": "Priestess Akira — an elven woman with flowing blonde hair that shimmers rose-gold — greeted them, saw Ponzi's necrotic hand, and led him to an alcove.", "facets": [["Character", "Ponzi removed his hat and bowed his head, clearly out of his element. \"I don't even know how to start though.\" Akira: \"Many don't know how to start.\""], ["Major NPC", "High Priestess of the Temple of Aileena the Bride. Empathic healing, floral-scented healing magic, reads emotions acutely."]]}, {"t": 1422, "kind": "magic", "title": "She bites the dowel and walks into his pain", "line": "Akira washed Ponzi's hand in a basin, cast a healing spell that changed nothing visible, then proposed an empathic ritual: she would experience exactly what he had experienced.", "facets": [["Character", "Ponzi warned her: \"My life has been one of constant pain, so are you sure you can handle this?\" She limited the scope to just this event."], ["Environment", "A male priest in robes was summoned to assist if needed — he could not see what she saw. Her wooden dowel already bore bite marks from previous use."], ["Combat", "She grabbed his hand and arcane light mirrored on her own. Both felt it simultaneously — Ponzi relived the stabbing and being pinned to the door handle. She ended up on the floor, still holding his hand, and the priest helped her up."], ["Character", "A lighter scar appeared on Akira's hand. She now permanently bears a mark of his pain."]]}, {"t": 1460, "kind": "reveal", "title": "The mark of Zastas the Delta", "line": "Akira identified the silver magical stitching on Ponzi's hand — Talon's healing work — and noted that it bears the mark of \"Zastas the Delta.\"", "facets": [["New lore", "The stitching denotes magical healing of a specific divine or arcane origin, tied to Talon's healing magic."]]}, {"t": 1808, "kind": "reveal", "title": "His wife's hand in the dark", "line": "Inside the shared vision everything went white and Ponzi saw himself from outside his own body, holding his own hand — and remembered his wife holding it in that moment.", "facets": [["Character", "A deeply personal, previously unmentioned detail: in his moment of greatest pain, his mind went to his wife."]]}, {"t": 1848, "kind": "dread", "title": "\"That should have killed you\"", "line": "Akira's conclusion was blunt. The poison should have killed him — and she implied he has been close to the judgment hall, the threshold of death, in a way that is spiritually significant.", "facets": [["Major NPC", "She said she is not an expert on poison, but is an expert on what is happening to him spiritually. She recommended Vattenheim's temples for answers."], ["Threat", "At least one religious authority now knows about Ponzi's unusual proximity to death. That may have ripple effects."], ["New lore", "UNSOLVED: is this a recurring condition or a one-time event? The implication is that Ponzi may have a destined role."]]}, {"t": 31, "kind": "clue", "title": "Vattenheim, a city of faiths", "line": "Akira recommended Vattenheim — a city of faiths whose temples may hold answers for Ponzi's condition — and mentioned a festival happening there soon.", "facets": [["New lore", "The chess player's timeline for relaying information aligns with the same festival."], ["Decision", "She implies Ponzi may have spiritual business in Vattenheim, not just courier business."]]}, {"t": 35, "kind": "item", "title": "The diamond on the altar", "line": "Runewillow had given Ponzi her last stick of incense to offer. After the ritual he judged it insufficient and put his one diamond on the offering altar instead.", "facets": [["Major NPC", "Akira smiled: \"Know that your generosity will help others.\" She invited him to take a rose from the garden — \"Tend to it well — even without soil and water, those roses persist.\""], ["Item", "Ponzi carefully selected a bright red everlasting rose. Teased afterwards about being love-struck, he simply looked at the rose."], ["Character", "A massive sacrifice from a character who hoards resources — a signal of genuine spiritual impact."]]}, {"t": 44, "kind": "scene", "title": "Talon feels nothing, and the old baker", "line": "Talon sat alone inside the temple trying to feel something and feeling nothing — then a very old, heavily wrinkled man who smelled of flour put a hand on his shoulder.", "facets": [["Check", "A religion check of 25 — exceptional — and still no connection."], ["Major NPC", "The old man: \"On to my life for someone who has no want, no claim,\" then, hands laid fatherly on Talon's head, \"Well, if the words of an old baker can be any comfort to you, then I've done my journey.\""], ["Character", "He walked to the altar and set a small loaf of bread beside Ponzi's diamond. Talon left not sad but curious — \"an interesting thought.\""], ["New lore", "UNSOLVED: is he a mortal baker, a divine figure, or a manifestation of Aileena's mercy? His words carry unusual weight."]]}, {"t": 2603, "kind": "item", "title": "Restocking at the temple", "line": "The Temple of Aileena stocks healing potions — rosé-coloured and sparkling in crystalline containers — and a roll of 17 meant the good ones were available.", "facets": [["House ruling", "Availability roll: d20, 6+ for potions, 15+ for quality potions. Rolled 17 — superior and greater potions available. Stats: common 2d4+2, greater 4d4+4, superior 8d4+8."], ["Item", "Prices: common 50 gp, greater 100 gp, superior 500 gp. Nix bought 1 greater + 1 common (150 gp); Ponzi 1 greater (100 gp); Talon 1 greater (100 gp)."]]}, {"t": 50, "kind": "social", "title": "Goodbye to the blind brother", "line": "Runewillow stopped to say goodbye to the blind tattoo artist she calls her \"blind brother.\" He refused payment for sewing needles and gifted her a dozen.", "facets": [["Character", "She left him a fire bundle, a loaf of bread and 10 gold — \"For the next travelers you meet.\" Her parting words: \"May the city of the blind stand strong — sight and steel.\""], ["Major NPC", "He embraced her: \"I know Olama's small, but come by soon again. Don't be drinking.\""]]}, {"t": 55, "kind": "travel", "title": "North out of Olama", "line": "After a final rest the party left Olama bright and early, bound for Caramall on a roughly direct route rather than hugging the Ald River.", "facets": [["Decision", "Direct route ~1.5 days versus ~2 days along the river; they chose the straight shot, at normal pace, keeping the horses and wagon."], ["Threat", "They deliberately routed east to avoid the hill giants in the region."], ["Decision", "The chess player in Olama wants information gathered in Caramall for relay to the Vattenheim contact — and they must not linger, because the festival is the constraint."]]}, {"t": 60, "kind": "plan", "title": "The village whose river shipments stopped", "line": "Friends of the party in the region have stopped receiving river shipments from a small village on their route, and the party agreed to look into it while passing through.", "facets": [["Threat", "Unknown cause — anything from a natural disaster to a hostile force blocking trade."], ["Environment", "The village is marked on the map, on the route north."]]}, {"t": 3489, "kind": "travel", "title": "Into the hill country", "line": "The party pushed north-northwest into steeper hills, wind whipping the grasses and the season dipping into winter.", "facets": [["Check", "Runewillow's nature check for travel: 13, middle of the road. Random encounter check (encounter on 18–20): no encounter triggered."], ["Environment", "Ald River running through the region with the party east of it; Crestfall Wood to the west. The winds cut and bite."]]}, {"t": 3944, "kind": "reveal", "title": "The whistling shrine", "line": "Talon heard a pure, high-pitched whistle cutting through the wind. Cresting a hill they saw, on the next and higher one, a stone shrine about 5 feet wide and 12 feet tall with a long thin slit at its top.", "facets": [["Check", "Perception: Talon 18, Nix 21, Ponzi 12, Runewillow 18. They followed the sound cautiously, with stealth. Talon's closer look: 23. Ponzi's investigation: 14 — found the inscription. Nix's faith: 22 — divine sense activated."], ["New lore", "Runewillow, who speaks Elvish, read the inscription: \"May the wind carry his song wherever it may go.\""], ["Environment", "The structure breaks into three arms — two shorter side arms and one taller central spire — resembling the symbols of Arasil the Ruler or Vela the Devoted. Located on a high hill south of the branching Ald River and east of Crestfall Wood."], ["Item", "Nix's wand detected conjuration magic. The session ends at the shrine."], ["New lore", "UNSOLVED: what deity or figure does it belong to? Waypoint, summoning site, memorial — or trap?"]]}], "threads": [{"u": "hi", "q": "What is the full nature of Ponzi's spiritual proximity to the judgment hall, and what happens if it recurs?", "t": 1848}, {"u": "hi", "q": "Who is the chess society contact in Vattenheim, and what information do they need out of Caramall?", "t": 55}, {"u": "hi", "q": "What happened to the village whose river shipments stopped?", "t": 60}, {"u": "md", "q": "What does the whistling shrine's conjuration magic do? Who built it, and for whom?", "t": 3944}, {"u": "md", "q": "Who were the strange folk seen near the wagon in Olama — are they connected to the party's enemies?", "t": 879}, {"u": "md", "q": "Is the old baker mortal or divine, and what was the significance of his words to Talon?", "t": 44}, {"u": "md", "q": "What does Talon's inability to feel anything in the temple, despite a 25 religion roll, mean for his faith arc?", "t": 44}, {"u": "lo", "q": "Is Runewillow's tension with Ponzi fully resolved, or still simmering?", "t": 404}], "next": ["Investigate the whistling stone shrine — determine what the conjuration magic does and whether interacting with it is safe or beneficial", "Continue travel to Caramall — gather the information requested by the chess player for relay to the Vattenheim contact", "Investigate the village with stopped river shipments (on the route)", "Reach Vattenheim before the festival — deliver the notched knight piece and make contact with the chess society member", "Seek out Vattenheim's temples for answers about Ponzi's spiritual condition and proximity to the judgment hall", "Track down or account for the two enemies left at the tavern in Olama", "Runewillow needs to purchase more incense to restore her familiar-summoning capability", "Monitor Ponzi's hand — the necrosis is not resolved, only understood better"], "entities": [{"name": "Priestess Akira", "kind": "npc", "note": "Elven woman with flowing blonde hair that shimmers rose-gold. High Priestess of the Temple of Aileena the Bride in Olama. Performed the empathic ritual on Ponzi and now bears a scar on her own hand. \"Yes, yes, that should have killed you.\"", "t": 1368}, {"name": "The Old Baker", "kind": "npc", "note": "Very old, heavily wrinkled man who smells of flour. Comforted Talon with a hand on his head and left a small loaf of bread on the altar beside Ponzi's diamond. Mortal, divine figure, or manifestation of Aileena's mercy — unresolved.", "t": 44}, {"name": "Blind Tattoo Artist", "kind": "npc", "note": "Blind tattoo artist in Olama, called \"blind brother\" by Runewillow. Refused payment and gifted her a dozen sewing needles. \"I know Olama's small, but come by soon again. Don't be drinking.\"", "t": 50}, {"name": "Stable Woman", "kind": "npc", "note": "Unnamed woman who tends horses outside her stable in Olama. Pragmatic, firm but fair. Accepted the party's apology and payment, and warned them about strange folk near the wagon.", "t": 620}, {"name": "The Chess Society", "kind": "faction", "note": "Secret society connected to chess pieces, using specific opening moves as a covert language of recognition. A contact in Vattenheim is expecting the notched knight piece before the festival. Scope, membership, goals and hierarchy unknown.", "t": 98}, {"name": "Temple of Aileena the Bride", "kind": "faction", "note": "Healing and compassion-focused temple in Olama, stocking healing potions. Aileena is the Lady of Love. Connected to Vattenheim's festival network.", "t": 1239}, {"name": "Temple of Eratos", "kind": "faction", "note": "Olama's second temple. Eratos is described as a champion or healer deity; Suzelaina is his wife. Not visited this session.", "t": 1039}, {"name": "Olama", "kind": "place", "note": "Small city — the city of the blind. Horse stable on the outskirts, general goods store, tattoo shop, two temples. No apothecary and no magic item shop.", "t": 550}, {"name": "The Whistling Stone Shrine", "kind": "place", "note": "~5 ft wide, ~12 ft tall, on a high hill south of the branching Ald River and east of Crestfall Wood. Long thin slit at the top whistles in the wind. Three arms resembling the symbols of Arasil the Ruler or Vela the Devoted. Radiates conjuration magic.", "t": 3944}, {"name": "Hills Between Olama and Caramall", "kind": "place", "note": "Steep, windy hill country dipping into winter. Ald River through the region, Crestfall Wood to the west, hill giants routed around to the east.", "t": 3489}, {"name": "Notched Knight Chess Piece", "kind": "item", "note": "Obtained from the chess player in Olama and transferred from Runewillow to Ponzi. Delivery item for a chess society contact in Vattenheim — the notch identifies it.", "t": 322}, {"name": "Everlasting Red Rose", "kind": "item", "note": "Gifted to Ponzi by Priestess Akira from the Temple of Aileena's garden. Persists without soil or water.", "t": 35}, {"name": "Portable Chessboard", "kind": "item", "note": "Runewillow's, left on loan to Ponzi as a teaching tool.", "t": 426}, {"name": "Sewing Needles", "kind": "item", "note": "A dozen, gifted to Runewillow by the blind tattoo artist in Olama.", "t": 50}, {"name": "Zastas the Delta", "kind": "npc", "note": "Named by Akira as the mark borne by the silver magical stitching on Ponzi's hand — the signature of Talon's healing magic's divine or arcane origin.", "t": 1460}, {"name": "Arasil the Ruler", "kind": "npc", "note": "One of two figures whose symbols the three-armed shrine resembles.", "t": 4154}, {"name": "Vela the Devoted", "kind": "npc", "note": "The other figure whose symbols the three-armed shrine resembles.", "t": 4154}, {"name": "Aileena the Bride", "kind": "npc", "note": "The Lady of Love. Her worship uses incense burned at weddings, everlasting roses and intimate individual alcoves; her magic smells of flowers and roses.", "t": 1239}], "gaps": ["Several mid- and late-session entries carry sub-one-minute timecodes in Notta's own note (e.g. 00:00:35 for Ponzi's diamond offering, 00:00:44 for the old baker, 00:00:50 for the blind tattoo artist, 00:00:55 for the departure from Olama) despite clearly occurring after the 00:20:39 temple scene; the stamps are preserved exactly as the source gives them but should not be trusted for audio seeking.", "Because of that, `beats` in this file are ordered in true NARRATIVE order, not by ascending `t` — unlike the other sessions in this vault. Reading order is correct; sorting this file by `t` will scramble it.", "The source never names the DM, so `dm` is left null.", "The note contradicts itself on who rolled the 25 religion check in the temple: the MAJOR EVENTS section attributes it to Talon, the MECHANICS section to Nix. Written as Talon's moment, following the narrative section.", "The note contradicts itself on the knight piece's origin: the LORE entry says \"Ponzi was not present\", the ITEMS entry says \"Runewillow was present, Ponzi was not\" — consistent — but the Project Sync section calls it \"from prior tavern contact\", which does not match.", "Place-name spelling varies across the note: \"Olama\"; \"Caramall\" / \"Caramol\"; \"Aileena\" / \"Ailena\"; \"Runewillow\" / \"Rune Willow\"; \"Vattenheim\". Names are copied as spelled in the section they came from."], "iso": "2026-04-13", "pretty": "13 Apr 2026", "audio": false, "legendary": false, "n": 10}, {"slug": "divine-sense-and-curse-detection", "title": "Dungeons and Dragons Campaign: Divine Sense and Curse Detection", "date": "04/13/2026 20:14", "runtime": "9min 57s", "nottaId": "40929d52-b3fc-45e3-8e27-88d52b6427c9", "url": "https://app.notta.ai/7366972874555052032/dashboard/40929d52-b3fc-45e3-8e27-88d52b6427c9", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 597, "subtitle": "One hand warm, one hand cold", "logline": "On night watch Nyx finds Ponsey's hand unnaturally cold, and five points of Lay on Hands burn pale green without warming it.", "recap": "\"Previously on…\"\nThe night was quiet, but quiet is never safe. Nyx stood watch as Ponsey stirred from a state no one wanted to name — too far gone, too unlike himself. She helped him up, and that's when she felt it: one hand warm, one hand cold. A cold she had only ever felt once before, on Rune. She poured five points of her healing light into him — ember orange turned pale green, and the cold hand did not warm. Something in Ponsey is beyond her reach. Something unholy. Something that doesn't want to be found.\nThey sat together in the dark, two soldiers at the edge of a fire that was going out. They talked about Scar — the one who mattered, the one who's gone. And then Nyx began to ask about the dragon. About Algana. About what happened at Umbers Hill.\nThe hand stayed cold.", "dm": null, "party": ["Nyx", "Ponsey / Talon", "Rune"], "opens": "Night watch; Ponsey/Talon has just recovered from being heavily intoxicated or poisoned.", "closes": "Casual downtime at watch post; conversation about Bronze Dragon Algana begins; dice games proposed.", "cards": {"changed": {"headline": "Ponsey's hidden affliction is now known to Nyx", "detail": "Ponsey's hand condition is now known to Nyx — a secret or hidden affliction has been partially revealed within the party. Scar is also confirmed gone from the party.", "t": 258}, "learned": {"headline": "The cold hand is immune to divine healing", "detail": "The cold hand appears resistant or immune to divine healing magic, suggesting a deep-seated necrotic curse or supernatural affliction beyond standard poison.", "t": 320}, "who": {"headline": "Ponsey / Talon", "detail": "The session turned on Ponsey: afflicted, emotionally guarded and unreadable, he is the one carrying the cold hand that mirrors Rune's, and the one who admits Scar \"had an impact I never had.\"", "t": 409}, "cost": {"headline": "Five points of Lay on Hands spent for nothing", "detail": "Nyx expended 5 points of Lay on Hands attempting to cleanse poison/necrotic effect; the healing magic visibly failed to warm the cold hand — no change detected.", "t": 276}, "hanging": {"headline": "What connects Rune's cold hand to Ponsey's?", "detail": "Why does Ponsey's hand feel exactly like Rune's? Are they connected by the same curse, entity, or event — or is Rune the source?", "t": 94}}, "beats": [{"t": 0, "kind": "scene", "title": "A bad state on night watch", "line": "Ponsey/Talon is in a deteriorated state during night watch — described as smelling bad, visibly unwell.", "facets": [["Environment", "Night Watch Camp: the party is on a night watch rotation. Rune is asleep. The setting is quiet and dark."], ["Character", "Recently intoxicated/high earlier; antidote already taken."]]}, {"t": 39, "kind": "scene", "title": "The offered hand is ice cold", "line": "Talon rolls over and offers a hand up to Nyx (or vice versa); Nyx notices the hand is ice cold.", "facets": [["Character", "Talon/Ponsey wakes from what appears to be a poisoned/drugged state; Nyx assists him up."], ["Observation", "Pain upon gripping; general warmth felt elsewhere on the body."]]}, {"t": 67, "kind": "clue", "title": "A cold only ever felt on Rune", "line": "Nyx identifies the cold hand as matching the sensation previously only felt with Rune — a significant and alarming parallel.", "facets": [["Unsolved", "What connects Rune and Ponsey? Is this the same affliction, curse, or entity?"], ["Threat", "If Rune shares this affliction, both party members may be compromised."]]}, {"t": 111, "kind": "magic", "title": "Divine Sense finds something off and unholy", "line": "Nyx uses Divine Sense: detects something \"off\" and \"unholy\" but no active curse confirmed on the hand or elsewhere.", "facets": [["Check", "Divine Sense (Paladin — Nyx): detected something \"off and unholy.\" No active curse confirmed."], ["Check", "Medicine check rolled in tandem: result of 3 (very low). Insufficient to diagnose the condition."]]}, {"t": 148, "kind": "rule", "title": "DM: poison or necrotic magic", "line": "DM notes the hand could be simple poison OR a necrotic spell/magic/curse.", "facets": [["House ruling", "The failed Lay on Hands and pale green flame suggest the latter."]]}, {"t": 177, "kind": "rule", "title": "Lay on Hands does cure poison", "line": "Lay on Hands — Poison Cure Confirmed: 5 points of Lay on Hands does cure poison per ruling, but had no effect here.", "facets": [["House ruling", "Confirmed at the table that 5 points of Lay on Hands cures poison."]]}, {"t": 243, "kind": "lore", "title": "Nyx's ex-Druid background may matter", "line": "HOOK: Nyx (ex-Druid) notes she would know more about necrotic poison than unholy afflictions — her background may be relevant to diagnosing Ponsey's condition.", "facets": [["Character", "Nyx (Paladin, ex-Druid background mentioned)."]]}, {"t": 258, "kind": "reveal", "title": "A hidden affliction surfaces inside the party", "line": "Ponsey's hand condition is now known to Nyx — a secret or hidden affliction has been partially revealed within the party.", "facets": [["World state", "Ponsey's affliction is no longer entirely his own secret."]]}, {"t": 276, "kind": "magic", "title": "Five points of Lay on Hands fail", "line": "Nyx expends 5 Lay on Hands points; healing warmth is felt on Ponsey's face and upper arm but NOT on the afflicted hand itself.", "facets": [["Check", "Lay on Hands — 5 Points: used to attempt poison/curse cleanse. Result: no effect on the cold hand."], ["Cost", "5 points of Lay on Hands expended with no change detected."]]}, {"t": 298, "kind": "item", "title": "An antidote already taken", "line": "Antidote: Ponsey had already taken an antidote prior to this scene — suggesting a known poison was administered or ingested. Source and type unspecified.", "facets": [["Item", "Antidote — source and type unspecified."], ["Note", "No other items, loot, or artifacts mentioned in this session."]]}, {"t": 320, "kind": "reveal", "title": "The hand resists divine magic", "line": "The cold hand appears resistant or immune to divine healing magic, suggesting a deep-seated necrotic curse or supernatural affliction beyond standard poison.", "facets": [["Foreshadowing", "Suggests either a very powerful curse, a pact-based affliction, or something tied to undeath/necrotic energy."]]}, {"t": 334, "kind": "magic", "title": "Ember orange burns pale green", "line": "Lay on Hands produces pale green flame instead of usual ember orange — no effect on the cold hand; an anomaly flagged by the DM as significant.", "facets": [["New lore", "Lay on Hands normally manifests as ember orange warmth. The pale green flame is an anomaly."], ["House ruling", "DM flagged the colour change as a specific and meaningful ruling."]]}, {"t": 346, "kind": "scene", "title": "Escorted to the watch post", "line": "Nyx escorts Ponsey to his watch post; both sit together quietly.", "facets": [["Environment", "Watch Post: Nyx escorts Ponsey to a designated watch post where they sit together."], ["Decision", "Proceed with the scheduled watch without immediately waking Rune."]]}, {"t": 366, "kind": "social", "title": "Quiet caretaking in the dark", "line": "Nyx physically supports Ponsey to his watch post, sitting with him — a moment of quiet caretaking.", "facets": [["Character", "A rare unguarded beat between the two."]]}, {"t": 383, "kind": "social", "title": "\"I've never seen you that messed up\"", "line": "Nyx: \"I've never seen you that messed up, I must say.\" — Genuine concern expressed; Ponsey admits he hasn't been \"that drunk/high in a long time.\"", "facets": [["Character", "Suggests this state was unusual and possibly involuntary or deeply personal."]]}, {"t": 409, "kind": "social", "title": "Guarded and unreadable", "line": "Ponsey and Nyx share a quiet moment at the watch post; Ponsey is emotionally guarded and unreadable.", "facets": [["Major NPC", "Ponsey / Talon — emotionally guarded, highly adapted at hiding feelings; appears emotionless."]]}, {"t": 433, "kind": "social", "title": "Mourning Scar", "line": "Conversation about Scar: party misses him; Ponsey admits he wouldn't share Scar at first but acknowledges his impact — \"had an impact I never had.\" Nyx: \"I think you did have an impact.\"", "facets": [["Major NPC", "Scar — gone (deceased or departed); described as having had a meaningful impact on the party."], ["World state", "Scar is confirmed gone from the party — a loss that has emotionally affected both Nyx and Ponsey."]]}, {"t": 456, "kind": "lore", "title": "The question about Algana", "line": "Nyx asks Ponsey about the Bronze Dragon Algana encountered near \"Umbers Hill.\" The conversation was interrupted.", "facets": [["New lore", "Bronze Dragon named Algana was encountered previously near a location the player mistakenly called \"Umbers Hill.\""], ["Hook", "Conversation was cut off; details of this encounter may be significant."]]}, {"t": 555, "kind": "scene", "title": "Dice games to pass the time", "line": "Table banter; dice games proposed to pass time. Session ends in casual downtime. No major combat this session.", "facets": [["Decision", "Interest in creating a recurring team dice game (\"dice fights\") as a downtime tradition."], ["Combat", "No combat occurred this session."]]}], "threads": [{"u": "hi", "q": "Ponsey's Cold Hand: unresponsive to Lay on Hands (5 points), pale green flame anomaly, detected as \"off and unholy\" by Divine Sense. No active curse found — but something is clearly wrong.", "t": 111}, {"u": "hi", "q": "Rune Parallel: why does Ponsey's hand feel exactly like Rune's? Are they connected by the same curse, entity, or event?", "t": 94}, {"u": "md", "q": "Algana Conversation: Nyx's question about the Bronze Dragon was not completed. What does Ponsey know or feel about that encounter?", "t": 456}, {"u": "md", "q": "Scar's Fate: Scar is gone. The circumstances of his departure/death are not detailed in this session.", "t": 433}, {"u": "lo", "q": "Pale Green Lay on Hands: the DM flagged this colour change as specific and meaningful. Its significance is unexplained.", "t": 334}], "next": ["Investigate Ponsey's cold hand — find a healer or lore source that can diagnose necrotic/unholy afflictions beyond Lay on Hands.", "Confront or consult Rune about the cold hand parallel — is Rune afflicted the same way? Is Rune the source?", "Resume the conversation about Bronze Dragon Algana — what does Ponsey know and why does it matter now?", "Leverage Nyx's ex-Druid knowledge to research necrotic poison vs. unholy curse distinctions.", "Address Scar's absence — determine if his departure has any unresolved narrative or mechanical consequences.", "Identify what the pale green Lay on Hands flame signifies — consult DM lore or in-world sources."], "entities": [{"name": "Nyx", "kind": "pc", "note": "Paladin with an ex-Druid background; uses Divine Sense and Lay on Hands on Ponsey and keeps watch with him.", "t": 111, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Ponsey / Talon", "kind": "pc", "note": "Afflicted; one hand is unnaturally cold and unresponsive to divine healing. Emotionally guarded, highly adapted at hiding feelings. Cold hand mirrors Rune's condition — UNSOLVED connection.", "t": 409}, {"name": "Rune", "kind": "pc", "note": "Asleep during this scene; not directly involved. Previously the only person whose hand felt this cold to Nyx.", "t": 94}, {"name": "Scar", "kind": "pc", "note": "Gone (deceased or departed). Described warmly; had an impact on the party that Ponsey admits he himself lacked.", "t": 433}, {"name": "Algana", "kind": "creature", "note": "Bronze Dragon previously encountered near \"Umbers Hill.\" Nyx is beginning to ask Ponsey about this encounter.", "t": 456}, {"name": "Umbers Hill", "kind": "place", "note": "Location of a prior encounter with Bronze Dragon Algana. Name may be incorrect — player self-corrected.", "t": 456}, {"name": "Ruby Willows", "kind": "npc", "note": "Named only in the residual status-summary block, as \"reference to Rune/Ruby Willows\" for the previously experienced extreme cold. No further detail given.", "t": null}, {"name": "Antidote", "kind": "item", "note": "Already taken by Ponsey before this scene; source and type unspecified.", "t": 298}, {"name": "Driftwood Kin", "kind": "faction", "note": "Appears only as an empty section heading — the note states no relevant Driftwood Kin information was found in this session.", "t": null}], "gaps": ["The regenerated note still contains a residual generic \"Project Sync / Status Update Summary\" block (the entire text of the previous Auto-template version) embedded between the digest and FULL DETAILED NOTES; it is preserved verbatim in the raw file but carries no timecodes of its own.", "The digest heading reads \"QUICK DIGEST SUMMARY\" rather than the expected \"LAYER 1 — QUICK DIGEST SUMMARY\"; the template chip does read \"D&D Session Noters: V3\" and the full V3 section structure and timecodes are present.", "Proper-noun spelling varies across the note: \"Ponsey\" (V3 sections) vs \"Ponzi\" (residual status block), and the same character is also called \"Talon\". Retained as spelled in each place.", "\"Umbers Hill\" is flagged in the source itself as an approximate/possibly incorrect place name that the player self-corrected.", "Date and location are not specified in the transcript, and the DM is never named.", "Within the QUICK DIGEST list only, two adjacent stamps are printed out of order (00:05:34 appears before 00:05:20); the MAJOR EVENTS (Chronological) section is internally monotonic and was used for beat ordering."], "timecodesReliable": true, "iso": "2026-04-13", "pretty": "13 Apr 2026", "audio": false, "legendary": false, "n": 9}, {"slug": "rescue-mission-planning-recap", "title": "Dungeons and Dragons Campaign Session Recap: Rescue Mission Planning", "date": "04/09/2026 19:19", "runtime": "3h 27min 8s", "nottaId": "c9158b3c-41ed-42f5-bcf6-ac5e7c69aca9", "url": "https://app.notta.ai/7366972874555052032/dashboard/c9158b3c-41ed-42f5-bcf6-ac5e7c69aca9", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 12428, "subtitle": "Three barrels, one arrow, a declaration of war", "logline": "The Driftwood Kin burn an orc stronghold to rescue Ponzi, kill Dawson's assassin Axes, and post a taunt to Dawson using his own signet ring.", "recap": "\"Previously on Driftwood Kin…\"\nThe silver-scaled dragonborn moved through the tavern like smoke through a keyhole — slipping Thieves' Cant between the words, proving his craft with a vial that set Ponzi's tongue on fire, and then, with a casual hand on the shoulder and a pin-prick beneath the armor, sending him into darkness. Ponzi woke in a stone cellar, bound by a rope that breathed like a snake, to find a man half-devoured on the floor and Axes standing over him with arms crossed and a message from Dawson: the debt had metastasized. Four debtors now. Nothing on this island could satisfy what was owed.\nMiles away, Nyx stood surrounded by orcs, identity blown, plan accelerated. He let out the fire — three barrels, three fireballs, three shatters — and in the inferno, a girl appeared. Small. Pale. Blue eyes. A bronze medallion of Aces the Shepherd dangling from her neck. Celis, shielding him from the fire she was made of. When the smoke cleared, twenty orcs lay dead in burning grass, and Nyx knelt in the center of it, not quite ready to stand.\nPonzi cut through his magical bonds with a sharpened coin — a coin whose core, he noticed, was not what it appeared to be. He triggered a glyph, survived paralysis, filled the cellar with black smoke, and punched through a door with his bare fists. And then Axes drove a dagger through his palm and pinned him to the wood.\nThe Driftwood Kin blew the gate open with a wagon full of barrels. They found Axes staggering, purple veins climbing his arm from Ponzi's earlier poison. They fought through fire and shrapnel and a storm of stained-glass light. Axes threw three daggers and dropped Nyx before he could blink. Talon's music pulled Nyx back from the edge. Ponzi ripped his hand free from the door, broke through the wood with a spear, and looked Axes in the eye: \"How many deaths now?\"**\nAxes ran. Runewillo thunderstepped. Talon's guiding bolt painted a target on Axes's chest. And Ponzi's arrow found it — drawn like a magnet to the light — through the back of the head.\nThey looted the body. Found the ring. Identified it. Sealed a letter with it — ink vanishing, words teleporting to Dawson's desk. A taunting letter. A declaration.\nThe stronghold burned behind them as they rode back toward the llama.\nDawson has the letter now.", "dm": null, "party": ["Ponzi (Rogue/Poisoner)", "Nyx (Changeling — fire/cloak abilities)", "Runewillo (Wizard — Bladesinger)", "Talon (Cleric/Bard)"], "opens": "Recap of previous sessions — Nyx's fight, tattoo at Air Toss Temple (Alama/blossom tattoo), chess society introduction, Dawson's letter found, horses stolen from stable.", "closes": "Orc stronghold destroyed, Axes killed, letter sent to Dawson, party riding back toward Onbaton/llama.", "cards": {"changed": {"headline": "The Driftwood Kin have openly declared war on Dawson", "detail": "The party moved from covert resistance to open defiance: they destroyed his orc stronghold regiment, killed his top assassin Axes, and sealed a taunting letter with Dawson's own signet ring that teleported straight to his desk. Phase 1 → Phase 2 flag: the covert phase may be ending.", "t": 12282}, "learned": {"headline": "Dawson's signet ring both tracks and transmits", "detail": "Identify revealed the ring has two functions — divination-based location tracking for Dawson, and, when used as a wax seal, the ink of the sealed letter disappears and the letter teleports to Dawson's desk. Implies a sophisticated intelligence/communication network.", "t": 11978}, "who": {"headline": "Ponzi", "detail": "The session turned on Ponzi: lured and drugged by Axes, held in the cellar through waves of hallucination, he cut his own bonds with a sharpened coin, punched through a door, took a dagger through the palm, and finally landed the arrow that killed Axes.", "t": 10899}, "cost": {"headline": "Ponzi's hand is permanently scarred", "detail": "Black and purple discoloration and reduced fingertip sensitivity; full articulation was restored by Talon's Cure Wounds, but the scarring is permanent. For a rogue/poisoner reliant on fine motor skills this may carry long-term mechanical consequences. Nyx was also dropped to 0 HP, and significant spell resources were burned.", "t": 11251}, "hanging": {"headline": "How does Dawson answer the letter?", "detail": "Dawson has the taunting letter, knows his ring sits at the burned stronghold, and has lost his top operative. Will he pivot to direct engagement or increase proxy pressure elsewhere? Escalation is certain and imminent.", "t": 12282}}, "beats": [{"t": 0, "kind": "scene", "title": "Recap of previous sessions", "line": "The session opens with a recap: Nyx's fight won convincingly, a driftwood tattoo chosen and an Alama (blossom) tattoo received at the Air Toss Temple, and the party tracking Ponzi after he was carried out by a silver-scale dragonborn.", "facets": [["Character", "Party (Driftwood Kin): Ponzi (Rogue/Poisoner), Nyx (Changeling), Runewillo (Wizard — Bladesinger), Talon (Cleric/Bard)."], ["Decision", "Horses stolen from a stable (half-paid, half-stolen); guards helped with direction but don't take bribes."]]}, {"t": 49, "kind": "lore", "title": "The Chess Society and Dawson's letter", "line": "Recap surfaces two standing threads: a secret chess society with levels and hierarchy met at the Minotaur's Mug, which gave the party a night-piece to deliver in the Onbaton area, and Dawson's letter found at a table.", "facets": [["New lore", "The Chess Society — an \"opening move\" is significant, possibly a code or ritual. UNSOLVED / HOOK."], ["New lore", "Dawson's letter: \"What grows in the vaults is deaths and silence.\""]]}, {"t": 263, "kind": "scene", "title": "Ponzi lured and drugged at the tavern", "line": "Eighteen hours before the main action, Axes approached Ponzi at a tavern using Thieves' Cant disguised as stuttering, proved his craft with a poison vial, then delivered a pin-prick under the armor.", "facets": [["Major NPC", "Axes (Silver-Scale Dragonborn Assassin/Poisoner) — Dawson's crew, specialty incapacitating sleep poisons."], ["Character", "Ponzi's coin rang out in warning just too late; Axes gently petted his head as he lost consciousness."]]}, {"t": 469, "kind": "dread", "title": "Ponzi wakes in the cellar", "line": "A stone cellar beneath the orc stronghold, colder and damper. Axes stands with arms crossed; Ponzi's pack and the Ringbox sit on the table, and the gory remains of a man partially devoured by the Ringbox lie on the floor, shadow-smoking.", "facets": [["Environment", "One oil lantern in the corner; stairs leading up to a door; Glyph of Warding carved under the Ringbox."], ["Item", "Ringbox (Ponzi's) — black rainbox that devoured a man in the cellar."]]}, {"t": 603, "kind": "reveal", "title": "The debt has metastasized", "line": "Axes delivers Dawson's message: the debt has \"metastasized dramatically.\" 300 gold is now insufficient and nothing on the island can satisfy it. Four debtors instead of one. \"Now you must learn what grows within the vault. Debts and silence.\"", "facets": [["New lore", "Dawson's vault motto — implies the vault is a place of imprisonment, debt-slavery, or death."], ["Hook", "Where is the vault? Who else is imprisoned there?"]]}, {"t": 812, "kind": "social", "title": "Ponzi and his wife", "line": "The most emotionally resonant thread of the session: Ponzi's hallucinations of his wife were simultaneously the most comforting and most torturous element of the poison. The DM noted that unconsciousness is the only time Ponzi can \"talk\" to his wife.", "facets": [["Character", "He tried to talk to her, took her hand, and was guided by her through the dungeon."], ["Foreshadowing", "Suggests deep unresolved grief and possibly a spiritual/magical connection."]]}, {"t": 900, "kind": "dread", "title": "Bound by the Constricting Coil", "line": "Ponzi is bound with a magical constricting snake-skin rope that tightens when struggled against, while hallucination waves bring his wife, mind-flayer tentacles, childhood trauma and the death of Scar.", "facets": [["Item", "Constricting Coil — braided from snake skin, moves like a living snake."], ["Check", "Coin warning brings tunnel-vision focus — hallucinations pushed to the periphery."]]}, {"t": 1292, "kind": "item", "title": "A sharpened coin, and a core that is not what it seems", "line": "Ponzi cuts the Constricting Coil with the filed edge of his coin — the rope constricts against the sharp edge and snaps, bursting outward. Underneath the exterior the core shows a light green sheen, apparently mithral.", "facets": [["Item", "Ponzi's Sharpened Coin — silver/copper, a rose on one side, one edge filed sharp years ago in a desperate moment."], ["New lore", "DM explicitly flagged the coin core to discuss next session."]]}, {"t": 1468, "kind": "magic", "title": "Glyph of Warding and the alarm", "line": "Moving the Ringbox triggers a Glyph of Warding (Hold Person) and an alarm spell — a loud ringing bell alerting the guards above. Ponzi fails the first Wisdom save and breaks free on the second.", "facets": [["Check", "Wisdom save at disadvantage (poisoned + baned): rolled 11, failed. Second save six seconds later: rolled 16, succeeded."], ["Threat", "Process gap flagged: need a standardized magical sweep before handling sensitive items."]]}, {"t": 1674, "kind": "scene", "title": "Smoke, ball bearings and a sealed door", "line": "Ponzi fills the room with a Bottle of Smoke, scatters ball bearings at the bottom of the stairs, and fires an arrow blindly up at the guards. It misses; the guards seal the door with a table and leave him locked in.", "facets": [["Item", "Bottle of Smoke — fills a 30×30 ft area with thick black smoke."], ["Check", "Arrow attack roll: 8, missed, sank into wood halfway up the stairs."]]}, {"t": 2265, "kind": "combat", "title": "Nyx detonates three barrels", "line": "Surrounded by orcs with his identity discovered, Nyx triggers three explosive barrels in changeling form — 3× Fireball plus 3× Shatter — killing roughly twenty orcs.", "facets": [["Combat", "122 fire damage rolled (38, 34, 50) plus ~49 piercing from shatters."], ["Combat", "Nyx's final damage taken: 48 HP, surviving on +10 temp HP (Hearth Fire Manifest), piercing immunity, Aura of Solace and a successful Dex save."]]}, {"t": 2397, "kind": "reveal", "title": "Celis in the fire", "line": "Nyx's cloak transforms into the form of Celis, his deceased changeling ward, shielding him. Her bronze medallion of Aces the Shepherd — with an amber-cloaked woman superimposed — dangles in his face. Nyx drops to his knees in the aftermath.", "facets": [["Major NPC", "Celis — small changeling girl, pale skin, bright blue eyes, short bob hair, always smiling; deceased."], ["Foreshadowing", "Second time this symbol has manifested protectively around Nyx; strongly implies a divine or spiritual connection."]]}, {"t": 3730, "kind": "scene", "title": "Runewillo and Talon reach Nyx", "line": "Runewillo sprints in first at bladesinging speed, taking 7 fire damage through the flames; Talon arrives about 45 seconds behind and casts Aura of Vitality, rolling 77 total healing distributed between the party.", "facets": [["Check", "Aura of Vitality (Level 3): 10 turns, 2d6 healing per turn."], ["Character", "Nyx in Aura of Solace — fire resistance shared with nearby allies."]]}, {"t": 4578, "kind": "plan", "title": "Luring the orcs to the dead-end", "line": "The party lures remaining stronghold forces toward a second trap: three barrels in triangle formation in a dead-end valley, with Runewillo and Nyx as decoys and Talon holding the failsafe barrel from horseback.", "facets": [["Check", "Deception checks to appear wounded/limping: Nyx 18, Runewillo 13, Talon 12. Dragged an orc corpse for a blood trail."], ["Decision", "Runewillo triggers two barrels via Scorching Ray then Dimension Doors out with Nyx."]]}, {"t": 5319, "kind": "dread", "title": "A dagger through the palm", "line": "The explosion snaps Ponzi out of hallucination paralysis. He fails the lock with a natural 1, bashes through the door with his fists — and Axes, waiting outside, drives a dagger through his palm and pins it to the door, then heals him 16 HP just to keep him alive for more torture.", "facets": [["Combat", "Three attacks, all hit, lowest 22: ~21 + 22 plus poison damage. Ponzi went unconscious."], ["Character", "Ponzi's wife hallucination reached for his hand — he took it and gained clarity."]]}, {"t": 6107, "kind": "combat", "title": "The second trap kills two chiefs", "line": "Orcs hurl javelins before entering, then the barrels detonate. The boss orc riding a warg survives the first blast but dies to a rock shard; a new orc chief is crowned instantly and is killed by Talon's third barrel.", "facets": [["Combat", "Javelin barrage: Nyx took 32 piercing, Talon took 25 piercing. 2× Fireball ~141 fire plus shatters; third barrel ~23 fire."], ["Combat", "Last fanatic failed its Dex save — died standing, then collapsed. Entire remaining orc force eliminated."]]}, {"t": 7098, "kind": "combat", "title": "The gate goes down", "line": "The party rides back to the shut gates, loads a wagon with barrels from the portable hole, and Talon ignites it with Firebolt — blasting the gate open, scorching the orc on the wall and blowing out part of the building where Ponzi was held.", "facets": [["Environment", "Orc Stronghold: rough human log walls (flammable), stone basement, sentried walls."], ["Combat", "Party streamed through the fiery entry and found Axes staggering, purple veins climbing his forearm from Ponzi's poison."]]}, {"t": 7335, "kind": "boss", "title": "Axes drops Nyx in one round", "line": "Final combat inside the burning stronghold. Axes wins initiative and throws three poisoned daggers at Nyx — hit, hit, natural 20 crit — dropping him to 0 HP at 29 below. Talon's Aura of Vitality revives him; Runewillo casts Spellfire Storm.", "facets": [["Combat", "Initiative: Axes 25, Runewillo 23, Talon (nat 20), Nyx (nat 11), Ponzi after breaking through the door."], ["House ruling", "Axes was poisoned — attacks should have been at disadvantage; the DM compensated with extra healing."]]}, {"t": 8731, "kind": "social", "title": "\"How many deaths now?\"", "line": "Ponzi rips his hand free from the door, charges through with a spear and uses Frightful Presence — Axes fails his Charisma save and is frightened — then looks him in the eye and asks the question.", "facets": [["Character", "Line recorded in CHARACTER MOMENTS as Nyx's taunt; the CINEMATIC RECAP attributes the same words to Ponzi."], ["Combat", "Ripped hand free for 8 damage; spear attack roll 11+7=18, hit."]]}, {"t": 8765, "kind": "social", "title": "Do they let him run?", "line": "Genuine table tension over whether to let Axes escape: Nyx argued for letting him go as a message to Dawson; others argued he was too dangerous. The chase continued.", "facets": [["Decision", "Party chose pursuit over sending a live messenger."], ["Character", "Runewillo's taunt as Axes fled: \"Don't we want to stay and see how much debt we can rack up?\""]]}, {"t": 10899, "kind": "boss", "title": "The arrow drawn to the light", "line": "Runewillo Thunder Steps with Nyx to cut Axes off, Talon's Guiding Bolt leaves a glowing mark on his chest, and Ponzi's sneak-attack arrow is drawn magnetically to that light — through the back of Axes's head. Axes is dead.", "facets": [["Combat", "Ponzi: 21 to hit with advantage, sneak attack plus trip attempt, 30 damage total."], ["Major NPC", "Axes — STATUS: DEAD. Dawson's top assassin and poisoner removed from his network."]]}, {"t": 10927, "kind": "item", "title": "Looting the body", "line": "Ponzi finds the antidote strapped to Axes's wrist and takes it — hallucinations fade, poison progression stops. Talon's Cure Wounds heals the ruined hand 11 HP, fusing it but leaving permanent scarring. The body yields the bandolier, a sleep poison vial, 400 gold and Dawson's signet ring.", "facets": [["Item", "Bandolier of poison daggers given to Talon; sheaths lined with tacky poison, bandolier itself magical. Properties TBD."], ["Item", "400 gold across four hidden coin purses; one vial of Assassin's Sleep Poison retained by Ponzi."], ["Character", "One orc was seen fleeing ~90 feet away — the party chose not to pursue."]]}, {"t": 12282, "kind": "reveal", "title": "A letter to Dawson's desk", "line": "The party composes a taunting message — \"come after us like a real man\" — with ominous musical notes added by Talon, seals it with the signet ring, and the ink vanishes as the letter teleports to Dawson's desk. A wax mold of the ring was made first for future forgery.", "facets": [["Decision", "Ring left behind rather than carried — too risky as a tracker."], ["Item", "Wax Mold of Dawson's Signet Ring — in the party's possession for future forgery."]]}, {"t": 12332, "kind": "travel", "title": "The stronghold burns behind them", "line": "The orc stronghold is left burning to the ground as the party rides back toward the llama in the Onbaton area, with the wagon and hidden horses still to recover.", "facets": [["World state", "A significant military/criminal asset of Dawson's has been eliminated."], ["Decision", "MUST DO NEXT SESSION: return to Onbaton, retrieve wagon/horses, check on the llama."]]}], "threads": [{"u": "hi", "q": "Dawson's Response: the party sent a taunting letter. Dawson knows they destroyed his stronghold and killed Axes. Escalation is certain and imminent.", "t": 12282}, {"u": "hi", "q": "Ponzi's Hand: permanent scarring, reduced sensitivity. Long-term mechanical and narrative consequences unknown.", "t": 11251}, {"u": "md", "q": "Ponzi's Coin Core (Mithral?): DM flagged explicitly. Could be a major lore/item reveal.", "t": 1340}, {"u": "md", "q": "Night-Piece Delivery (Chess Society): undelivered. Contact in Onbaton area waiting. Unknown stakes.", "t": 49}, {"u": "md", "q": "Celis / Aces the Shepherd / Amber-Cloaked Woman: recurring spiritual motif around Nyx. Not yet explained.", "t": 2397}, {"u": "md", "q": "Dawson's Vault Location: referenced twice. Prisoners implied. Party has not located it.", "t": 603}, {"u": "lo", "q": "Surviving Orc (Running Away): one orc was seen fleeing (~90 feet away) at end of combat. Could report to Dawson or other factions.", "t": 10927}, {"u": "lo", "q": "Bandolier Properties: DM said details on the magical bandolier will be provided next session.", "t": 11438}], "next": ["Return to Onbaton: wagon, horses, llama check", "Deliver night-piece to Chess Society contact", "Ask DM about Ponzi's coin core (mithral?) — flagged for next session", "Receive bandolier stats from DM", "Assess Ponzi's hand for further healing options", "Prepare for Dawson's escalation — he's been directly challenged", "Locate Dawson's vault", "Investigate Celis / Aces the Shepherd / amber-cloaked woman symbol"], "entities": [{"name": "Ponzi", "kind": "pc", "note": "Rogue/Poisoner. Captured, poisoned and tortured by Axes; escaped with a sharpened coin and landed the killing arrow. Hand permanently scarred.", "t": 263, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Nyx", "kind": "pc", "note": "Changeling with fire/cloak abilities. Detonated the first trap killing ~20 orcs; was dropped to 0 HP by Axes. Received the Celis vision.", "t": 2265, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Rune Willow", "kind": "pc", "note": "Wizard (Bladesinger). Cast Spellfire Storm, used Dimension Door twice and Thunder Step twice to cut off Axes.", "t": 3730, "alias": "Runewillo"}, {"name": "Talon", "kind": "pc", "note": "Cleric/Bard. Cast Aura of Vitality, Guiding Bolt and Cure Wounds; ignited the gate wagon with Firebolt; received the poison dagger bandolier.", "t": 3730, "reveal": "Talon's real name is Tanner."}, {"name": "Axes", "kind": "npc", "note": "Silver-scale dragonborn assassin/poisoner in Dawson's crew. Bandolier of poison-coated daggers. STATUS: DEAD — killed by Ponzi's arrow guided by Talon's Guiding Bolt.", "t": 10899}, {"name": "Dawson", "kind": "npc", "note": "Powerful enemy operating through lackeys. Has a vault and a signet ring for magical communication. Alive, off-screen, and has now received the party's taunting letter.", "t": 12282}, {"name": "Celis", "kind": "npc", "note": "Deceased changeling girl connected to Nyx as ward/adopted child. Appeared as a protective manifestation during the explosion wearing a bronze medallion of Aces the Shepherd.", "t": 2397}, {"name": "Aces the Shepherd", "kind": "faction", "note": "Deity or divine figure. Symbol: a shepherd with the impression of an amber-cloaked woman superimposed. Appears on Celis's bronze medallion; Talon prays to Aces during the session.", "t": 3753}, {"name": "Chess Player", "kind": "npc", "note": "Individual at the Minotaur's Mug, part of the secret chess society. Gave the party a night-piece to deliver in the Onbaton area. UNSOLVED.", "t": 49}, {"name": "Driftwood Kin", "kind": "faction", "note": "The party. Destroyed an orc stronghold regiment, killed Dawson's top assassin, and sent a direct challenge letter. Phase 1 to Phase 2 flag raised.", "t": 0}, {"name": "Dawson's Organization", "kind": "faction", "note": "Dawson at top; uses assassins, orc mercenaries and debt as leverage. Lost Axes and the orc stronghold regiment this session. Threat level HIGH.", "t": 12282}, {"name": "Secret Chess Society", "kind": "faction", "note": "Levels/hierarchy of chess players; an \"opening move\" is significant. Party holds an undelivered night-piece. Could be ally or rival.", "t": 49}, {"name": "Orc Stronghold Forces", "kind": "faction", "note": "ELIMINATED. ~20+ orcs killed in the first trap, remaining forces in the second trap and gate explosion. Boss orc killed; new chief crowned and immediately killed.", "t": 6413}, {"name": "Orc Stronghold", "kind": "place", "note": "In the hills outside Onbaton. Rough human log walls (flammable), stone basement/repository, cellar/vault beneath. Gate destroyed and fort set ablaze.", "t": 7098}, {"name": "Ann Baton", "kind": "place", "note": "The nearby town/city where the party is based. The llama is there; horses hidden nearby.", "t": 12332, "alias": "Onbaton"}, {"name": "Ponzi's Sharpened Coin", "kind": "item", "note": "Silver/copper coin with a rose on one side, one edge filed sharp. Core appears to be mithral (light green sheen). Cut through the Constricting Coil.", "t": 1292}, {"name": "Constricting Coil", "kind": "item", "note": "Magical rope braided from snake skin that tightens when struggled against. Destroyed — cut by Ponzi's coin.", "t": 1292}, {"name": "Ringbox", "kind": "item", "note": "Ponzi's black rainbox. Devoured a man in the cellar and shadow-smokes off corpses. Recovered from the cellar table; sat under a Glyph of Warding.", "t": 1416}, {"name": "Bottle of Smoke", "kind": "item", "note": "Fills a 30x30 ft area with thick black smoke when opened. Used this session.", "t": 1674}, {"name": "Bandolier of Poison Daggers", "kind": "item", "note": "Six daggers, sheaths lined with tacky poison; the bandolier itself is magical (daggers are swappable). Transferred from Axes to Talon. Properties TBD next session.", "t": 11438}, {"name": "Assassin's Sleep Poison Vial", "kind": "item", "note": "Black and purple. Axes's specialty — incapacitating sleep poison causing hours of hallucinations. One vial recovered, retained by Ponzi.", "t": 11397}, {"name": "Dawson's Signet Ring", "kind": "item", "note": "Worn on Axes's pinky. Divination tracking plus wax-seal letter teleportation to Dawson's desk. Used then abandoned at the burning stronghold.", "t": 11978}, {"name": "Wax Mold of Dawson's Signet Ring", "kind": "item", "note": "Cast for future forgery of Dawson's seal without carrying the tracked ring. In the party's possession.", "t": 12299}], "gaps": ["get_page_text hard-truncated the page at 50,000 of 55,828 characters, but the cut fell inside the excluded right-hand Notta Brain panel (a slides-generation chat); the AI Note itself is complete through the CINEMATIC RECAP and the full 10-item Actionable To-Do List, so no note content was lost.", "The note contains a residual generic \"Project Sync / Status Update Summary\" block between LAYER 1 and LAYER 2, carried over from the previous Auto-template version; it is preserved verbatim in the raw file but carries no timecodes.", "Ponzi's coin core is described as mithral in the LAYER 1 digest and the V3 sections (\"looks like enemy team (mithral?)\") but as adamantine in the residual status block. The source contradicts itself and the DM flagged the material for next session.", "Dawson's vault motto is quoted two ways: \"What grows in the vaults is debts and silence\" (digest, LORE) and \"What grows in the vaults is deaths and silence\" (recap of previous sessions). Both spellings retained as written.", "Proper-noun spelling varies across the note: Runewillo / RuneWillow / Runewillow, and Onbaton / Ann Baton. Copied exactly as spelled in each place.", "\"How many deaths now?\" is filed under CHARACTER MOMENTS as \"Nyx's Taunt to Axes\" but the CINEMATIC RECAP attributes the same line to Ponzi. The source does not resolve which character said it."], "timecodesReliable": true, "iso": "2026-04-09", "pretty": "9 Apr 2026", "audio": false, "legendary": false, "n": 8}, {"slug": "fort-assault-planning", "title": "Fort Assault Planning: Explosives Placement and Reconnaissance Strategy", "date": "04/02/2026 19:11", "runtime": "1h 29min 38s", "nottaId": "29e9e787-0415-48f4-8fbf-30b46e567ec3", "url": "https://app.notta.ai/7366972874555052032/dashboard/29e9e787-0415-48f4-8fbf-30b46e567ec3", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 5378, "subtitle": "He winked, said boom, and lit the fuse", "logline": "The party buries napalm barrels, scouts the orc stronghold by bat, and Nix talks the chief into marching his war party straight into the kill zone.", "recap": "\"Previously on…\"\nThe sun was sinking behind the western hills when the party made their move. Miles of careful planning — barrels of napalm-like sap buried in dead-end valleys, scouting routes mapped with uncanny precision, a bat named Periwinkle slipping through glass-paned windows to count the enemy — all of it had led to this moment.\nNix shed his skin and became the enemy. An orc. Scraggly. Nasty. Convincing enough to walk through the gate and stand before the chief himself — a mountain of muscle draped in fur, his face a constellation of iron piercings. With a natural 20 and a silver tongue, Nix sent eighteen orcs marching into the dark. Into the hills. Into the trap.\nBut the plan frayed at the edges. A sentry's suspicion. A survival roll that sent the war party stumbling past the wrong side of the barrels. And then — a natural 1. Nix's leg caught fire. The orc shaman, black-eyed and warg-mounted, looked down and saw through every lie.\nTwenty orcs surrounded him.\nNix straightened up. Dropped the disguise. Let his true face — his changeling face — stare back at the fanatic. Smirked. Winked.\n\"Boom.\"\nThree barrels. One Scorching Ray. A ball of smoke rising into the night sky a quarter mile away.\nThe trap has been sprung. The question is: who survived it?", "dm": null, "party": ["Nix (Changeling — infiltrator/face)", "Rune Willow (spellcaster — familiar/recon/firebolt)", "Talon (Rock Gnome — trap-setter/survival)"], "opens": "Approximately 1.5–2 miles from the orc stronghold, in hill country with valleys and hilltops; assault planning underway.", "closes": "First trap detonated; Nix surrounded by 18–20 orcs in the kill zone; Rune Willow and Talon approximately a quarter mile away, ready to act.", "cards": {"changed": {"headline": "The orc war party is in the kill zone and the trap is blown", "detail": "The stronghold's exterior war party — 18–20 orcs including warg riders and the shaman/fanatic — was drawn out and detonated on. The stronghold's defensive capacity is significantly reduced, with roughly half the original force remaining inside.", "t": 5346}, "learned": {"headline": "Ponzi is \"the Dragonborn's prize,\" not the orcs'", "detail": "The orc chief referenced \"the Dragonborn's prize\" when sending orcs out, suggesting Ponzi may be the silver Dragonborn's captive and the orcs merely hired muscle. The chief also spoke the name \"Driftwood\" — the Kin's reputation has reached this stronghold.", "t": 4378}, "who": {"headline": "Nix", "detail": "The whole operation turned on Nix: he impersonated an orc, walked up to the chief and, on a natural 20 Persuasion with Luck burned, convinced him to send 18–20 warriors out to hunt the Driftwood — depleting the stronghold's exterior force by himself.", "t": 4459}, "cost": {"headline": "Nix detonated the trap from inside it", "detail": "Surrounded in the centre of the barrel triangle after a natural 1 Deception, Nix dropped his disguise and fired Scorching Ray into all three barrels at point-blank. Luck points are depleted or nearly so, and the portable hole was abandoned in open ground near the wall.", "t": 5324}, "hanging": {"headline": "Who survived the blast?", "detail": "The session ended at the moment of explosion. The outcome for the orcs in the kill zone is unknown, and Nix's survival status is unknown — he was standing in the centre of the triangle.", "t": 5375}}, "beats": [{"t": 5, "kind": "plan", "title": "A multi-stage ambush to get Ponzi out", "line": "The party is executing a multi-stage ambush plan against an orc stronghold to rescue Ponzi, who is being held inside.", "facets": [["Character", "Party: Nix (Changeling infiltrator/face), Rune Willow (familiar/recon/firebolt), Talon (Rock Gnome trap-setter), and at least one additional member referenced."], ["Environment", "Start point roughly 1.5–2 miles out in hill country; approaching sunset."]]}, {"t": 35, "kind": "plan", "title": "Three barrels, three sites, one sequence", "line": "The party finalizes a three-stage explosive trap plan: two outer traps funnel enemies into a dead end, and the gate is the third detonation point. Flaming Arrow, Firebolt and Scorching Ray are discussed as ignition methods.", "facets": [["Decision", "Barrel allocation set to 3 at the dead end, 3 at the bottleneck, 4 reserved for the gate breach."], ["Item", "Explosive barrels: gelatinous, napalm-like flammable sap that throws flaming sap on detonation. 10 total."]]}, {"t": 150, "kind": "plan", "title": "Recon before burying anything", "line": "The party decides reconnaissance must come before barrel-burying. Rune Willow will use Find Familiar to scout via a bat from inside the wagon parked against the stronghold wall.", "facets": [["House ruling", "Find Familiar: 1,000 ft range, bonus action to see through the familiar's eyes; sight must be re-initiated each turn."]]}, {"t": 303, "kind": "travel", "title": "Through the valleys at sunset", "line": "The party moves through hill country using valleys for cover, avoiding detection, with the sun setting behind them to the west and providing concealment.", "facets": [["Environment", "Rolling hills and valleys; natural paths wind through low ground."], ["Decision", "Operations aligned to sunset to leverage backlighting and reduced visibility."]]}, {"t": 1179, "kind": "plan", "title": "The dead-end valley found", "line": "Survival checks locate a suitable dead-end valley formation — a serpentine path through hills toward the keep, roughly three-quarters of a mile out and outside the orc scouting range. Three barrels are dropped here.", "facets": [["Check", "Survival: natural 19 plus modifiers; Rock Gnome advantage on digging/burying."], ["Environment", "Hollow tree stump and rocks available for improvised shrapnel."]]}, {"t": 1537, "kind": "clue", "title": "The patrol routes mapped perfectly", "line": "Talon observes patrol patterns and Rune Willow rolls a natural 20 on Investigation for a total of 28, mapping the orc scouting routes perfectly — including the shift-change secondary routes.", "facets": [["Check", "Investigation natural 20, total 28. Revealed full scouting routes AND shift-change secondary routes."], ["New lore", "Orc scouting parties number 2–3 groups patrolling within roughly half a mile, rotating routes on shift changes."]]}, {"t": 1698, "kind": "scene", "title": "Unseen all the way to the gate", "line": "The party rolls stealth with advantage granted by their scouting knowledge — 23, 17 and 12 — and remains unseen on the advance.", "facets": [["Check", "All three stealth checks passed; two Bardic Inspiration dice spent."], ["House ruling", "DM ruled heavy armor stealth disadvantage does NOT apply at half-mile detection range, only when creeping through hallways."]]}, {"t": 1761, "kind": "plan", "title": "The switchback bottleneck", "line": "Survival checks locate a switchback valley — a natural bottleneck with limited sightlines and natural shrapnel materials to hand, inside the orc scouting range. Three more barrels are buried here.", "facets": [["Check", "Survival checks of 17 and 19."], ["Environment", "Two barrels on the outer sides of the bend, one on the inner bend."]]}, {"t": 2491, "kind": "scene", "title": "A rock gnome in his element", "line": "Talon buries the barrels with advantage on the survival check, granted by the DM specifically because digging into rock is \"so adjacent to your upbringing and your race as a rock gnome.\"", "facets": [["Check", "Rolled 7 and 11, total 16. Trap set but with three points of suspicion."], ["Character", "A moment of Rock Gnome pride at the table."]]}, {"t": 2634, "kind": "scene", "title": "Into the portable hole", "line": "Rune Willow hides in the portable hole in the wagon. Nix transforms into an orc and stealths to the wagon wall. Rune Willow casts Find Familiar and deploys Periwinkle the bat.", "facets": [["Check", "Stealth check (Nix at wall): natural 19 on the first attempt."], ["Item", "Periwinkle — a super dark blue, nearly black bat familiar."]]}, {"t": 2722, "kind": "social", "title": "Periwinkle's point of view", "line": "When Rune Willow connects to Periwinkle's eyes, she sees her own porcelain face up close — and notices the fine, shattered nature of the porcelain. A quiet, unsettling moment of self-perception.", "facets": [["Character", "A rare beat of self-regard for Rune Willow."]]}, {"t": 2903, "kind": "clue", "title": "What the bat saw", "line": "Periwinkle flies over the stronghold interior: about 18 orcs outside, fires, sword-sharpening, no prisoners visible. Landing on a window sill, the bat spots the silver Dragonborn walking up from a basement and speaking to the heavily-pierced orc chief.", "facets": [["Environment", "Double-wall construction, single gate, central building, stairs down to a basement, glass-paned windows."], ["Major NPC", "Orc Chief: large, heavy fur cloak, face and jawline riddled with piercings including large loops."]]}, {"t": 2993, "kind": "reveal", "title": "The silver Dragonborn is inside", "line": "The silver Dragonborn previously seen with Ponzi in a tavern is present inside the stronghold, speaking with the orc chief. Ponzi's exact location is unknown but presumed to be the basement the Dragonborn walked up from.", "facets": [["Hook", "Their relationship and purpose are unknown. HIGH PRIORITY UNSOLVED."], ["Unsolved", "No prisoners were observed outside; Ponzi presumed held within the interior."]]}, {"t": 3339, "kind": "social", "title": "A twig that would not burn", "line": "Nix lights a small twig for warmth for Rune Willow before closing the portable hole. The twig immediately goes out — no oxygen. Described as \"working emotionally harder\": a small, tender moment.", "facets": [["Character", "A quiet beat of care between two party members mid-infiltration."]]}, {"t": 3403, "kind": "scene", "title": "Extraction, and a sentry's eye", "line": "Nix retrieves Rune Willow from the portable hole, tucks it into his shoulder pads, and attempts to stealth away. A sentry raises suspicion but no alarm is sounded.", "facets": [["Check", "Stealth check (extraction): 12, twice. Above 10 but not great."], ["Check", "Perception 14 determined the sentry was on high alert but not fully alarmed."]]}, {"t": 3649, "kind": "social", "title": "The lone survivor ruse", "line": "As Nix nears the hills a sentry on the wall calls out. Nix drops the portable hole — opening it so Rune Willow can escape — turns back, and improvises: he is a lone survivor of a Driftwood attack, and he can lead the orcs to the enemy.", "facets": [["Decision", "Nyx pivoted to the \"lone survivor\" ruse; the war horn sounded earlier than planned."], ["Item", "The portable hole was left in the open ground between the wall and the hills."]]}, {"t": 3697, "kind": "plan", "title": "Three barrels in a triangle", "line": "Talon buries three barrels in a triangular formation at the dead end, packs in rock shrapnel and creates ignition wicks. The trap is set, but with three visible points of suspicion.", "facets": [["Check", "Survival roll: 16."], ["Environment", "One barrel at the end of the dead end, two on the outer sides of the bend."]]}, {"t": 4378, "kind": "reveal", "title": "\"The Dragonborn's prize\"", "line": "The orc chief references \"the Dragonborn's prize\" when sending orcs out — suggesting Ponzi is the Dragonborn's captive rather than the orcs'. He also names \"Driftwood\" directly.", "facets": [["Foreshadowing", "The Dragonborn appears to be operating with or through the orcs; their broader faction, goals and resources are entirely unknown."], ["World state", "MILESTONE FLAG: the Driftwood Kin's reputation has reached this stronghold."]]}, {"t": 4459, "kind": "social", "title": "Natural 20 on the chief", "line": "Nix reaches the wall, speaks to the orc commander, and with a natural 20 Persuasion — Luck burned — convinces the chief to send 18–20 orcs including warg riders out to hunt the Driftwood.", "facets": [["Check", "Persuasion: burned Luck, natural 20."], ["Character", "Nix had a whole speech prepared but was told to resist it; he delivered a compressed, effective version instead."]]}, {"t": 4614, "kind": "travel", "title": "Rune Willow outruns the column", "line": "Rune Willow uses Expeditious Retreat at speed 40+ to race back to Talon's position ahead of the orc column, and the two coordinate a staggered ignition sequence.", "facets": [["Check", "Stealth check (Rune Willow escape): advantage from Nix directing attention; \"dirty 20\" — melted into shadows."], ["Decision", "Staggered ignition sequence agreed: \"boom, boom, boom.\""]]}, {"t": 4853, "kind": "dread", "title": "The wrong side of the barrels", "line": "Nix leads the war party at a deliberately slowed, hobbling pace to buy time, passing through the switchback valley trap and trying to steer around the barrels — but rolls a Survival check of 3, picks the wrong path and nearly runs the orcs straight past them.", "facets": [["Check", "Survival: 3. Mirrored terrain caused the pathing error under pressure."], ["Threat", "High cognitive load while being prodded by orcs increased the risk."]]}, {"t": 5018, "kind": "dread", "title": "Natural 1, and the shaman sees through him", "line": "Nix attempts to light his own leg on fire as a distraction and rolls a natural 1 on Deception. The orc shaman/fanatic — black-painted eyes, heavy tusks, riding a warg — sees through it and begins surrounding Nix with roughly twenty orcs.", "facets": [["Major NPC", "Orc Shaman/Fanatic: black-painted eyes dripping to the jawline, wields a staff, can summon magic."], ["Combat", "Trigger event: ~20 orcs closed into the kill triangle; the fanatic prepared magic."]]}, {"t": 5324, "kind": "combat", "title": "\"Boom.\"", "line": "Nix drops his orc form, reveals his changeling appearance, looks the fanatic in the eyes, smirks, winks, says \"boom\" — and casts Scorching Ray, hitting all three barrels at once.", "facets": [["Check", "Scorching Ray cast at three barrel targets simultaneously. All three hit."], ["Character", "Peak character moment, called out as such by the note."]]}, {"t": 5346, "kind": "combat", "title": "A ball of smoke a quarter mile up", "line": "All three barrels detonate in a massive explosion, sending a smoke ball visible a quarter mile away from Rune Willow and Talon's position. All ~18–20 orcs, including the fanatic and warg riders, were in the kill zone at the point of detonation.", "facets": [["World state", "The stronghold's defensive capacity is significantly reduced; roughly half the original force remains inside."], ["Combat", "Session ended at the moment of explosion — the outcome for the orcs, and for Nix in the centre of the triangle, is unknown."]]}], "threads": [{"u": "hi", "q": "Silver Dragonborn's Identity and Motive: who are they, why do they have Ponzi, and what is their connection to the orc stronghold?", "t": 4378}, {"u": "hi", "q": "Ponzi's Condition: is Ponzi alive, injured, or magically restrained? Located in the basement.", "t": 2993}, {"u": "hi", "q": "Orc Shaman/Fanatic Survival: was the fanatic killed in the explosion? He was in the kill zone. His magical capabilities are unknown.", "t": 5053}, {"u": "hi", "q": "Gate Barrel Detonation: the gate barrel has not been triggered. The stronghold is not yet breached.", "t": 3403}, {"u": "md", "q": "Remaining Garrison: ~15–20 orcs remain inside with the chief and the Dragonborn.", "t": 4540}, {"u": "md", "q": "Rune Willow's Communication Gap: Rune Willow and Nix had zero chance to share recon information before the plan went live. Rune Willow knows the interior layout; Nix does not.", "t": 4355}, {"u": "md", "q": "Portable Hole Location: dropped in the open ground between the wall and the hills. Its current status and whether it was recovered is unclear.", "t": 3615}, {"u": "lo", "q": "Talon's Three Points of Suspicion: the dead-end trap had three visible points of suspicion. Whether orcs noticed before the explosion is unknown.", "t": 3799}], "next": ["Determine Nix's survival and condition post-explosion.", "Detonate the gate barrel — breach the stronghold.", "Rune Willow and Talon move to the gate immediately.", "Rescue Ponzi from the basement of the main building.", "Engage and neutralize the orc chief.", "Identify and confront the silver Dragonborn.", "Recover the portable hole from the open ground near the wall.", "Assess whether the orc shaman/fanatic survived."], "entities": [{"name": "Nyx", "kind": "pc", "note": "Changeling infiltrator/face. Impersonated an orc, persuaded the chief on a natural 20, led the war party into the trap and detonated it from the centre of the kill zone.", "t": 4459, "alias": "Nix", "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Rune Willow", "kind": "pc", "note": "Spellcaster handling familiar recon and firebolt ignition. Mapped the patrol routes on a natural 20 Investigation and scouted the interior through Periwinkle.", "t": 1537}, {"name": "Talon", "kind": "pc", "note": "Rock Gnome trap-setter. Buried three barrels at the dead end and three at the switchback with improvised rock and branch shrapnel; carries an exploding crossbow bolt.", "t": 3697, "reveal": "Talon's real name is Tanner."}, {"name": "Ponzi", "kind": "pc", "note": "Party member or ally held captive inside the stronghold, presumed in the basement. The entire mission is a rescue operation.", "t": 2993, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Silver Dragonborn (Unnamed)", "kind": "npc", "note": "Previously seen with Ponzi in a tavern. Inside the stronghold speaking with the orc chief, who calls Ponzi \"the Dragonborn's prize\" — suggesting the Dragonborn is the true captor. Motives unknown.", "t": 2993}, {"name": "Orc Chief/Leader (Unnamed)", "kind": "npc", "note": "Large orc in a heavy fur cloak, face and jawline riddled with piercings including large jaw loops. Commands the stronghold; sent 18–20 warriors out on Nix's persuasion.", "t": 3193}, {"name": "Orc Shaman/Fanatic (Unnamed)", "kind": "npc", "note": "Warg rider with black-painted eyes dripping to the jawline and heavy tusks. Wields a staff with magical capability. Saw through Nix's leg-fire distraction; was in the kill zone at detonation.", "t": 5053}, {"name": "Periwinkle", "kind": "creature", "note": "Rune Willow's bat familiar, super dark blue in colour (nearly black). Used for interior recon of the stronghold.", "t": 2650}, {"name": "The Orc Stronghold Garrison", "kind": "faction", "note": "Approximately 35–40 orcs total, led by the heavily-pierced chief, including warg riders and a shaman/fanatic. Currently split — 18–20 in the trap, the remainder holding the stronghold.", "t": 4540}, {"name": "The Silver Dragonborn's Faction (Unknown)", "kind": "faction", "note": "The Dragonborn appears to operate with or through the orcs, holding Ponzi as a \"prize.\" Broader faction, goals and resources entirely unknown.", "t": 4378}, {"name": "Driftwood Kin", "kind": "faction", "note": "The party, operating as a covert strike team using deception, familiar recon, explosive traps and changeling infiltration. Named aloud by the orc chief.", "t": 4378}, {"name": "Dead-End Valley", "kind": "place", "note": "Trap Site 1. Serpentine path through hills to a natural dead end, roughly three-quarters of a mile from the stronghold and outside the scouting range. Three barrels buried in a triangle.", "t": 1179}, {"name": "Switchback Valley", "kind": "place", "note": "Trap Site 2. A hard switchback turn forming a natural bottleneck with limited sightlines, inside the orc scouting range. Three barrels buried here.", "t": 1761}, {"name": "The Stronghold", "kind": "place", "note": "Double-wall construction with a central building near the back wall, a single gate, fire pits, a grindstone, glass-paned windows and stairs down to a basement.", "t": 2903}, {"name": "The Gate", "kind": "place", "note": "Made of sharpened, pulled tree trunks with slight overlap. The only entrance/exit. A barrel is positioned here for detonation.", "t": 4320}, {"name": "Explosive Barrels", "kind": "item", "note": "Ten total. Gelatinous, napalm-like flammable sap that detonates with fire and throws flaming sap. Distributed 3 at the dead end, 3 at the switchback, the rest reserved for the gate.", "t": 1249}, {"name": "Portable Hole", "kind": "item", "note": "Used by Rune Willow as a hiding space and for transporting barrels. Dropped and opened near the stronghold wall during Nix's extraction; not yet recovered.", "t": 3615}, {"name": "Exploding Bolt", "kind": "item", "note": "Talon's light crossbow bolt, able to detonate one barrel.", "t": 4752}, {"name": "Va", "kind": "place", "note": "Referenced as the region or campaign world holding multiple orc tribes; the note itself marks the name as uncertain (\"likely the campaign world\").", "t": 1967}], "gaps": ["The note contradicts itself about which trap was detonated: the LAYER 1 digest, MAJOR EVENTS and COMBAT BREAKDOWN all say Scorching Ray hit the three barrels in the DEAD-END trap, while the residual status block says the war party was led through the Bottleneck/switchback and that the barrels ignited there (Ambush 2). Beats follow the V3 sections; the discrepancy is unresolved in the source.", "The regenerated note still contains a residual generic \"Project Sync / Status Update Summary\" block between the digest and FULL DETAILED NOTES, carried over from the previous Auto-template version; preserved verbatim in the raw file but carrying no timecodes.", "The digest heading reads \"QUICK DIGEST SUMMARY\" rather than the expected \"LAYER 1 — QUICK DIGEST SUMMARY\", and the detailed section is headed \"FULL DETAILED NOTES\" without a \"LAYER 2\" prefix; the template chip does read \"D&D Session Noters: V3\" and the full V3 structure and timecodes are present.", "The infiltrator's name is spelled \"Nix\" throughout the V3 sections and \"Nyx\" throughout the residual status block. \"Rune Willow\" is written as two words here. Copied exactly as spelled in each place.", "The party roster notes \"at least one additional party member referenced\" but never names them, and the DM is never named.", "The region name \"Va\" is flagged by the source itself as uncertain."], "timecodesReliable": true, "iso": "2026-04-02", "pretty": "2 Apr 2026", "audio": false, "legendary": false, "n": 7}, {"slug": "sea-hag-battle-and-trials-completion", "title": "Dungeons and Dragons Campaign Session: Battle Against Sea Hag and Trials Completion", "date": "02/19/2026 19:19", "runtime": "3h 9min 11s", "nottaId": "cd0e2154-65d7-48b6-81c5-84f04f91c506", "url": "https://app.notta.ai/7366972874555052032/dashboard/cd0e2154-65d7-48b6-81c5-84f04f91c506", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 11351, "subtitle": "A city where everyone carries a blade", "logline": "The trials end, the party hits Level 7 and walks into Olama — where they learn the root in Ponzi's pocket is something the whole city fears.", "recap": "Previously on… The Driftwood Kids\nThe tunnels flooded. The hag fell. The Banshee screamed — not in rage, but in something like relief. Ponzi stood over the body of the sea hag and felt the weight of a ring with chains pressed into his palm.\nRune knelt over the White and spoke the words of Revivify — and the man breathed. The frog receded. Her test was complete.\nNyx stood tall as the last Pyreling merged with the glaive, and the weapon sang.\nThen Alvgand showed them what they could become. Talon saw music that moved the world. Nyx saw a knight who had been forgiven. Moonwillow saw herself — truly herself — with her hood off and light pouring from her head.\nAnd Ponzi saw darkness take him.\nIn the wide hall, a coin flipped. A figure at the end of a throne looked at him and said a name he had not heard in a long time.\nAsher.\n\"Are you seeking justice — or vengeance?\"\nPonzi didn't know.\n\"You'll have to choose sooner than you think. We won't meet again until you do.\"\nThe party arrived at Olama — the City of the Blind — where every citizen carries a blade and nobody trusts a pedestal. They leveled up. They found a smith who forges steel that sings. They played games, won gold, and made friends.\nAnd in a grove of guarded fruit trees, a halfling named Tudor looked at what Ponzi had been carrying in his pocket — and shuddered.\n\"Put that away. Keep it away. The Lord of Blood is gone — but the scars he made remain.\"\nNow, in the sandpit of the Manticore's Mug, the crowd is chanting. Ale is being brought to the sides. Frosalk is wrapping his knuckles. And Nyx is stepping into the pit.\nThe Vollenhand has begun.", "dm": null, "party": ["Rune Willow — Wizard / Bladesinger", "Talon — Bard", "Ponzi — Rogue", "Nyx — Changeling Paladin"], "opens": "Just outside the walls of Olama, post-challenge completion.", "closes": "Inside the Manticore's Mug tavern, moments before the Vollenhand brawl between Nyx and Frosalk begins.", "cards": {"changed": {"headline": "The trials are closed and the party walks into Olama at Level 7", "detail": "Talon, Nyx, Rune and Ponzi all completed their trials — Talon has a fife tied to the Dragon Song, Nyx's glaive is consecrated with the Pyrelings merged into it, Rune's Revivify restored the White, and Ponzi holds a ring with chains from the Banshee. The party advanced to Level 7 and established itself in Olama, taking rooms at the Manticore's Mug and building ties to the militia, the smith, the grove and the chess elder.", "t": 245}, "learned": {"headline": "The root in Ponzi's pocket is Veins of Yavanna, tied to the Lord of Blood", "detail": "Tudor identified the red/green root in Ponzi's glass vial as Veins of Yavanna — alchemically and magically potent, but something Olama wants nothing to do with because of its connection to the Lord of Blood, who is gone but whose scars remain on the city. Tudor urged them to put it away and keep it away.", "t": 7118}, "who": {"headline": "Frosalk", "detail": "Rune's invitation to warm himself at the hearth opened the whole city: Frosalk gave the party the Mark of the Rose, the history of the Unbroken, the reason Olama is called the City of the Blind, the four districts, the lead on Halas Gold, and the pink-haired hero that made Rune sit up. He also took Nyx's brawl wager, which is where the session ends.", "t": 2712}, "cost": {"headline": "Roughly 545 gold spent and a dangerous relic still in the pocket", "detail": "390 gold for the Phase Steel darts, 20 for the pocket knife offering, 80 for the dragon scale hammer commission, 55 for temple offerings, plus gambling losses (Ponzi 5 gold on the shield, Rune 45 before winning it back). The 7,000-gold Phase Steel daggers are out of reach. Nyx has a tattoo of Frosalk's choosing riding on tonight's brawl, and the party is still carrying the Veins of Yavanna through a city that hates it.", "t": 5492}, "hanging": {"headline": "Justice or vengeance — and who is Asher?", "detail": "The figure on the throne named Ponzi \"Asher,\" said another had spoken for him, and told him he would have to choose between justice and vengeance sooner than he thinks. They will not meet again until the choice is made. Ponzi has no answer.", "t": 200}}, "beats": [{"t": 16, "kind": "combat", "title": "Previously on — the trials close out", "line": "A recap of the previous battle: Ponzi got the Banshee to reveal the mermaid was a sea hag and then defeated the hag, Rune cast Revivify on the White and revived him, Talon's Bardic Inspiration finally commanded the Nothic, and the Pyrelings merged into Nyx's glaive.", "facets": [["Combat", "Tunnels filling with water put time pressure on Talon; the Nothic dropped the fight and fled, leaving Talon's fife."], ["Item", "The Banshee gave Ponzi a ring with chains; Nyx consecrated his glaive."], ["Character", "Silvari Collis identified as Rune's guide — from the first glaive, died from skulls in a nasty eastern swamp. Ponzi speaks to the part of Savari that is still dead; Savari is \"pretty shattered.\""]]}, {"t": 156, "kind": "reveal", "title": "Alvgand shows each of them what they could become", "line": "Alvgand showed every party member a vision of their potential.", "facets": [["Character", "Talon: robed in wisdom, playing his fife with other instruments accompanying — a master improviser."], ["Character", "Nyx: a radiant knight and mighty commander, eyes alight with purpose, shining, forgiven, standing tall."], ["Character", "Moonwillow: a woman fully alive, robes snapping as she dances, hood off, a brilliant cascade of flowing light — no longer hiding."], ["Character", "Ponzi: just as he is, but one side dark with wings, the other side light. Darkness takes him."]]}, {"t": 187, "kind": "dread", "title": "The coin, the throne, and the name Asher", "line": "Ponzi collapses into a wide hall with a flipping coin and a throne, where a mysterious figure calls him \"Asher\" and asks whether he seeks justice or vengeance.", "facets": [["Major NPC", "The figure (implied: Diane / a deity) says he stands for dying himself because another spoke for him — \"one he knew deeply yet not at all.\""], ["Decision", "Ponzi doesn't know his answer. The figure says he will have to choose sooner than he thinks, and they won't meet again until the choice is made."], ["Item", "Ponzi leaves the stone he took from the locked door; Nyx gives Ponzi his oligon to give him three scales."]]}, {"t": 224, "kind": "travel", "title": "On to Olama", "line": "After checking in on Savari, the party moves on to Olama, reaching it the next afternoon.", "facets": [["Environment", "Olama flies no national banners — only banners of Olama itself."]]}, {"t": 245, "kind": "rule", "title": "Level 7", "line": "The party levels up to Level 7, with heroic inspiration available to spend on hit die re-rolls.", "facets": [["House ruling", "Heroic inspiration can re-roll a hit die on level up, but the new roll stands even if lower. If a rolled hit die is less than half the die value, take half instead."], ["Character", "Talon gains Reliable Talent (skill/tool proficiency checks treated as minimum 10); minimum stealth estimated ~20-23 now, ~33 at Level 9."], ["Character", "Doug's character (Bard) gains Counter Charm and a 4th-level spell slot plus a new spell. Rune/Moonwillow gains an extra slot and spell. Nyx (Paladin) gains an extra slot and eyes Revivify."], ["Environment", "A new map of the Ald Hills is revealed — location names, settlements, forests, and diamond markers for cities."]]}, {"t": 1279, "kind": "scene", "title": "Arrival in the City of the Blind", "line": "The party arrives at Olama and enters the Dusk Horn District, finding a bright, joyful city where literally every citizen is armed.", "facets": [["Environment", "Wild folk visible: wild elves with antlers/feathers/claws, wild halflings with wild hair, satyrs. Main walls plus two outer walls creating smaller districts; a small castle at the back."], ["Environment", "Two gathering places identified: Manticore's Mug (humble tavern and gambling hall, run by Berengar) and The Clouded Green (higher-end smoking hall, run by Dialog). The party chooses the Manticore's Mug."], ["Character", "Talon whispers to Ponzi: \"Best behaviors now, right? New place. New opportunities. I don't want you guys embarrassing me.\" Then walks ahead."]]}, {"t": 1751, "kind": "social", "title": "The Manticore's Mug", "line": "The party settles into Berengar's tavern — stew, roast, bread and ale — and takes stock of the games on offer.", "facets": [["Environment", "Tavern started small and expanded; one wall blown out, canopies outside with a central fire pit. Strange long needle-like spikes driven into the wood behind the bar hold shelves of finer alcohols."], ["Major NPC", "Berengar — elven male, owner/operator, welcoming with dry humor."], ["Item", "Brown ale 2 silver/pint, white moon mead from Va 1 silver/glass, silverberry brandy, blood wine. Food 1 gold/plate; drinks 13 silver for the first round."], ["Environment", "Games available: Devil's Dice, card games, arm wrestling, brawling, Dagger and Shield."]]}, {"t": 2369, "kind": "plan", "title": "Counting Alvgand's bronze", "line": "While waiting for food the party assesses the bronze bars awarded by Alvgand: 4,900 gold worth of bronze that needs a gold merchant.", "facets": [["Decision", "Frosalk directs them to Halas Gold, a gold merchant representing a mining guild."]]}, {"t": 2425, "kind": "social", "title": "Rune invites a cold half-orc to the hearth", "line": "Rune stokes the fire and invites a thin, heavily tattooed half-orc to warm himself — Frosalk, militia veteran.", "facets": [["Major NPC", "Frosalk: gray-green skin, wild eyes, bald, covered in tattoos, piercings in the left ear including a pink gem at the top point."], ["Character", "Rune: \"You seem cold. Come warm yourself.\" Frosalk examines Rune's porcelain skin/markings with familiarity — \"This is you?\""], ["New lore", "The mark many in town share is the Mark of the Rose, worn by militia members who have trained the most."]]}, {"t": 2712, "kind": "lore", "title": "Frosalk's lore dump — why Olama never sleeps armed", "line": "Frosalk explains that Olama is the City of the Blind: it once elevated a group called \"the Unbroken\" as heroes, and they turned out to be liars and cowards who killed one of their own and lied to the city.", "facets": [["New lore", "Good people came, opened the city's eyes, gave a speech, then left to compete in the Artland Race around the island — and won. After that Olama formed the militia and began the Mark of the Rose."], ["Quote", "\"Learn the lesson or two. The higher you place someone on a pedestal, the more damage they do when they fall from it.\""], ["Clue", "One of the heroes had pink hair — Rune perks up, having studied the Va bond extensively. Possible connection to her backstory or lineage."], ["Clue", "Frosalk's favorite tattoo is a tree on his forearm lit ablaze. On his left hand is a brand he glosses over and winces near. Significance unknown."]]}, {"t": 3049, "kind": "social", "title": "Nyx wagers a tattoo", "line": "Nyx challenges Frosalk to a brawl with a wager: the loser gets a tattoo of the winner's choice.", "facets": [["Quote", "\"I've got money. I'd like to see some of those fighting skills. What do you say? Put a wager down.\""], ["Decision", "Frosalk accepts; Nyx starts designing the tattoo in his mind. Berengar overhears and thanks Nyx for providing the night's entertainment."]]}, {"t": 3351, "kind": "social", "title": "Two games of chess with Boshin", "line": "Ponzi plays chess with an older man in the corner; Boshin wins the first game with an unorthodox opening, Ponzi takes the second.", "facets": [["Major NPC", "Boshin — philosophical, observant: \"I find chess as a way of getting to know people. Staying connected.\" and \"Not so bad yourself. I don't believe in going easy.\""], ["Check", "No proficiency in chess sets for the party; straight Intelligence check. Talon rolled 18 (natural 20 — DM noted \"not fair\")."], ["Decision", "Ponzi buys Boshin a glass of wine (2 gold) and tells him the party is called the Driftwood Kids — the first time the group identity is stated to an NPC. Boshin: \"You like to help. Interesting.\""]]}, {"t": 3685, "kind": "lore", "title": "The four districts", "line": "Frosalk lays out Olama's geography: Dusk Horn, Haven, Sight Steel and Wild Yard.", "facets": [["Environment", "Dusk Horn — current location, Manticore's Mug and The Clouded Green. Haven — militia center. Sight Steel — library, Phase Steel smithy, Temple of Eratas, newer outer walls. Wild Yard — northwest, outside the main walls, grove maintained by the Endolf family, leather worker, potter."], ["New lore", "Temple of Ailena the Bride sits near The Clouded Green; Temple of Eratas the Champion (Ailena's spouse) is much newer — built within the last year. Both are decorated with rose gold filigree."], ["Environment", "Also noted: Monument of the Citizen, Glimmering Rose Jeweler, Halas Gold, the Phase Steel Smithy, and the library."]]}, {"t": 4010, "kind": "lore", "title": "Odd Steele and the metal that sings", "line": "At the Sight Steel District smithy the party meets Odd, a huge soot-covered half-orc who works Phase Steel.", "facets": [["Major NPC", "Odd: long dreaded hair pulled back with brightly colored ropes, bright orange eyes like glowing coals, tusks jutting high and exaggerated. Works in tandem with both Maya the Smith and Arounme."], ["New lore", "Phase Steel (also \"face steel\") produces a pure tuning-fork note when struck and does something different every time it is forged. Captain Barley, captain of the guard, carries a Phase Steel blade Odd made."]]}, {"t": 4212, "kind": "item", "title": "The dart-throwing competition", "line": "Talon buys 12 Phase Steel blow darts for 390 gold after a five-shot competition against a sliding price, plus a Phase Steel pocket knife as a Festival of Oaths offering.", "facets": [["Item", "The darts are plus-one ammunition whose enchantment is consumed on use; on a hit, Cutting Words rolls twice and takes the higher d8. Talon's spellcasting ability check to harmonize with them: 21."], ["Check", "Starting price 500 gold, 4 targets from AC 12 climbing by 2; each hit -15, each miss +15. Shots: miss, 23 hit, 25 hit, 20 hit, then a miss (17). Final price 390 gold."], ["Check", "Talon cast Bless on the last dart; Odd noticed (Deception 16 vs. his insight), smiled and said \"go ahead.\" Afterwards: \"You're looking to buy something? I don't think I saw anything.\""], ["Item", "Talon persuaded Odd (Persuasion 15) to hand over the ~4.5-inch Phase Steel pocket knife as an offering for 20 gold. He also keeps 7 normal darts."]]}, {"t": 5599, "kind": "item", "title": "A hammer from a dragon's scale", "line": "Ponzi shows Odd three brass dragon scales and commissions a simple, honest utility hammer from one of them.", "facets": [["Item", "Price: about 75 gold or one of the other scales; Ponzi pays 80 gold. Pickup late morning the next day."], ["Major NPC", "Odd recognizes the scales — he knows of Alvgand, a dragon within a day and a half of Olama — and is excited to work with the material."]]}, {"t": 5795, "kind": "item", "title": "The daggers they cannot afford", "line": "Odd shows a pair of Phase Steel daggers that return like boomerangs when thrown at long range — 3,500 gold each, 7,000 for the pair.", "facets": [["Item", "Lightweight, almost like mithril; edges cut backwards against themselves like individual fibers. The sheath itself wants to reunite with the blade."], ["Character", "Rune throws them in the training grounds and hits a bullseye at long range (60 ft); the daggers return. Still 7,000 gold."], ["Decision", "Ponzi considers trading his plus-one spear from the delve but decides to wait and check the leather worker about armor first."]]}, {"t": 6401, "kind": "plan", "title": "Splitting 4,900 gold in bronze", "line": "The bronze bars are split three ways — 1,633 gold each, with roughly 100 gold remainder — after Ponzi takes the dragon scales instead of a share.", "facets": [["Decision", "Remainder to be gambled or split evenly. The bars still need converting at Halas Gold."]]}, {"t": 6557, "kind": "scene", "title": "Offerings at both temples", "line": "The party visits the Temple of Ailena the Bride and the Temple of Eratas the Champion; Ponzi buys offerings.", "facets": [["Item", "5 gold incense plus a goblet (~50 gold for the simpler version) = 55 gold total."], ["Environment", "Both temples decorated with rose gold filigree; the Temple of Eratas is much newer, built within the last year."]]}, {"t": 6903, "kind": "reveal", "title": "Tudor shudders at what's in Ponzi's pocket", "line": "Passing a specifically guarded grove of peach, orange and grapefruit trees, Ponzi shows the halfling grove guide Tudor a solid glass vial holding a red/green root — and Tudor recoils.", "facets": [["New lore", "The root is Veins of Yavanna: it has alchemical or enchanting properties, but the city of Olama wants nothing to do with it."], ["Quote", "\"What have you been carrying in your pocket?\" … \"Put that away. Keep it away.\""], ["New lore", "Tudor mentions the Lord of Blood — \"generally try not to deal with people with that name. He's gone but the scars he made these day.\""], ["Item", "Ponzi also has a Gorgon horn with no resolution yet; the party debates selling some of the six barrels stored in a portable hole, which might fetch a price but attract dangerous attention."]]}, {"t": 7866, "kind": "social", "title": "Devil's Dice", "line": "A tiefling dealer runs the dice table: bet gold, roll 3d6 against the dealer's 1d6.", "facets": [["Check", "Match 1 die = bet back plus an equal amount; match 2 = plus 2x; match 3 = plus 3x; miss = lose the bet."], ["House ruling", "Sleight of Hand may be used to cheat and flip one die to a desired face. Natural 1 = flip one but reroll another; natural 20 = flip one and reroll another."], ["Character", "Rune won 25 gold net; Ponzi won about 40 gold net using Sleight of Hand (including a natural 20); Talon ended roughly even or slightly down; Doug's character netted +30 over one stretch."]]}, {"t": 8544, "kind": "combat", "title": "Dagger and Shield", "line": "The tavern's dagger-throwing game: five throws against a shield holder charging a mud lane, with the AC set by the holder's Athletics check each round.", "facets": [["Check", "Talon (throwing, Steady Aim) hit all 5 against a plus-seven opponent and won 50 gold; later hit 4 of 5 against a proficient opponent for 40 gold."], ["Character", "Rune hit all 5 against Odd including two natural 20s with blade-singing wisps visible — the crowd is stunned — winning 75 gold, then lost 45 and took double-or-nothing to win 90 back."], ["Character", "Ponzi on the shield side against a blue-skinned woman with silvery floating hair: low Athletics, she hit 4 of 5, one dagger buried through the shield to the crossguard. Lost 5 gold. Nyx dodged 3 of 5 against her and won 30 gold."], ["House ruling", "Reliable Talent applied to Talon's Persuasion for negotiating price — rolled 9, became 10, then +7 = 17."]]}, {"t": 10471, "kind": "social", "title": "Not quite strong enough", "line": "Rune asks a scarred, bruised dwarf arm wrestler to try his dwarven whiskey, takes a large glug, feels a brief warmth and nothing else.", "facets": [["Quote", "\"It was good, but not quite strong enough.\""], ["Character", "The dwarf and nearby patrons are bewildered; Rune gives him a silver piece and concludes it was definitely the strongest thing in town."]]}, {"t": 11074, "kind": "scene", "title": "The Vollenhand begins", "line": "Frosalk steps into the sandpit with his forearms wrapped, Nyx removes his armor to reveal his tattoos, and a dwarven chant starts rolling through the crowd.", "facets": [["Character", "Talon paints a courage/ingenuity/luck sigil on Nyx before the fight."], ["Check", "No one in the party speaks Dwarvish. Talon's Persuasion with disadvantage to get a translation: 6, fails. Ponzi bluffs that he knows (Deception 22 vs. Insight 15) and the dwarf pulls him in tight — \"Volanand\" translates roughly to \"beer fighting.\""], ["New lore", "Vollenhand rules: multiple rounds of Con saving throws vs. ale, then brawling — drinking and fighting simultaneously. Ale is brought to the sides. Session ends here."]]}], "threads": [{"u": "hi", "q": "Ponzi's Identity as \"Asher\": Who is Asher? Why does the mysterious figure know this name? What is the choice between justice and vengeance? Who \"spoke for\" Ponzi?", "t": 200}, {"u": "hi", "q": "Veins of Yavanna: What does it actually do? Who is the Lord of Blood? Why does Olama fear it? Is carrying it dangerous?", "t": 7118}, {"u": "hi", "q": "Frosalk's Brand: Hidden, painful, avoided. Likely significant to his past or a faction.", "t": 3002}, {"u": "md", "q": "The Pink-Haired Hero: Direct connection to Rune's studies of the Va bond. Could be an ancestor, mentor, or key figure.", "t": 2882}, {"u": "md", "q": "Savari's Shattered State: Rune's guide is barely holding together. What does it take to restore him?", "t": 140}, {"u": "md", "q": "Boshin's True Identity: He seems more than a chess-playing elder. His interest in the Driftwood Kids feels deliberate.", "t": 10811}, {"u": "md", "q": "Six Barrels: What's in them? Who wants them? Selling risks exposure.", "t": 7055}, {"u": "md", "q": "Temple of Eratas (New): Why was it built so recently? Political or divine significance?", "t": 3828}], "next": ["Complete the Vollenhand brawl (Nyx vs. Frosalk — drinking + fighting; tattoo wager on the line)", "Pick up Ponzi's dragon scale hammer from Odd (late morning)", "Convert 4,900 gold in bronze bars at Halas Gold", "Find push-on-heel for Rune (The Clouded Green or Captain Barley)", "Visit the leather worker in Wild Yard (armor upgrades)", "Visit the Glimmering Rose Jeweler", "Explore the library in Sight Steel District (research: Unbroken, Lord of Blood, Veins of Yavanna, pink-haired hero)", "Decide what to do with the six barrels in the portable hole"], "entities": [{"name": "Frosalk (Fro Salk)", "kind": "npc", "note": "Thin half-orc militia veteran and founding member, Mark of the Rose, covered in tattoos with a pink gem piercing. Delivered the history of the Unbroken and the City of the Blind. Has a brand on his left hand he avoids showing. Nyx's Vollenhand opponent.", "t": 2425}, {"name": "Berengar", "kind": "npc", "note": "Elven male, owner/operator of the Manticore's Mug tavern and gambling hall. Welcoming, dry humour, thanked Nyx for providing the night's entertainment.", "t": 1896}, {"name": "Boshin", "kind": "npc", "note": "Older man with a chessboard and a glass of wine in the corner of the Manticore's Mug. Played two games with Ponzi, won the first, lost the second. Noted the Driftwood Kids \"like to help\" with interest.", "t": 3351}, {"name": "Odd", "kind": "npc", "note": "Large soot-covered half-orc smith, owner of Odd Steele in the Sight Steel District. Works Phase Steel; works in tandem with Maya the Smith and Arounme. Sold Talon the darts and commissioned Ponzi's hammer.", "t": 4140}, {"name": "Tudor", "kind": "npc", "note": "Halfling grove guide for the Endolf family. Identified the Veins of Yavanna, invoked the Lord of Blood, and urged the party to keep the root hidden. Pointed to The Clouded Green or Captain Barley for push-on-heel.", "t": 7002}, {"name": "Captain Barley", "kind": "npc", "note": "Captain of the guard in Olama; carries a Phase Steel blade made by Odd. Named as a possible source for push-on-heel.", "t": 4311}, {"name": "Dialog", "kind": "npc", "note": "Runs The Clouded Green, a higher-end smoking hall and tavern in the Dusk Horn District. Not yet met.", "t": 1512}, {"name": "The Blue-Skinned Woman", "kind": "npc", "note": "Light blue skin, silvery hair that floats as if underwater. Skilled Dagger and Shield thrower; hit 4 of 5 on Ponzi, lost to Nyx.", "t": 9097}, {"name": "Olama (City of the Blind)", "kind": "place", "note": "Independent, fortified island city-state flying only its own banners. Universally armed citizenry, four districts (Dusk Horn, Haven, Sight Steel, Wild Yard). Also spelled Alama in the source.", "t": 1279}, {"name": "Manticore's Mug", "kind": "place", "note": "Humble tavern and gambling hall in the Dusk Horn District with a mud lane for Dagger and Shield and a sand pit for brawling. The party's temporary base.", "t": 1751}, {"name": "Endolf Grove", "kind": "place", "note": "Guarded grove of peach, orange and grapefruit trees in the Wild Yard, maintained by the Endolf family with Tudor as guide.", "t": 6971}, {"name": "Olama Militia", "kind": "faction", "note": "Founded after the betrayal of the Unbroken. Mark of the Rose worn by those who trained the most; militia centre in the Haven District; Captain Barley leads the guard.", "t": 2712}, {"name": "The Unbroken", "kind": "faction", "note": "Defunct. Elevated as heroes by Olama, exposed as liars and cowards who killed one of their own. Their fall created the militia culture and the City of the Blind identity.", "t": 2791}, {"name": "The Lord of Blood", "kind": "faction", "note": "Historical threat connected to the Veins of Yavanna. Gone, but the scars he made remain on Olama. Mention alone visibly distresses knowledgeable NPCs.", "t": 7221}, {"name": "Veins of Yavanna", "kind": "item", "note": "A red/green root in a solid glass vial carried by Ponzi. Alchemical/enchanting properties; Olama wants nothing to do with it. Connected to the Lord of Blood.", "t": 6791}, {"name": "Phase Steel", "kind": "item", "note": "Unique material forged at Odd's smithy; rings like a tuning fork when struck and does something different every time it is forged.", "t": 4356}, {"name": "Enchantment Breaker Ring", "kind": "item", "note": "Given to Ponzi by the Banshee after the sea hag was defeated. Properties unknown.", "t": 116, "alias": "Ring with Chains"}, {"name": "Algovan", "kind": "creature", "note": "A dragon within a day and a half of Olama. Awarded the party bronze bars, showed each member a vision of their potential, and is the source of Ponzi's brass dragon scales.", "t": 156, "alias": "Alvgand"}], "gaps": ["Notta's roster for this session was garbled (\"Nyx/Nick\", \"Moonwillow/Rune\", \"Ponzi/Fonze\") and invented a fifth member from a mis-heard name. Corrected by hand to the four PCs confirmed by the surrounding sessions.", "Heavy proper-noun variance is preserved rather than resolved: Olama / Alama / \"Llama\"; Ponzi / Konzi / Fonze / Asher; Rune / Moonwillow; Nyx / Nick; Silvari Collis / Savari; Frosalk / Fro Salk; Vollenhand / Volanand; Yavanna's root as \"Veins of Yavanna\". The note's own Action Items ask the table to align on canonical spellings.", "The regenerated V3 note still carries a residual generic \"Project Sync / Status Update Summary\" block from an earlier template run; it duplicates the D&D content in corporate framing.", "Internal contradiction: the NPC index says Captain Barley is \"tonight's brawl opponent\" while the rest of the note consistently says Nyx fights Frosalk; the note itself flags this as needing clarification.", "Internal contradiction on the dart competition arithmetic — the note shows the price landing at 470, then says \"actually 455,\" then \"tracked as 390 in session,\" and 390 is the figure carried forward.", "Internal contradiction on the Pyrelings: the digest and cinematic recap describe a fifth/last Pyreling merging with the glaive, while the combat breakdown says \"all six Pyrelings.\""], "timecodesReliable": true, "iso": "2026-02-19", "pretty": "19 Feb 2026", "audio": false, "legendary": true, "n": 6}, {"slug": "combat-encounter-magical-weapon", "title": "Dungeons and Dragons Campaign Session: Combat Encounter and Magical Weapon Acquisition", "date": "02/05/2026 19:33", "runtime": "2h 57min 37s", "nottaId": "7ae33442-ed9a-482d-8a6b-9b78767bb13b", "url": "https://app.notta.ai/7366972874555052032/dashboard/7ae33442-ed9a-482d-8a6b-9b78767bb13b", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 10657, "subtitle": "Four trials, four rooms, nobody together", "logline": "Each of the Driftwood Kin passes a solo trial in Algovan's Tower and walks out with a magical item, a revived settler, and Ponzi's real name spoken aloud by a stranger on a throne.", "recap": "Previously on Driftwood Kin…\nThe tower of Algovan the Bronze Dragon demanded a price — not gold, not blood, but truth. Each member of the Driftwood Kin descended into their own trial, alone.\nTalon waded through rising black water, trading words with a gnarled, ring-knuckled Nothic that guarded a dragon's skull and the secrets within it. Three commands. Two refusals. One bardic note of discord — and the creature fled, leaving behind a wooden fife that hummed with the memory of dragons. The tunnel filled. Talon ran.\nNix stood in the deep, fire against water, rallying the lost pyreling spirits one by one until six burned in the spokes of their glaive. They cast their shield of faith in dripping liquid flame, drove their blade into the heart of the Water Weird, and emerged — not as a masked changeling, but as themselves.\nRune Willow faced a creature caught between death and life, and chose to offer it both. She struck with a blade wreathed in restoration, pressed her hand to its decayed face, and pulled a man — Sylvari Kallis, dead for years — back from the fog. The fog retreated. The flowers were still dead. But he breathed.\nPonzi leveled his spear at a Banshee and asked why. He listened. He healed. He killed the hag that had trapped her, and received a ring of chains from a cold, fading hand. Then he looked into a mirror and saw two futures — and darkness took him.\nIn the dark hall, a coin rang. A figure on a throne called him Asher. The Book of Fates lay open. Two pages. Two paths. \"You will choose sooner than you think.\"\nThey emerged from the tower changed. Algovan showed them their reflections — master, warrior, dancer, and a soul split between shadow and light. Bronze bars were exchanged. Broken scales were given. A first-wave settler blinked green eyes and said, \"I died. I won't waste it.\"\nNow the Driftwood Kin walks toward Alama — a city that flies no one's banner but its own.", "dm": null, "party": ["Talon — Bard (Rogue inspiration noted)", "Nix — Changeling Paladin/Cleric (fire/pyreling theme)", "Rune Willow — Wizard/Bladesinger (half-elf, ring of Lesser Restoration)", "Ponzi (real name: Asher) — Rogue/Paladin hybrid (spear user, Banshee ally)"], "opens": "Inside Algovan's Tower — individual trials underway.", "closes": "Outside the walls of Alama, a fortified independent city.", "cards": {"changed": {"headline": "All four trials passed, and every member walked out armed differently", "detail": "Talon has the Fife of Dragonsong, Nix has the Guardian's Glaive with six pyrelings merged into its spokes and consecrated to Asus, Rune Willow passed by choosing to heal instead of kill, and Ponzi has the Enchantment Breaker Ring. Sylvari Kallis was pulled back from the dead and welcomed into the Driftwood Kin, Algovan and the party struck a mutual call agreement, and the party is now outside Alama.", "t": 10047}, "learned": {"headline": "Vore Banner — a necrotic swamp east at the end of the N River", "detail": "Sylvari Kallis, a first-wave settler on the island, died at Vore Banner investigating skulls at the beginning of the Roiling Cloud. It is filled with necrotic energy and remains unexplored, and it ties the island's earliest history to whatever the Roiling Cloud is.", "t": 6775}, "who": {"headline": "Ponzi — who is actually Asher", "detail": "The session turned on Ponzi's vision. He talked a Banshee down instead of killing her and freed her, then collapsed at the Mantle of Potential into a throne room where the Solemn Keeper of the Prisons called him by his real name, showed him a page of the Book of Fates written twice, and told him someone who \"knew him deeply and yet not at all\" had spoken for him.", "t": 8472}, "cost": {"headline": "The Diviner Stone given up, and a dragon made to break his own scar", "detail": "Ponzi surrendered the Diviner Stone — a tool he had been hoarding — for bronze bars, and Algovan broke three scales off his scarred stomach with visible shame and grief. In the fights Ponzi took necrotic damage from the Banshee's Corrupt Touch, Nix took bludgeoning from the Water Weird's Whelm even on successful saves, Talon nearly drowned in the rising tunnel, and Talon's tinkerer's supplies ran low.", "t": 9453}, "hanging": {"headline": "Who spoke for Ponzi to the Solemn Keeper?", "detail": "The Keeper said an intercessor who \"knew him deeply and yet not at all\" spoke on Asher's behalf. The identity is unknown, and it sits directly under Ponzi's forced choice between justice and vengeance — which the Keeper says will come sooner than he thinks.", "t": 8543}}, "beats": [{"t": 342, "kind": "scene", "title": "Four trials, four rooms, nobody together", "line": "The Driftwood Kin are inside Algovan's Tower, each member alone in an individual trial keyed to a theme: Act, Shine, Live, and Purpose.", "facets": [["Character", "Party: Talon — Bard (Rogue inspiration noted); Nix — Changeling Paladin/Cleric (fire/pyreling theme); Rune Willow — Wizard/Bladesinger (half-elf, ring of Lesser Restoration); Ponzi (real name: Asher) — Rogue/Paladin hybrid (spear user, Banshee ally)."], ["Environment", "Each trial ends with a unique magical item tied to that member's test theme."]]}, {"t": 368, "kind": "item", "title": "The Dawn Guardian", "line": "Talon secures the Dawn Guardian, a radiant weapon requiring attunement.", "facets": [["Item", "+1 to attack and damage rolls; becomes +2 between dawn and dusk. A protective/monitoring guardian presence is sensed within roughly 10 feet."], ["House ruling", "The note flags its own conflicting phrasing — \"between dawn and dusk +2\" versus \"during the day, +1\" — and the aura's exact range, triggers and benefits as needing GM clarification."]]}, {"t": 1777, "kind": "combat", "title": "Ponzi's trial (Purpose): a Banshee and a mermaid", "line": "Ponzi engages a Banshee and a disguised Sea Hag posing as a mermaid in a flooded chamber.", "facets": [["Environment", "Flooded chamber shared with a Water Weird, pyrelings, the Banshee and the Sea Hag; combat took place partially submerged."], ["Combat", "The Banshee opened with Horrify (Ponzi saved on a 15, granting hours of immunity to that effect) and Corrupt Touch for 10 necrotic reduced to 5."]]}, {"t": 2079, "kind": "scene", "title": "Talon's trial (Act): the Nothic in the flooding tunnel", "line": "Talon enters a flooding tunnel and finds a Nothic guarding a dragon skull.", "facets": [["Environment", "Water rose incrementally — the DM rolled a D4 each round for water level, with four levels before full submersion at the start of the trial. It went hip-deep to chest-deep during Talon's turns (D4 rolls of 2 and 4 noted)."], ["Major NPC", "The Nothic has old gold/brass rings embedded in its knuckles and remnants of arcane tattoos. A wooden fife was hidden inside the dragon skull."]]}, {"t": 2507, "kind": "magic", "title": "Rune Willow's trial (Live): \"Come with me and live\"", "line": "Rune Willow faces a creature embodying a battle between necrotic death and radiant life, and chooses to heal it rather than kill it.", "facets": [["Environment", "A fog-hemmed area with dead grass and flowers and skulls at the perimeter."], ["Check", "She cast Lesser Restoration as a bonus action (confirmed by the DM), wreathed her blade in golden light, and struck for 12 damage on a 16 to hit. The spell poured into the creature's veins and its necrotic side fought the restoration."], ["Quote", "\"Come with me and live\" — Persuasion 14 against a Charisma save of 18 (dirty 20 with +2); the creature was not persuaded."]]}, {"t": 2979, "kind": "combat", "title": "Nix's trial (Shine): fire against water", "line": "Nix fights a Water Weird in a flooded chamber while rallying pyreling spirits to their glaive.", "facets": [["Combat", "Nix cast Burning Hands, channelling warmth toward the pyrelings — a fourth pyreling appeared and joined. DC22 DEX save, 6 damage."], ["Combat", "The Water Weird used Whelm; Nix saved three times (15, 23, 18), taking half damage — 6 and 9 bludgeoning."], ["Magic", "Nix cast Shield of Faith on a faith check of 15, manifesting a dripping liquid-fire shield in the shape of their burned shield — which cost them a smite they had attempted on a 21 to hit."]]}, {"t": 3216, "kind": "social", "title": "Ponzi asks the Banshee why", "line": "Rather than attacking, Ponzi levels his spear at the Banshee in a threatening gesture and asks what she wants.", "facets": [["Quote", "\"Why are you attacking this creature? What is your purpose?\" — Intimidation check 11."]]}, {"t": 3480, "kind": "clue", "title": "\"Foul witch!\" — the Banshee is the victim", "line": "The Banshee screams \"Foul witch!\" and Ponzi's Insight of 18 reads genuine hatred and green fear, identifying her as a trapped creature rather than the threat.", "facets": [["Major NPC", "The Banshee: undead, trapped by the Sea Hag, not evil — a victim."]]}, {"t": 3633, "kind": "reveal", "title": "Healing Hands cracks the disguise", "line": "Ponzi casts Healing Hands on the Banshee for 8 points and the Sea Hag's mermaid disguise breaks, revealing her true form.", "facets": [["House ruling", "Healing Hands was ruled a Magic Action (race feature) and allowed as risky enough given the circumstances."], ["Combat", "The Banshee answered with Death Wail; the Sea Hag failed a DC 13 CON save for 9 psychic damage. The Sea Hag's Death Glare on Ponzi failed against his DC 11 WIS save (he rolled 11)."], ["Major NPC", "Revealed as a Flower Sea Hag; her Vile Appearance forces WIS saves at the start of turns."]]}, {"t": 4104, "kind": "social", "title": "The Nothic bargains with forbidden knowledge", "line": "The Nothic keeps the wooden fife hidden behind its back, shrugs off two command spells, and tries to lure Talon in with forbidden knowledge.", "facets": [["Check", "Talon's spell save DC is 15; the Nothic's WIS save is +0. Two Commands still failed."], ["House ruling", "Command was ruled an action, leaving movement and bonus action available. Cutting Words was confirmed to affect saving throws. Heroic Inspiration was allowed after the table debated whether Talon still had it — he had it written down as \"Rogue Inspiration.\""]]}, {"t": 4439, "kind": "magic", "title": "One bardic note of discord", "line": "Talon uses Cutting Words to impose disadvantage on the Nothic's wisdom save, then casts Command: Flee — the Nothic rolls a 1, obeys, and escapes through a crack in the rock.", "facets": [["Combat", "Talon grabbed the fife from the dragon skull, squeezed through the crack, and escaped the flooding tunnel."], ["Environment", "The note flags the flooding tunnels as a near-death scenario for Talon."]]}, {"t": 4574, "kind": "magic", "title": "A handprint of living flesh", "line": "Rune Willow touches the decayed side of the creature's face and releases Revivify; her handprint becomes flesh and overtakes the necrosis.", "facets": [["Check", "Blade Song attack to touch: 14+8 = 22 to hit."], ["Reveal", "She grabs the creature as it staggers back into the fog and tears it free, revealing Sylvari Kallis — a scarred half-elf in tattered armor."], ["New lore", "The fog receded back toward the original skulls after Sylvari was freed, suggesting it was tied to his undeath. The flowers stayed dead."]]}, {"t": 5736, "kind": "item", "title": "Identify: the Fife of Dragonsong", "line": "Talon casts Identify on the wooden fife and finds it is the Fife of Dragonsong.", "facets": [["Item", "Rare, requires attunement by a bard. Functions as both instrument and blowgun. +1 to attack and damage, extra 1d6 thunder damage on hit."], ["Item", "Dragon Song: expend one bardic inspiration use — audible at 100 ft, 15 ft cone, DC 15 CON save, 2d6 thunder damage and pushed 10 ft on a fail, half and no push on a success. Allies in the cone get +10 ft speed until the end of their next turn and 2d6 temporary HP for 10 minutes."], ["Character", "Talon was delighted, noting it fit perfectly with his character's story involving dragons. Attunement limit is 3 items and his slots need checking."]]}, {"t": 5902, "kind": "boss", "title": "Six pyrelings merge into the glaive", "line": "Nix's killing blow pierces the centre of the Water Weird in a cascade of purifying fire, and all six pyrelings merge into the glaive's sunburst spokes.", "facets": [["Combat", "Nix performed a Radiant Swing — six ember-pyrelings shot out and returned to the glaive, confirming the ability works with the merged weapon."], ["Item", "The Guardian's Glaive is born: Nix's existing glaive now carrying six pyreling spirits permanently."]]}, {"t": 6047, "kind": "combat", "title": "Ponzi kills the Sea Hag", "line": "Ponzi disengages, charges, and drives his spear into the Sea Hag for 21 damage, killing her.", "facets": [["Combat", "18+7 = 25 to hit, D8 plus force damage. Earlier in the fight a charge attack landed a 27 crit with double dice and Sneak Attack applied (34→40 damage noted)."], ["Combat", "The Sea Hag's claw attack missed — Ponzi's AC was too high — and her Death Glare failed to recharge."]]}, {"t": 6154, "kind": "item", "title": "A cold hand, a ring of chains, and peace", "line": "The Banshee reaches out, places a black ring with small chains in Ponzi's palm, and fades away in peace — a trapped soul freed.", "facets": [["Item", "Enchantment Breaker Ring (from the Griffin Saddlebag supplement): tangy chains rotate on the finger. A reaction can weaken enchantments on allies within 10 ft, and it can attempt to shatter enchantment spells — fear, dominate person, hold person, petrified and others. No attunement required; recharges 4 days after use."]]}, {"t": 6751, "kind": "lore", "title": "Sylvari Kallis, of the first wave", "line": "The revived half-elf is from the first wave of settlers on the island, and died investigating skulls near the N River at a place called Vore Banner.", "facets": [["New lore", "Vore Banner: a swamp to the east at the end of the N River, filled with necrotic energy. Sylvari died there investigating skulls at the beginning of the Roiling Cloud."], ["Major NPC", "Sylvari Kallis (also written Silvari Callis): scarred, tattered armor, bright green eyes, speaks haltingly, repeats \"I died. I won't waste it.\""], ["Check", "Nix's Perception on Sylvari: 19 + 8 = 27 — heard Sylvari's spirit in their mind. A faith check was used to communicate with the spirit, under Wisdom with Ponzi's Charisma modifier applied since he has no religion bonus."]]}, {"t": 6879, "kind": "magic", "title": "A prayer to Asus and a bronze grip", "line": "Nix offers a prayer to Asus and dedicates the glaive; the bronze grip forms naturally where their hands rest.", "facets": [["New lore", "Asus is associated with bronze; Nix has been praying to Asus throughout, and Algovan recognized the name with familiarity."]]}, {"t": 7286, "kind": "social", "title": "\"Welcome to the Driftwood Kin, Silvari\"", "line": "Nix marches up to Sylvari Kallis, lays a hand on his shoulder and welcomes him into the party's faction, using Laid on Hands for 10 points.", "facets": [["Quote", "\"Welcome to the Driftwood Kin, Silvari. Be warmed, my friend.\""], ["Character", "Sylvari's repeated \"I died. I won't waste it.\" became a recurring phrase at the table."]]}, {"t": 7873, "kind": "reveal", "title": "The Mantle of Potential", "line": "At a three-quarters circular balcony of reflective bronze panelling beneath a hovering bronze disc, Algovan shows each party member their reflection of potential.", "facets": [["Environment", "Algovan's tower contains a Bronze Throne, a spiral stair to the balcony, and the large bronze disc hovering magically at the spire's top; the dragon curls in the centre. The disc acts as a concave bronze disc eyelid."], ["Character", "Talon: a man robed in wisdom, armed with action — instruments playing of their own accord, a master improviser."], ["Character", "Nix: a radiant knight in glowing armor, face unmasked as their true changeling gray self, dozens gathered around hearths they kindled. Nix dropped into changeling form hesitantly before stepping up — a moment of vulnerability and self-acceptance."], ["Character", "Rune Willow: a woman fully alive, hood cast back, joy flowing freely as magic, a brilliant cascade of light from crown to shoulders."], ["Character", "Ponzi: two versions — a dark bony necrotic wing and a brilliant white feathered wing. He hesitated before the mirror (bad history with mirrors from the dungeon), Nix put a hand on his shoulder, and then he collapsed."]]}, {"t": 8472, "kind": "dread", "title": "The Solemn Keeper of the Prisons", "line": "Ponzi wakes in a dark hallway, hears a coin ringing, approaches a dark throne, and meets a figure who names himself \"the Final Pronouncement, the Solemn Keeper of the Prisons.\"", "facets": [["Major NPC", "The Keeper holds the Book of Fates — a massive tome with an animate cover — flips a coin, and speaks in measured, deliberate fragments."], ["New lore", "He tells Ponzi that someone who \"knew him deeply and yet not at all\" spoke for him, that Ponzi's page is written in duplicate on two paths, and calls him by the name Asher."], ["Quote", "\"Do you seek vengeance or justice?\" — Ponzi said he didn't know. \"You are not yet ready. You can wield the justice of your own, or the justice wielded by the Asteroids themselves.\""]]}, {"t": 8960, "kind": "social", "title": "\"I offer justice, not rageful vengeance\"", "line": "Ponzi declares his choice and the Keeper answers that he will choose sooner than he thinks.", "facets": [["New lore", "They will not meet again until Ponzi's feet \"speak to sound in this manner\" — the ringing coin."], ["Character", "Ponzi woke to see two versions of himself in Algovan's eye: a dark avenger standing in pools of blood, and a radiant angelic version."]]}, {"t": 9453, "kind": "item", "title": "A stone for bars, and scales broken off a scar", "line": "Ponzi surrenders his Diviner Stone to Algovan and receives bronze bars stamped with a draconic head; Nix asks for three broken scales from Algovan's scarred stomach.", "facets": [["Character", "Surrendering the Diviner Stone was a significant act of letting go of a tool Ponzi had been hoarding."], ["Character", "Algovan broke the scales off with visible shame and grief, shaking his head at his own stupidity before giving them. They are to be forged into the Guardian's Glaive."], ["Decision", "Algovan and the Driftwood Kin agreed a mutual call — he will call on them in times of need if they can call on him, spoken in draconic."]]}, {"t": 10415, "kind": "travel", "title": "Out of the tower and up to Alama's gates", "line": "The party leaves Sylvari in the care of Sorcerer Casein and Mason Oos, travels toward Alama, makes camp, and arrives outside the city walls the next midday.", "facets": [["Environment", "Alama: thick sharpened oak log walls, heavy wooden gates standing open, guard towers and walkways, approached from the wilds. It flies only its own banner — no Tostring, Calestis, Fromva or Cab Arrows."], ["New lore", "From Mandy's campaign: Alama was once called the City of the Blind. Mandy's party affected it significantly — she rallied its people with an improvised speech."], ["Item", "Talon crafted another explosive bolt at camp on a Tinkerer's check of 15 (Intelligence + proficiency); his crafting supplies are now running low. The party is leaving Kraken's Reach and entering the All Tills region."]]}], "threads": [{"u": "hi", "q": "Ponzi's Two Paths (Asher): The Book of Fates has two pages for him. He must choose justice over vengeance before a confrontation that is coming \"sooner than he thinks.\"", "t": 8960}, {"u": "hi", "q": "Who Spoke for Ponzi? Identity of the intercessor with the Solemn Keeper is unknown and critical to Ponzi's arc.", "t": 8543}, {"u": "hi", "q": "Vore Banner / Roiling Cloud: Necrotic swamp to the east, connected to the island's first settlers and the Roiling Cloud. Unexplored and dangerous.", "t": 6775}, {"u": "md", "q": "Sylvari Kallis's Full Memory: He is still recovering. His knowledge of the first wave and Vore Banner is incomplete but potentially vital.", "t": 9866}, {"u": "md", "q": "Alama's Political Independence: No national banners. Unknown governance. Mandy's party changed it significantly. What is it now?", "t": 10479}, {"u": "md", "q": "Nix's Bronze Scales Forging: Three scales from Algovan need to be incorporated into the Guardian's Glaive.", "t": 9713}, {"u": "lo", "q": "Talon's Attunement Slots: Needs to be tracked carefully with new fife.", "t": 6332}, {"u": "lo", "q": "Tinkerer's Crafting Supplies: Talon is running low after crafting another explosive bolt. Needs resupply.", "t": 10273}], "next": ["Enter Alama and gather intelligence on its governance and current state", "Investigate Alama's past as the \"City of the Blind\" — ask careful questions", "Talon: Attune to the Fife of Dragonsong (confirm slot availability)", "Nix: Commission forging of Algovan's three bronze scales into the Guardian's Glaive", "Ponzi: Identify the intercessor who spoke to the Solemn Keeper on Asher's behalf", "Ponzi: Define the deed of justice — what is it, who is the target, vengeance vs. justice", "Talon: Restock tinkerer's crafting supplies", "Rune Willow: Continue studying gifts list (candle study sessions)"], "entities": [{"name": "Algovan (Alvgan)", "kind": "npc", "note": "Ancient bronze dragon with a scarred stomach from past shame. Keeper of the Mantle of Potential. Speaks in draconic when making personal agreements. Recognized Asus. Gave bronze bars for the Diviner Stone and three broken scales to Nix, and agreed a mutual call with the party.", "t": 7776}, {"name": "Sylvari Kallis (Silvari Callis)", "kind": "npc", "note": "Half-elf of the first wave of settlers, died at Vore Banner investigating skulls near the Roiling Cloud. Revived by Rune Willow. Scarred, tattered armor, bright green eyes, speaks haltingly, repeats \"I died. I won't waste it.\" Left in the care of Sorcerer Casein and Mason Oos.", "t": 7150}, {"name": "The Solemn Keeper of the Prisons", "kind": "npc", "note": "Also \"the Final Pronouncement.\" A figure on a dark throne reachable only through Ponzi's vision. Holds the Book of Fates, flips a coin, called Ponzi \"Asher,\" and will not meet him again until the coin rings at his feet.", "t": 8472}, {"name": "The Banshee", "kind": "creature", "note": "Undead creature trapped by the Sea Hag; not evil, a victim. Used Horrify, Corrupt Touch and Death Wail. Gave Ponzi the Enchantment Breaker ring before fading in peace.", "t": 3480}, {"name": "The Sea Hag", "kind": "creature", "note": "Disguised as a mermaid; revealed as a Flower Sea Hag when Ponzi healed the Banshee. Used Death Glare, Corrupting Touch and Horrify, and has Vile Appearance. Killed by Ponzi for 21 damage.", "t": 3780}, {"name": "The Nothic", "kind": "creature", "note": "Arcane creature with old gold/brass rings embedded in its knuckles and remnants of arcane tattoos. Guarded the dragon skull holding the Fife of Dragonsong. Refused two command spells before fleeing on the third.", "t": 4050}, {"name": "Sorcerer Casein", "kind": "npc", "note": "Present at Algovan's Tower, tending to Sylvari Kallis.", "t": 9793}, {"name": "Mason Oos", "kind": "npc", "note": "Present at Algovan's Tower, tending to Sylvari Kallis.", "t": 9793}, {"name": "Olama", "kind": "place", "note": "Fortified independent city with sharpened oak log walls, open wooden gates, guard towers and walkways. Flies no national banners. Formerly called the City of the Blind; affected significantly by Mandy's campaign party.", "t": 10479, "alias": "Alama"}, {"name": "Vore Banner", "kind": "place", "note": "Swamp to the east at the end of the N River, filled with necrotic energy. Where Sylvari Kallis died investigating skulls at the beginning of the Roiling Cloud.", "t": 6775}, {"name": "Asus the Shepherd", "kind": "asterum", "note": "Bronze dragon god. Bronze is Asus's domain; Nix has been praying to Asus throughout and Algovan recognized the name.", "t": 9607, "alias": "Asus"}, {"name": "Driftwood Kin", "kind": "faction", "note": "The party's own growing faction. Sylvari Kallis welcomed as a potential member by Nix.", "t": 7286}, {"name": "Fife of Dragonsong", "kind": "item", "note": "Rare, attunement by a bard. Instrument and blowgun, +1 attack and damage, extra 1d6 thunder on hit, plus the Dragon Song cone that damages enemies and buffs allies.", "t": 6356}, {"name": "Enchantment Breaker Ring", "kind": "item", "note": "Black ring with small rotating chains, from the Griffin Saddlebag supplement. Reaction to weaken enchantments on allies within 10 ft and attempt to shatter enchantment spells. No attunement; recharges 4 days after use.", "t": 6487}, {"name": "Guardian's Glaive", "kind": "item", "note": "Nix's glaive with six pyreling spirits merged into the sunburst spokes, consecrated to Asus with a bronze grip. Radiant Swing confirmed. Algovan's three bronze scales still to be incorporated.", "t": 6879}, {"name": "Dawn Guardian", "kind": "item", "note": "Radiant weapon secured by Talon early in the session. Requires attunement; +1 to attack and damage, +2 between dawn and dusk, with a guardian presence sensed within about 10 feet.", "t": 368}, {"name": "Book of Fates", "kind": "item", "note": "A massive tome with an animate cover held by the Solemn Keeper. Ponzi's page is written in duplicate — two paths.", "t": 8667}, {"name": "Diviner Stone", "kind": "item", "note": "Surrendered by Ponzi to Algovan in exchange for bronze bars stamped with a draconic head.", "t": 9453}], "gaps": ["The source's MAJOR EVENTS section is grouped by character trial rather than strict chronology (Talon's whole trial, then Nix's, then Rune Willow's, then Ponzi's), so its printed order jumps backwards several times. Within each trial the timecodes rise monotonically and every stamp is semantically plausible, so beats here are sorted into true chronological order by timecode.", "Heavy proper-noun variance is preserved rather than resolved: Algovan / Alvgan (spelled Alvgand in the 02/19 session); Sylvari Kallis / Silvari Callis / Silvari; Nix (spelled Nyx in the 02/19 session); Alama (spelled Olama in the 02/19 session); Rune Willow / Rune / Moonwillow elsewhere.", "\"The Asteroids\" in the Solemn Keeper's line is almost certainly a transcription artifact — the note itself hedges it as \"likely Astral beings or divine entities.\" Kept as spelled.", "The note carries a residual generic \"Project Sync / Status Update Summary\" block from an earlier template run. It describes material that appears nowhere in the V3 layers — a whirlpool-like lift, a mutable \"box\" door, an artifact chamber with buttons, a Zone of Truth exchange (\"What is your value/purpose?\" / \"To learn and protect\") — apparently from an earlier stretch of the session that the V3 layers skip.", "The Dawn Guardian appears only in the residual block and the item list, timestamped 00:06:08, and its mechanics are self-contradictory in the source (\"+2 between dawn and dusk\" vs \"during the day, +1\"); the note flags this for GM clarification. It is also unclear how it relates to Talon later attuning to the Fife of Dragonsong given a 3-item attunement limit.", "Internal contradiction on pyreling count: the detail line says \"a fourth pyreling appeared and joined\" while the killing-blow line and the digest both say all six merged into the glaive."], "timecodesReliable": true, "iso": "2026-02-05", "pretty": "5 Feb 2026", "audio": false, "legendary": false, "n": 5}, {"slug": "character-backstories-tower-investigation", "title": "Dungeons and Dragons Campaign Session: Character Backstories and Tower Investigation", "date": "01/19/2026 19:20", "runtime": "3h 27min 31s", "nottaId": "26eec6a5-a9c5-44f2-8d7a-4bbe20c45643", "url": "https://app.notta.ai/7366972874555052032/dashboard/26eec6a5-a9c5-44f2-8d7a-4bbe20c45643", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 12451, "subtitle": "Spells frozen mid-air like insects in amber", "logline": "The party breaks into a doorless arcane tower where every spell they cast misfires, and finds inside it the name of the lich who is their endgame.", "recap": "\"Previously on Driftwood Kin…\"\nThe road to Vattenheim was never going to be easy. But no one warned them about the tower.\nIt stood on the plains like a ghost — white stone veiled in murky gray, surrounded by spells frozen mid-air like insects in amber. Magic hung in the sky, waiting. Patient. Dangerous.\nThey tested it. Firebolt. Light. Thunderclap. The magic answered back — sometimes gently, sometimes not. Ponzi opened a box he should have left closed, and the shadows nearly swallowed him whole. It took a baseball bat, a command spell, a dulcimer, and a sword flourish to pull him back.\nThe door was hidden. Of course it was. Rune Willow found it — a keyhole in a crag, barely visible, deliberate. Nyx picked the lock. The tower answered with a Disintegrate spell that should have turned him to ash. Seventy-seven force damage. Gone. Except Rune Willow threw her cloak, sang her blade, and gave him the last thing she had — her luck. He lived.\nInside: dwarven glory painted over with madness. A name: Lady Shaelra. A man behind her with a lichen staff who became, in the final painting, something terrible. A lich. Vesh. The same arcane signature as their first dungeon. The same screaming grief locked in a shattered orb.\nAnd at the top: a dwarven diviner who saw it all coming. Who painted the prophecy on every wall. Who wailed himself to death from the weight of knowing. His skull rose in blue flame, and the mushrooms came alive.\nPonzi slid on his knees across the stone floor, drew back, and put an arrow through its eye.\nThe tower came down around them.\nThey ran.\nThe Gray Tower is rubble now. But what it told them — about Vesh, about Lady Shaelra, about the dwarven kingdoms that fell — that knowledge is alive. And somewhere ahead, Vattenheim waits.", "dm": null, "party": ["Rune Willow — Wizard/Bladesinger (3 years old, created/born, arcane scholar)", "Talon (real family name: Tanner, grandfather's name; \"Talon\" adopted after orphaning) — Bard, dulcimer player", "Ponzi — Rogue, widower (wife Rose, killed by Wolfgang's wolf gang)", "Nyx (true name: Kayon) — Changeling; pale haunted true form revealed last session"], "opens": "Outside the Gray Tower, on the plains between home and Vattenheim.", "closes": "Gray Tower collapsed; party fleeing through debris field toward the river.", "cards": {"changed": {"headline": "The Gray Tower is rubble and Vesh has a name, a face and a motive", "detail": "A landmark on the road to Vattenheim is gone, taking the mosaics, the paintings, the prophetic sigils and the shattered orb with it. In exchange the party walked out knowing who the endgame antagonist is: Vesh, a druidic lich who was Lady Shaelra's right-hand man, whose grief at her downfall turned him, and whose rise a dwarven diviner foresaw and died of.", "t": 12421}, "learned": {"headline": "The orb's arcane signature exactly matches their first dungeon", "detail": "Rune Willow confirmed the shattered orb's signature is identical to the arcane energy from the party's first dungeon — placing Vesh at that location. The note calls it a major intelligence breakthrough and it retroactively reframes the campaign's opening.", "t": 7606}, "who": {"headline": "Rune Willow", "detail": "She found the hidden keyhole on a nat 20 Arcana when the tower had no door, read the elevator runes to get the party upstairs, matched the orb's signature to their first dungeon, and — when a released 6th-level Disintegrate would have turned Nyx to ash for 77 force damage — gave him her own heroic inspiration for the reroll that saved him. She also batted the Demon Ring Box off Ponzi and cut the tendrils, and Thunderstepped the escape.", "t": 4756}, "cost": {"headline": "Severely depleted — HP, spell slots and every heroic inspiration", "detail": "Multiple members are below half HP, spell slots are expended (including slots burned on spells that froze without ever going off), and all heroic inspirations are used. Ponzi took roughly 39+ necrotic from the ring box, 26 cold from a Cone of Cold and fire on top; Rune Willow took 34 fire in two rays; Nyx took radiant, fire and near-disintegration. A long rest is called critical before proceeding.", "t": 11444}, "hanging": {"headline": "What was inside the orb that screamed?", "detail": "It was cracked from the inside out with mushrooms growing from the fissures, and touching it produced a male scream of anguish and loss. It was left behind in the rubble. The source's own guess is that it held something of Vesh's — his grief, a soul fragment, or a bound entity.", "t": 7797}}, "beats": [{"t": 0, "kind": "scene", "title": "Backstories over breakfast, then a gorgon on the road", "line": "The party wakes from a hag's dream, rests at home, shares backstories, and sets out toward Vattenheim — killing a gorgon by an abandoned wagon of stone statues on the way.", "facets": [["Character", "Backstories shared: Nyx's true name is Kayon; Talon's real family name is Tanner, his grandfather's, with \"Talon\" adopted after he was orphaned and raised by an ambassador; Ponzi's wife Rose was killed by Wolfgang's wolf gang."], ["Environment", "The Wound retrieved a reborn staff and flowers appeared on the floor; the Wound made breakfast. First stop en route: \"a llama via two towers.\""], ["Combat", "The gorgon was defeated with meteors; Nyx consecrated the ground and the party moved the petrified statues to safer positions, intending to return and restore them."]]}, {"t": 179, "kind": "rule", "title": "Arcane Viscosity — a d12 on every spell you cast", "line": "The Gray Tower turns out to be a white tower seen through a murky gray film, ringed by spells frozen in mid-air, and every spell cast in the field requires a d12 Arcane Viscosity roll.", "facets": [["House ruling", "High rolls (10-12) fire normally or are enhanced — a 12 upcasts or grants advantage. Mid rolls (7-9) freeze the spell and release a random ensnared one. Low rolls (1-4) freeze it and release a bad ensnared spell at the casters. Inside the tower the released spell is directed by the caster; outside it targets the party."], ["House ruling", "A hidden d100 aberrant-energy counter accumulates from time spent in the field; every 50-point threshold costs the party 4d6 damage on a save."], ["Environment", "Plains scarred by craters and scorched grass, steam vents beside 10-foot columns of ice. Frozen spells hang in the air: 12-foot streams of ice, jets of flame, green energy, black/purple necrotic clouds, lightning. The frozen-magic field starts about 60 feet out."], ["Check", "Test casts: Rune Willow's Firebolt (d12: 10) fired clean. Ponzi's Light cantrip (d12: 2) froze mid-air leaving five glowing divots. Talon's thunderclap drum roll (d12: 11) fired normally. Nyx dove into the shock wave for fun. Rune Willow bagged a gray rock imbued with necrotic energy in a handkerchief as a sample."]]}, {"t": 565, "kind": "social", "title": "The opposite side of a coin", "line": "Rune Willow touches Ponzi's frozen Light spell and finds it peaceful — the antithesis of Ponzi in his dreaded form — and hears a coin flip.", "facets": [["Check", "Insight 15 while touching his frozen magic; Ponzi noticed she had picked up on something."]]}, {"t": 1576, "kind": "dread", "title": "\"Guys, I have an idea\" — the Demon Ring Box", "line": "The party decides to test the Demon Ring Box in the arcane field; Talon opens it and black shadow tendrils explode out, seize Ponzi and begin compressing him into the box.", "facets": [["Combat", "Rune Willow won initiative on a nat 20 and baseball-batted the box 25 feet with her staff on a 17. Talon's Command (\"Drop\") went off on a d12 of 11 but the box is an object, not a creature. Nyx grappled the box (Athletics 13, then 16) and Ponzi snapped along with it, hovering 6 feet up."], ["Combat", "Ponzi failed a Con save on a 6, used inspiration, and still took necrotic damage halved by resistance; his cloak was ripped off and sucked into the box. Talon's Reduce (d12: 2 after a heroic reroll from 1) slowed it dramatically."], ["Combat", "Rune Willow drew her sword and severed all remaining tendrils with a Cirque du Soleil-style flourish; the box dropped, shut, and sucked the shadows back in. Ponzi took roughly 39+ necrotic damage total, and the box is still in his possession."]]}, {"t": 2832, "kind": "clue", "title": "A keyhole in a crag", "line": "The party circles the tower and finds no door; Rune Willow's nat 20 Arcana tunes out the ambient chaotic magic, catches a thread of deliberate magic in one stone, and reveals a hidden keyhole.", "facets": [["New lore", "Arcane towers have no doors as a first line of defense — entries are hidden behind touch-activated stones, illusory walls, or teleportation-only access."], ["Check", "Ponzi investigating the perimeter (d100: 59) was nearly hit by a frozen lightning bolt — Dex save 15, 7 lightning damage."]]}, {"t": 3605, "kind": "rule", "title": "The spell left you", "line": "Talon's Aura of Vitality freezes into the tower air, and the DM rules that spell slots are expended even when the spell freezes.", "facets": [["Quote", "\"The spell left you.\""], ["Character", "Rune Willow touched the frozen Aura of Vitality and felt a warm gentle touch — not a note or a chord but a complex chord with layers of harmonies: warmth, loneliness, love, the warmth Talon should have felt but didn't after being orphaned. \"From a note to a widespread chord.\""]]}, {"t": 4040, "kind": "rule", "title": "The counter nobody could see", "line": "The d100 aberrant energy accumulation mechanic is revealed during Nyx's lockpicking: every check in the field adds to a hidden counter, and every 50-point threshold costs 4d6.", "facets": [["Check", "Nyx passed the 150 and 200 thresholds simultaneously — an 86 damage save — and rolled 23 to succeed with proficiency plus Dex mod."]]}, {"t": 4756, "kind": "dread", "title": "Seventy-seven points of Disintegrate", "line": "Rune Willow's second Bless freezes and releases a 6th-level Disintegrate straight at Nyx, who fails his Dex save on a 3 and fails the heroic-inspiration reroll on another 3.", "facets": [["House ruling", "Heroic Inspiration can be transferred between party members — confirmed as a house rule this session. Rune Willow gave hers to Nyx, who rerolled 19+2 = 21 and succeeded."], ["House ruling", "Disintegrate is pass-or-fail: a successful save takes no damage, a failure takes it all, and reaching 0 HP turns the target to ash, requiring True Resurrection or Wish. The revealed damage was 77 force — it would have killed Nyx outright."], ["Combat", "The earlier freezes had already released two 5th-level Cone of Colds at the party — 13 cold to Rune Willow and Talon on nat 20s, 26 to Ponzi on a failed save. The Disintegrate missed and blasted a 30-foot hole in the tower wall; Nyx then picked the lock."], ["Character", "Genuine fear at the table: Rune Willow's cloak snapped over to protect Nyx and her bladesong knocked him out of the way. Nyx took a long moment reflecting afterward."]]}, {"t": 4989, "kind": "scene", "title": "Ground floor: dwarven glory painted over with madness", "line": "The foyer's walls carry ancient dwarven mosaics — kings on thrones with thousands bowing, a dwarf crushing a black dragon's head — overlaid with manic paint splatters of elemental catastrophe.", "facets": [["New lore", "The ancient dwarven kingdoms were glorious and militarily dominant, including slaying chromatic dragons, and were destroyed by elemental catastrophe. The mosaics are from the \"old world buried at the bottom of the sea, reborn in the New World.\""], ["New lore", "Chromatic dragons (black, red, blue, white) are corrupted/evil; metallic dragons (bronze, brass, silver, gold) are good."], ["Environment", "Some painted elements have become real — actual fire licking the mosaic edges, actual ice clinging to surfaces. Inside, arcane viscosity is controlled: released spells are directed by the caster."], ["Check", "Rune Willow found the \"start of the sentence\" in the runes of an 8-foot circular dais on a nat 20 Arcana and channelled magic into them — pastel light blue to white to purple to black and pink — activating an arcane elevator."]]}, {"t": 5449, "kind": "reveal", "title": "LADY SHAELRA", "line": "A name is painted manically across the mosaics at the nexus of the elemental rending: Lady Shaelra, spelled out S-H-A-E-L-R-A.", "facets": [["New lore", "An entity of immense power who wielded all four elements simultaneously, with slightly inhuman stretched proportions. Central to — or the cause of — the downfall of the ancient dwarven kingdoms."], ["Clue", "The name triggered a vague familiarity in Rune Willow's studies on a History 24 — something deep and obscure in her research, possibly connected to Vattenheim lore."], ["Unsolved", "Was she evil, or was she fighting something? The painted dwarven warriors could be fighting against her or for her — the source calls it ambiguous."]]}, {"t": 5865, "kind": "scene", "title": "Second floor: sixteen shrouded canvases and a pony called Pancho", "line": "A pitch-black room holds roughly sixteen massive canvases on heavy easels, all draped in black cloth.", "facets": [["Environment", "Circular room with squared corners, canvases up to 10×10 feet placed haphazardly, a shattered arcane orb on a metal pedestal in one corner, a door at the far end leading to stairs."], ["Magic", "Rune Willow's Detect Magic wand rolled a d12 of 4 — the spell froze and crept out, and a released spell conjured a gnome-sized phantom steed the party named \"Pancho\" (speed 100, lasts 8 hours)."], ["Environment", "The first canvas uncovered shows Lady Shaelra — beautiful but terrible, thin sharp points at elbows and shoulders, slightly too tall — wielding four elemental tendrils, surrounded by dwarven warriors, with a cloaked man carrying a lichen-wrapped staff standing behind her as her right hand."]]}, {"t": 6448, "kind": "dread", "title": "Wolfgang's face in her eyes", "line": "Ponzi looks into the painted Lady Shaelra's eyes and sees a flash — her face reflecting Wolfgang, the man who killed his wife Rose. He covers the painting immediately.", "facets": [["Check", "d100: nat 1 → 9."], ["Foreshadowing", "The note flags a possible thematic connection between Ponzi's personal vengeance and this ancient evil — her malice and death mirrored his."]]}, {"t": 6613, "kind": "combat", "title": "The Animated Rug of Smothering", "line": "Lifting the cloth off a canvas triggers a 20×20-foot animated rug that wraps around Rune Willow.", "facets": [["Combat", "Nyx grappled it free on Athletics 22 and snapped it off; Talon's Cloud of Daggers shredded the centre for 22 damage on double dice; the rug tried to snap around Nyx and his flame cloak recoiled it; Rune Willow bisected it with her sword and the threads unravelled."], ["Combat", "Victory with no significant damage taken."]]}, {"t": 7462, "kind": "item", "title": "An orb cracked from the inside", "line": "A shattered arcane orb sits on a metal pedestal, sundered from the inside out with mushrooms growing from the cracks; touching it produces a male scream of anguish and loss.", "facets": [["Item", "Two diamonds (100 gp each) and 61 gp worth of diamond dust recovered nearby. Rune Willow gave one diamond to Ponzi as a gesture of empathy."], ["Quote", "The sound was the sharp pain of losing the one thing you care about."], ["Unsolved", "What did it contain? The source suggests it may have held something of Vesh's — his grief, a soul fragment, or a bound entity."]]}, {"t": 7606, "kind": "reveal", "title": "The same signature as their first dungeon", "line": "Rune Willow confirms the orb's arcane signature exactly matches the arcane energy from the party's first dungeon — a direct link between Vesh and that location.", "facets": [["Clue", "The note calls this a major intelligence breakthrough: Vesh was present or active in the party's first dungeon."]]}, {"t": 7631, "kind": "reveal", "title": "The man with the lichen staff is Vesh", "line": "Across the painting series, Lady Shaelra's right-hand man grows more decrepit until, in the final canvas, he is cloaked in mushrooms — a lich, identified as Vesh, screaming and reaching for her amid her downfall.", "facets": [["New lore", "Vesh loved Lady Shaelra deeply. Her downfall destroyed him and he became a mushroom-cloaked druidic lich."], ["Environment", "The central and largest painting shows Shaelra in her downfall — burns from fingertips to elbows, frostbite on her throat, windburned cheeks, muddied cloak, arms outstretched as the sky erupts with all four elements and the dwarven mountain kingdoms are decimated behind her."]]}, {"t": 8469, "kind": "scene", "title": "Third floor: the diviner's dais", "line": "A double-height room whose central dais is covered in oracular arcane sigils built to peer into the future, with a kneeling dwarven skeleton at its centre, jaw agape in a silent scream and faintly still screaming.", "facets": [["Environment", "The paintings here are of Vesh, not Lady Shaelra — depicting him rising in a land of ruin rather than in the dwarven kingdoms."], ["Combat", "Blue flames alight on the skull, mushrooms animate out of the paintings, and mycanoids stand up."]]}, {"t": 8626, "kind": "lore", "title": "The prophecy that killed the diviner", "line": "The dwarven diviner foresaw Vesh's rise in a land of ruin, painted the warning on every wall, was driven mad by the knowledge and wailed himself to death — and the premonition is now manifesting.", "facets": [["New lore", "The tower was his. Mycanoids serve Vesh or manifest from his premonitions; the note flags Vesh as PRIMARY ANTAGONIST and the endgame threat."]]}, {"t": 8940, "kind": "boss", "title": "The Woe-Born Flame Skull rises", "line": "The diviner's skull bursts into being as a Woe-Born Flame Skull alongside two Mycanoid Radix, using fire rays, Gaze of Woe and lair actions that swap with the ensnared spells in the air.", "facets": [["Combat", "It opened with Fireball on Talon and Ponzi — both saved for 19 fire. Its lair actions wasted a Revivify in front of the party, then redirected Talon's frozen Guiding Bolt for 18 radiant on Nyx, then dropped fire Resistance on Nyx."], ["Combat", "Gaze of Woe: Rune Willow saved on a 21, then took 34 fire from two rays; Nyx failed on 13 and was frightened, took 20 fire from one ray, and retaliated with Hearth Fire Manifest for 6 that ignores resistance. The mycanoids' Frightening Spores caught Rune Willow."], ["Combat", "Rune Willow's Melf's Meteors froze into 5 Magic Missile darts — 3 at the skull, 2 at a mycanoid — with Bladesong up. Nyx hit for 16 with a delayed smite of 14 radiant. Talon's crossbow hit for 3 and he threw a healing potion to Rune Willow on Sleight of Hand 20."], ["Character", "Nyx offered to take a Warding Bond for Rune Willow during the fight."]]}, {"t": 9550, "kind": "magic", "title": "Beacon of Hope out of a frozen Guiding Bolt", "line": "Talon's Guiding Bolt freezes and releases Beacon of Hope onto himself, giving everyone within 30 feet advantage on Wisdom and death saves and maximum healing.", "facets": [["House ruling", "Max healing applies to all healing within 30 feet of the caster for the duration."], ["Combat", "Ponzi's Potion of Greater Healing maxed at 20 under it and put him back in the fight."]]}, {"t": 11789, "kind": "boss", "title": "An arrow through the eye socket", "line": "Ponzi disengages as a bonus action, moves for a clear shot, takes Vex advantage and sneak-attacks the Flame Skull through the eye socket for 21 — and it dies.", "facets": [["Character", "He slid on his knees across the stone floor and drew back. \"How do you want to do this?\""], ["House ruling", "Vex weapon property — advantage on the next attack against the same target after a hit — was ruled to apply for continuity."]]}, {"t": 11810, "kind": "travel", "title": "The tower comes down", "line": "Violent fungal growth immediately begins ripping the stonework apart and the party evacuates.", "facets": [["Combat", "Rune Willow's held Thunderstep teleported her and Nyx 90 feet down to the painting-room dais, and the mycanoids took 18 damage on failed Con saves."], ["Check", "Escape saves: Rune Willow nat 20 for a clean exit, Nyx 14 and barely made it, Talon made it on Pancho the pony. Ponzi flew out the top on summoned wings."], ["Environment", "Spores were released into the plains from the collapse — potential environmental and magical contamination."]]}, {"t": 12421, "kind": "scene", "title": "The Gray Tower is rubble", "line": "Every latent spell in the air detonates as the tower falls, explosions tearing up the earth around the fleeing party. The Gray Tower is now a mound of rubble, dust and spores.", "facets": [["Environment", "A landmark on the road to Vattenheim is gone, and with it the paintings, the mosaics, the orb and the prophetic sigils — some may be recoverable from the rubble, most is not."]]}, {"t": 12438, "kind": "social", "title": "\"It all started with 'guys, I have an idea'\"", "line": "Ponzi tallies up his session: electrocuted, frozen, ripped apart by shadow tendrils, set on fire, and nearly compressed into a ring box.", "facets": [["Character", "He took the most damage of anyone this session by far and needs healing resources before the next encounter."]]}], "threads": [{"u": "hi", "q": "Vesh's Rise: The diviner's prophecy is manifesting. Mycanoids are his heralds. He is connected to the party's first dungeon. He is the endgame.", "t": 8626}, {"u": "hi", "q": "Lady Shaelra's Identity: Who was she? Was she evil? What destroyed her? Her connection to Vesh and the dwarven kingdoms is central to the main plot.", "t": 5449}, {"u": "hi", "q": "The Shattered Orb: Contains (or contained) something significant — male scream of anguish, Vesh's arcane signature. Mushrooms growing from it. Left behind in the rubble.", "t": 7797}, {"u": "hi", "q": "Demon Ring Box: Still active, still dangerous, still in Ponzi's pocket.", "t": 1576}, {"u": "md", "q": "Wolfgang: Ponzi's personal quest. No current leads on his location.", "t": 4500}, {"u": "md", "q": "Second Tower: The party was heading to \"a llama by way of two towers.\" First tower destroyed. Second tower unknown.", "t": 89}, {"u": "md", "q": "Rune Willow's Shaelra Connection: Vague familiarity from studies — needs follow-up research.", "t": 5656}, {"u": "md", "q": "Nyx/Kayon's Changeling Identity: True name revealed last session; implications for his past and future not yet explored.", "t": 60}], "next": ["Take a long rest immediately — party is critically depleted", "Search the Gray Tower rubble for the shattered orb and mosaic fragments", "Research Lady Shaelra — find a sage, library, or archive in the next settlement", "Safely contain or destroy the Demon Ring Box", "Acquire proper containers for arcane samples (necrotic rock, any future finds)", "Heal Ponzi to full before the next encounter", "Consolidate party knowledge about Vesh and plan a response", "Approach the second tower with extreme caution — scout before engaging"], "entities": [{"name": "Vesh", "kind": "npc", "note": "Originally a cloaked man with a lichen-wrapped staff, Lady Shaelra's right-hand man; became a mushroom-cloaked druidic lich after her downfall. His arcane signature matches the party's first dungeon. Flagged PRIMARY ANTAGONIST and endgame threat.", "t": 7631}, {"name": "Lady Shaelra (S-H-A-E-L-R-A)", "kind": "npc", "note": "Tall with slightly inhuman stretched proportions, sharp points at elbows and shoulders, beautiful but terrible. Wielded all four elements simultaneously. Depicted in her downfall — burned, frostbitten, windburned. Alignment, origin and true role unknown.", "t": 5449}, {"name": "The Dwarven Diviner", "kind": "npc", "note": "Dwarven skeleton kneeling in disheveled robes, jaw agape, faintly screaming even in death. Foresaw Vesh's rise, painted prophetic warnings through his own tower, and wailed himself to death. Reanimated as the Woe-Born Flame Skull.", "t": 8537}, {"name": "Wolfgang", "kind": "npc", "note": "Ran a wolf gang. Killed Ponzi's wife Rose accidentally while hunting Ponzi, after Ponzi and Rose tried to leave him. Location unknown; Ponzi seeks vengeance.", "t": 4500}, {"name": "Rose", "kind": "npc", "note": "Ponzi's wife of one year, killed by Wolfgang's wolf gang. Ponzi looks for her every night and cannot find her.", "t": 4500}, {"name": "The Wound", "kind": "npc", "note": "Referenced only in the recap — retrieved a reborn staff, made breakfast, facilitated the backstory sharing. The note says not present this session, or not named as an active party member.", "t": 19}, {"name": "The Gray Tower", "kind": "place", "note": "White tower seen through a murky gray film, doorless, under 100 feet across, ringed by frozen spells and arcane viscosity. Ground floor mosaic foyer, second floor painting gallery, third floor diviner's chamber. Now rubble, dust and spores.", "t": 217}, {"name": "Vattenheim", "kind": "place", "note": "The party's destination, reached by way of two towers. The Gray Tower was the first waypoint; the second tower is still ahead.", "t": 89}, {"name": "Woe-Born Flame Skull", "kind": "creature", "note": "The reanimated diviner: flying, fire rays, Gaze of Woe, and lair actions that swap with the ensnared spells in the air. Killed by Ponzi's sneak attack through the eye socket for 21.", "t": 8940}, {"name": "Mycanoid Radix", "kind": "creature", "note": "Two spawned from the prophetic paintings alongside the Flame Skull. Slam attack and Frightening Spores forcing a Con save or frightened.", "t": 8940}, {"name": "Animated Rug of Smothering", "kind": "creature", "note": "A 20×20-foot black canvas drape in the painting gallery, triggered when Rune Willow lifted a cloth. Defeated by Cloud of Daggers and blade work.", "t": 6613}, {"name": "Ancient Dwarven Kingdoms", "kind": "faction", "note": "Once dominant militarily, politically and culturally — kings on thrones with thousands bowing, dragon-slayers. Destroyed by elemental catastrophe possibly caused by Lady Shaelra. From the old world buried at the bottom of the sea, reborn in the New World.", "t": 5316}, {"name": "Wolfgang's Wolf Gang", "kind": "faction", "note": "Criminal/mercenary faction. Killed Rose. Ponzi's personal enemy.", "t": 4500}, {"name": "Demon Ring Box", "kind": "item", "note": "Ponzi's trap item: black shadow tendrils, necrotic damage, attempts to compress targets into the box. Origin unknown, still active and dangerous, still in his possession.", "t": 1576}, {"name": "Shattered Arcane Orb", "kind": "item", "note": "Cracked from the inside out with mushrooms growing from the cracks; touching it produced a male scream of anguish. Arcane signature matches the party's first dungeon. Left behind in the rubble.", "t": 7462}, {"name": "Phantom Steed \"Pancho\"", "kind": "item", "note": "Gnome-sized pony conjured accidentally from a released spell during Rune Willow's Detect Magic. Speed 100, lasts 8 hours. Talon rode it out of the collapsing tower.", "t": 6174}, {"name": "Necrotic Rock Sample", "kind": "item", "note": "A gray rock struck by a released necrotic spell outside the tower, black and purple energy imbued into its veins. Wrapped in a handkerchief by Rune Willow; needs proper containment.", "t": 1435}], "gaps": ["The Wolfgang and Rose backstory entries are stamped 01:15:00 in four places (NPC index, faction, quest, unresolved threads). The transcript places that conversation at 00:01:15 — roughly 75 seconds in, during the opening recap — so 01:15:00 looks like a shifted mis-stamp of 00:01:15. Every stamp is preserved byte-for-byte as the source has it; none of these are used as beats. The MAJOR EVENTS spine itself is strictly monotonic and semantically correct, so beats are sorted ascending.", "Proper-noun variance preserved rather than resolved: Nyx / Kayon; Talon / Tanner; mycanoids / myconoids / Mycanoid Radix; \"a llama by way of two towers\" is almost certainly a transcription of a place name (compare Alama/Olama in later sessions); \"Nyx (met Scar)\" in the residual block does not match anything in the V3 layers.", "\"The Wound\" is treated as a character in the recap — it retrieved a reborn staff and made breakfast — but the NPC index says it was not present this session or not named as an active party member. This reads like a transcription artifact for someone's name, unresolved in the source.", "The note carries a residual generic \"Project Sync / Status Update Summary\" block from an earlier template run, rendering the session as a corporate expedition report with SOPs and action items.", "Internal contradiction on Ponzi's ring-box damage: MAJOR EVENTS says the failed Con save cost 17 necrotic, the COMBAT BREAKDOWN says 22 necrotic then 17 after inspiration then halved to 8 by resistance, and both give a total of \"~39+.\" The arithmetic is not reconciled in the source.", "The third-floor description attributes the new hole in the ceiling to \"Talon's fireball from below,\" but no such fireball appears anywhere in MAJOR EVENTS or the combat breakdown; the Fireball described is the Flame Skull's."], "timecodesReliable": true, "iso": "2026-01-19", "pretty": "19 Jan 2026", "audio": false, "legendary": false, "n": 4}, {"slug": "phantasma-night-hag-dream", "title": "Phantasma Spell Creates Ten-Foot Cube Barrier Effect", "date": "12/31/2025 20:14", "runtime": "2h 45min 29s", "nottaId": "dbd89da9-ed6a-459d-80aa-538fe6b6052d", "url": "https://app.notta.ai/7366972874555052032/dashboard/dbd89da9-ed6a-459d-80aa-538fe6b6052d", "template": "D&D Session Noters: V3", "hasTimecodes": true, "durationSec": 9929, "subtitle": "The Night Hag in Talon's Memory", "logline": "Trapped inside Talon's worst memory, the party fights a Night Hag from both sides of a dream at once.", "recap": "The warmth of childhood memories turned cold as stone when the earth itself rose against them. In the sanctuary of Talon's most precious recollections — the smell of fresh bread, the comfort of home — an ancient evil had taken root. The Night Hag fed on trauma, weaving nightmares from the bard's deepest pain: the day he lost everything. But even in the twisted realm of dreams, bonds forged in waking light held strong. In the end it took both dream and reality, both blade and magic, both memory and hope to pierce the heart of darkness. The Hag fell, but the scars she opened may never fully heal.", "dm": "Jake", "party": ["Talon — Bard", "Nyx — Paladin", "Runewillow — Wizard / Bladesinger"], "opens": "Talon's childhood home, in a dream", "closes": "Waking, the Hag dead on both sides", "cards": {"changed": {"headline": "The Night Hag is dead", "detail": "Killed on both sides at once — Talon inside the dream, Ponzi's blade outside it.", "t": 8538}, "learned": {"headline": "Damage in a dream is real damage", "detail": "The dream fight and the waking fight were the same fight. What lands in one lands in the other.", "t": 8692}, "who": {"headline": "Talon", "detail": "The session was built out of his worst memory — his parents' cave-in, and his fear of never dying.", "t": 2956}, "cost": {"headline": "A memory picked open", "detail": "Talon rolled 23 looking for someone to blame and found only ordinary wear. There was no sabotage. Specter life drain also cut the party's maximum HP.", "t": 3760}, "hanging": {"headline": "Why Talon?", "detail": "Nothing explains why she chose his memory specifically, or what his draconic studies have to do with it.", "t": 3963}}, "beats": [{"t": 0, "kind": "scene", "title": "The house that still smells of bread", "line": "The party steps into Talon's childhood home — warmth, a wood stove, the memory of baking.", "facets": [["Environment", "Stone construction with a wooden door"], ["Environment", "Contains the wood stove where bread was baked"], ["Environment", "Most details are shallow, like a painted memory"]]}, {"t": 30, "kind": "combat", "title": "The door comes apart", "line": "An Earth Elemental bursts through the door. Combat begins inside the memory.", "facets": [["Combat", "Enemies: 1 Earth Elemental"]]}, {"t": 47, "kind": "magic", "title": "Talon conjures an angel that isn't there", "line": "Phantasmic Force paints an angelic illusion. The elemental believes it, and is terrified.", "facets": [["Spell", "Phantasmic Force — Talon"]]}, {"t": 1373, "kind": "combat", "title": "Thunder is the answer", "line": "The elemental proves vulnerable to thunder — double damage.", "facets": [["Mechanic", "Vulnerability: thunder damage, doubled"], ["Spell", "Thunderous Smite — Nyx · Shatter — Talon"]]}, {"t": 2334, "kind": "combat", "title": "Thunderclap, and the rocks scatter", "line": "Talon finishes it. Stone scatters across the floor of his childhood.", "facets": [["Finishing move", "Thunderclap — Talon"]]}, {"t": 2680, "kind": "dread", "title": "The bread has turned to rock", "line": "On the short rest, Talon finds the bread has become jagged stone, streaked with dried blood.", "facets": [["Environment", "The memory is starting to rot from inside"]]}, {"t": 2956, "kind": "lore", "title": "What happened to Talon's parents", "line": "He lost them both in a mine cave-in when he was a child.", "facets": [["New lore", "Parents were miners, lost in a cave-in"], ["Character", "Deep exploration of childhood trauma and parental loss"]]}, {"t": 3075, "kind": "item", "title": "Nyx binds a coin to Talon", "line": "A Driftwood Kin coin, enchanted with Warding Bond. One for Talon, one for Nyx.", "facets": [["Item", "+1 AC and resistance to all damage"], ["Item", "Glows with a subtle light when active"], ["Faction", "Driftwood Kin coins can carry protective magic"]]}, {"t": 3284, "kind": "clue", "title": "Only four things in this memory are real", "line": "The post, the oven, the door, the mining equipment. Everything else is painted.", "facets": [["Clue", "The memory has exactly four sharp details"]]}, {"t": 3527, "kind": "lore", "title": "The tools that stayed home that day", "line": "The broken mining equipment in the corner didn't go down the shaft with them.", "facets": [["New lore", "The day of loss involved equipment left behind"]]}, {"t": 3760, "kind": "clue", "title": "Talon rolls 23, and finds nothing", "line": "He wants sabotage. He wants a reason. The tools show only ordinary wear.", "facets": [["Check", "Talon: 23 Investigation · Runewillow: 6 Perception"], ["New lore", "No sabotage. The tragedy was senseless."], ["Character", "Obsessive investigation seeking meaning in senseless tragedy"]]}, {"t": 3785, "kind": "dread", "title": "Black tendrils take the others", "line": "Runewillow and Nyx are restrained as the vision comes apart.", "facets": [["Mechanic", "Strength saves against restraining tendrils"]]}, {"t": 3938, "kind": "scene", "title": "The house breaks into ethereal space", "line": "Black and pastel orange. No true walls. Floating platforms of broken home.", "facets": [["Environment", "Gaps of ethereal space where walls should be"]]}, {"t": 3963, "kind": "boss", "title": "The Night Hag reveals herself", "line": "Fingers two knuckles too long. A drooping jaw. Eyes gone. She has been here the whole time.", "facets": [["Major NPC", "Gangly, extra-long fingers with two extra knuckles"], ["Major NPC", "Drooping jaw, gone eyes, gnarled"], ["New lore", "Night Hags can trap victims inside traumatic memories"], ["New lore", "She feeds on traumatic memory and nightmare"]]}, {"t": 4554, "kind": "reveal", "title": "A dagger comes through her shoulder from nowhere", "line": "Ponzi's blade. He and Tom are fighting her body in the waking world, at the same moment.", "facets": [["Ally", "Ponzi is fighting the Hag's physical form"], ["New lore", "The dream and the waking fight are the same fight"]]}, {"t": 4696, "kind": "combat", "title": "Initiative", "line": "Runewillow 21, Nyx 15, Talon 14. Against the Hag, two Specters and a Wraith.", "facets": [["Combat", "Specters are tethered to the Hag and share damage"], ["Combat", "Specter life drain reduces maximum HP"]]}, {"t": 5896, "kind": "combat", "title": "Phantasmal Killer", "line": "She answers illusion with illusion — and a fourth-level Magic Missile.", "facets": [["Mechanic", "Multiple Wisdom saves against Phantasmal Killer"]]}, {"t": 6221, "kind": "lore", "title": "What Talon is actually afraid of", "line": "Not death. Never-ending life — a bardic lich, hair replaced by dragon scales, decrepit and immortal.", "facets": [["New lore", "Greatest fear: immortality and draconic corruption"], ["Foreshadowing", "A vision of his own corrupted future"], ["Character", "Confrontation with his greatest fear"]]}, {"t": 6527, "kind": "rule", "title": "Ruling: paladin fire burns the undead anyway", "line": "Jake rules that paladin fire ignores undead resistance.", "facets": [["House ruling", "Divine Smite deals extra damage against fiends"]]}, {"t": 8538, "kind": "boss", "title": "True Strike, from inside the dream", "line": "Talon delivers the killing blow as Ponzi's blade lands from the other side of the world.", "facets": [["Finishing move", "True Strike — Talon, coordinated with Ponzi"], ["Character", "Moment of heroism delivering the killing blow"]]}, {"t": 8692, "kind": "scene", "title": "They wake", "line": "Ponzi and Tom stand over her body, bloodied and victorious. It's over. The scars aren't.", "facets": [["World change", "Night Hag eliminated from the local area"], ["New lore", "Damage done in a dream manifests in reality"]]}], "threads": [{"u": "hi", "q": "Why did the Night Hag target Talon's memory specifically?", "t": 3963}, {"u": "hi", "q": "What does Talon's fear of draconic corruption actually mean?", "t": 6221}, {"u": "md", "q": "How common are Night Hag attacks in this region?", "t": null}, {"u": "md", "q": "Are there other supernatural things hunting the party?", "t": null}, {"u": "lo", "q": "What really happened to Talon's parents?", "t": 3760}], "next": ["Debrief with Ponzi and Tom about the Hag", "Find out why the party was targeted", "Deal with the lingering life-drain damage", "Look into Talon's draconic studies", "Research Night Hag covens"], "entities": [{"name": "The Night Hag", "kind": "creature", "note": "Fed on traumatic memory. Killed this session.", "t": 3963}, {"name": "Ponzi", "kind": "pc", "note": "Fought the Hag's physical form in the waking world.", "t": 4554, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Tom", "kind": "npc", "note": "Present for the physical fight; bloodied but victorious.", "t": 8692}, {"name": "Driftwood Kin", "kind": "faction", "note": "Their coins can be enchanted with Warding Bond.", "t": 3075}, {"name": "Driftwood Kin coin", "kind": "item", "note": "+1 AC and resistance to all damage. One with Talon, one with Nyx.", "t": 3075}, {"name": "Talon", "kind": "pc", "note": "Bard. Lost his parents in a mine cave-in. Fears immortality.", "t": 2956, "reveal": "Talon's real name is Tanner."}, {"name": "Nyx", "kind": "pc", "note": "Paladin. Protective; bound the coins.", "t": 3075, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Rune Willow", "kind": "pc", "note": "Wizard / Bladesinger.", "t": null, "alias": "Runewillow"}], "gaps": [], "iso": "2025-12-31", "pretty": "31 Dec 2025", "audio": false, "legendary": false, "timecodesReliable": true, "n": 3}, {"slug": "dwk-book-2-chapter-1", "title": "DWK Book 2 Chapter 1", "date": "12/07/2025 00:39", "runtime": "3h 49min 5s", "nottaId": "54297431-92ac-4ed3-8049-f996fc7e024d", "url": "https://app.notta.ai/7366972874555052032/dashboard/54297431-92ac-4ed3-8049-f996fc7e024d", "template": "Auto", "hasTimecodes": true, "durationSec": 13745, "subtitle": "A new keep, a tunnel under Eden Moor", "logline": "The Kin claim Nastra Antheon, then follow a half-orc's tip into a staged mine and free chained prisoners as Callestus's tunnels beneath Eden Moor detonate.", "recap": "The echoes of battle fade as the Driftwood Kin stand victorious amidst the chains of the fallen. What began as a simple investigation into disappearances has revealed a sinister plot beneath Eden Moor—tunnels lined with embersap barrels and prisoners forced to work by Callestus and the Court of Blades. With their friend Tom freed and prisoners escaping, the rumbling of explosions signals the collapse of this dark enterprise. But as the tunnels begin to crumble, the Kin face a desperate race against time, carrying with them questions of what Callestus truly intended and why Vesh's fungal tendrils reach even here. In their newly established sanctuary at Nastra Antheon, a foundation has been laid for the Driftwood Kin's growing legend—but first, they must survive the cave-in that threatens to bury the truth forever.", "dm": "Jake", "party": ["Ponzi", "Talon", "Rune Willow", "Nyx (absent this session)", "Vera (guest character)"], "opens": "The Driftwood Kin settling into their new keep at Nastra Antheon after Scar's rest", "closes": "The party fighting to escape collapsing tunnels beneath Eden Moor after freeing prisoners", "cards": {"changed": {"headline": "A keep claimed above ground, an operation broken open beneath it", "detail": "Nastra Antheon — the greenhouse and tower that belonged to Vayon — is now the Driftwood Kin's base, and by the end of the night the Court of Blades' underground operation beneath Eden Moor was disrupted, an unknown number of prisoners freed from forced labor, and Tom freed from captivity.", "t": 13351}, "learned": {"headline": "The mine is a front for a tunnel running under Eden Moor", "detail": "The mine outside the city has no actual mining in it; it is the mouth of a straight, lantern-lit tunnel extending about 2.5 miles beneath Eden Moor, where the Court of Blades and Callestus hold prisoners setting barrels of embersap into fissures in the stone.", "t": 6290}, "who": {"headline": "Vera, the half-orc who brought the job to the door", "detail": "Vera came to the keep because of the Kin's reputation from the trials at Giovanni's Tavern, told them miners were vanishing in Eden Moor and that she had found a suspicious mine, and then fought through the tunnels with them — driven by a personal vendetta against Callestus, who \"stole all the hope\" she had built for herself.", "t": 1515}, "cost": {"headline": "Radiant damage, a spent bluff, and a marked enemy", "detail": "A priest's Spirit Guardians dealt radiant damage to the party; they spent the Blood Father's name and letters on a forged entry document; and having disrupted the operation they may now face retaliation from Callestus forces, with the tunnels collapsing around them.", "t": 9907}, "hanging": {"headline": "Why line the fissures with embersap and ward the opposite wall?", "detail": "Barrels of embersap sit around fissures in the south wall surrounded by arcane symbols to ignite them, while the north wall carries inscriptions of protective magic — and nobody knows what Callestus meant to do with a charge laid that carefully beneath a living city.", "t": 6800}}, "beats": [{"t": 156, "kind": "scene", "title": "The Kin Settle Into Nastra Antheon", "line": "The party spent several days establishing their new keep at Nastra Antheon, the greenhouse and tower previously belonging to Vayon.", "facets": [["New lore", "The greenhouse at Nastra Antheon was a sanctuary of Vayon, now cleansed of Vesh's influence."], ["Environment", "A stained glass greenhouse with a stone tower attached, and exposed gardens at the base of the tower."], ["World state", "Nastra Antheon transformed from abandoned sanctuary to Driftwood Kin base."]]}, {"t": 299, "kind": "item", "title": "The Tower Gives Up Its Hoard", "line": "Exploring the tower turned up a bag of sundrops, a javelin of lightning, a stash of gold and gems, and a lantern of revealing.", "facets": [["New lore", "The tower has three levels above a basement level, somewhat in ruins but repairable."], ["Item", "Bag of sundrops: five golden marble-like orbs that glow softly when held; as an action one can be thrown to create a dazzling pillar of sunlight, 5-foot radius and 40 feet high, until the start of the next turn. Currently held by Ponzi."], ["Item", "Javelin of lightning: hefty, requires good strength to throw, turns into a blazing streak of lightning and reappears in hand, but the lightning property can only be used once per dawn. Currently held by Rune Willow."], ["Item", "Lantern of revealing: burns six hours on one pint of oil, sheds bright light in a 30-foot radius and dim light 30 feet further, makes invisible creatures and objects visible in its bright light, and its hood can be lowered to dim light in a 5-foot radius. Currently held by Rune Willow."], ["Item", "A stash hidden in a hollow stone brick held several hundred gold worth of coins and gems, now in party possession."]]}, {"t": 746, "kind": "lore", "title": "Vayon's Dryads Return to the Garden", "line": "Floral dryads blessed by Vayon returned to tend the gardens and act as protectors of the keep.", "facets": [["New lore", "The dryads serve as protectors of Nastra Antheon."], ["Character", "Rune Willow buried her burned staff of flowers in the greenhouse next to Scar."]]}, {"t": 844, "kind": "scene", "title": "Making the Tower Theirs", "line": "The tower was in disrepair but is being fixed by the party, and each member claimed a space in it.", "facets": [["House ruling", "Talon used Mending to repair small items around the tower (up to 1 foot)."], ["Environment", "Each level is circular, about 50 feet across, divided into 2-3 rooms each."], ["Decision", "Common area on the first floor, Nyx and Ponzi on the second floor, Talon on the top floor."], ["Character", "The group organizing their living spaces showed growing comfort with each other."]]}, {"t": 1379, "kind": "magic", "title": "Homunculi Paint the Walls", "line": "Rune Willow summoned homunculi to paint the walls of her space with flowers, sunbursts, and night sky.", "facets": [["Character", "She read her \"weird nonsense books\" to Scar in the greenhouse."]]}, {"t": 1515, "kind": "social", "title": "A Half-Orc at the Gate", "line": "A half-orc woman named Vera approached the keep seeking the Driftwood Kin's help.", "facets": [["Major NPC", "Vera / Virag Zik, full name Suresnya Verag — dark hair, green skin, small tusks, in beat-up but solid armor."]]}, {"t": 1913, "kind": "scene", "title": "Poisoner's Kit and a Promise to Scar", "line": "Ponzi set up his poisoner's equipment in his room on the second floor, and he and Nyx decided to share a floor, honoring their promise to Scar to grow closer.", "facets": [["Check", "Rune Willow summoned her homunculi using ground gem powder."]]}, {"t": 2122, "kind": "plan", "title": "Vera's Ask: People Are Vanishing in Eden Moor", "line": "Vera explained people were disappearing in Eden Moor, particularly miners, and that she had discovered a suspicious mine outside the city.", "facets": [["Major NPC", "Vera sought the party out based on their reputation from the trials at Giovanni's Tavern."], ["New lore", "Callestus currently rules Eden Moor alongside Tostrain."]]}, {"t": 2808, "kind": "travel", "title": "East to the Mine", "line": "The party traveled to the mine — east and slightly south of Eden Moor, about a day and a half from Nastra Antheon — camping one night in the plains.", "facets": [["Check", "Talon rolled a Survival check (23) to navigate safely through the plains."]]}, {"t": 2996, "kind": "social", "title": "The Hope Callestus Stole", "line": "At camp Vera revealed her hatred for Callestus, who \"stole all the hope\" she had built for herself.", "facets": [["Plot hook", "Vera has a personal vendetta against Callestus."], ["Character", "She showed unusual avoidance of fire during camp, which is unusual for orcs."], ["Character", "The party was initially suspicious of Vera but gradually accepted her help."]]}, {"t": 3429, "kind": "lore", "title": "Watch Talk on the Quiet Plains", "line": "The plains were previously known for dangers from the Howjaws and wolves, but are now quiet.", "facets": [["Check", "Ponzi rolled a History check to assess the Howjaws situation."], ["Foreshadowing", "Ponzi theorizes the Howjaws have scattered after losing their central figure, but could potentially regroup."], ["Character", "Vera carries a large round buckler and a heavy flail with a crackly-looking, cracked ball at the end; her leather pack is scorched, as if recovered from a fire."], ["Character", "Talon played dulcimer during watch and shared his history of traveling through Caberos, Tostrain, and Va."], ["New lore", "Callestus is one of five nations mentioned — the others being Tostrain, Va, Caberos and Escana."], ["Character", "Vera is a highly skilled fighter, particularly with her complicated flail weapon."]]}, {"t": 4687, "kind": "clue", "title": "A Mine That Isn't Mining", "line": "They discovered the mine appeared staged, with several dozen tents, wooden crates and carts outside but no actual mining activity.", "facets": [["Environment", "The entrance sits at the edge of woods where there's a level change in topography."], ["Environment", "Two guards posted outside the entrance."], ["Clue", "Callestus is trying to hide the operation beneath Eden Moor."]]}, {"t": 5132, "kind": "clue", "title": "Zone of Truth at the Door", "line": "Talon cast Zone of Truth on the guards, who failed their saves and revealed that people had been going in for weeks but not coming out.", "facets": [["New lore", "The Court of Blades is involved in the operation beneath Eden Moor."]]}, {"t": 5413, "kind": "social", "title": "Forging the Blood Father", "line": "Ponzi used his criminal background to forge a document claiming they were sent by the Blood Father, and the party bluffed its way inside.", "facets": [["Item", "The party still holds letters from the Blood Father, saved from previous encounters, which were used to forge the document."], ["New lore", "The Blood Father is connected to the Howjaws."], ["Check", "Deception/Intimidation checks to bluff their way into the mine — Ponzi 20, Vera 25, Talon 14."]]}, {"t": 6083, "kind": "travel", "title": "Past the False Ending", "line": "The initial cavern held floating chunks of stone and scaffolding, and a false ending with a tight switchback opened onto the true tunnels — straight, dark, lit by sparse oil lanterns, wide enough for carts and extending about 2.5 miles underground toward Eden Moor.", "facets": [["New lore", "The mine outside Eden Moor is a front for a tunnel system that leads beneath the city."], ["Faction", "The Court of Blades is the guard of Eden Moor and its guards wear its emblem."], ["Clue", "The Court of Blades is connected to the disappearances of miners and stonemasons."]]}, {"t": 6374, "kind": "clue", "title": "The Fungus That Waits and Watches", "line": "Fungal growth on the walls increased as they progressed deeper, and Rune Willow's Arcana check (21) identified it as similar to Vesh's spores.", "facets": [["Foreshadowing", "The growth is \"less dominating, more like waiting and watching\" than Vesh's spores."]]}, {"t": 6800, "kind": "dread", "title": "Alcoves, Chains, and Barrels of Embersap", "line": "The tunnel opened into a vertical cavern like a crack beneath the surface, with alcoves spaced 75-200 feet apart where prisoners were chained to the walls and forced to set barrels of embersap into the stone.", "facets": [["Unsolved", "Barrels of embersap are placed around fissures in the south wall, surrounded by arcane symbols to ignite them."], ["Unsolved", "The north wall has inscriptions of protective magic."], ["Major NPC", "Tycerus is identified as a \"Barrow Captain of Callestus\"."], ["Major NPC", "Josh, a guard at the mine entrance loyal to the Court of Blades, was deceived by the party."]]}, {"t": 7460, "kind": "reveal", "title": "Tom in Chains", "line": "They discovered their friend Tom, the dragonborn guard from Eden Moor, stripped of armor, chained and forced to work — and combat broke out moments later when the guards realized they weren't actually sent by the Blood Father.", "facets": [["Major NPC", "Tom is a blue-scaled dragonborn guard of the Court of Blades and guard prefect of the Low Tide district in Eden Moor, an ally who previously helped the party in Eden Moor."], ["House ruling", "Clarification on Jack of All Trades: add half proficiency bonus (rounded down) to ability checks that don't use proficiency."]]}, {"t": 8518, "kind": "combat", "title": "Initiative in the Dark", "line": "Initiative ran Ponzi (23), guards, Talon (18), priests, Vera (15), Tycerus, Tom, Rune Willow, and Ponzi opened by using Necrotic Shroud and attempting to howl like a werewolf to intimidate the guards.", "facets": [["Combat", "Multiple guards fought with greatswords."], ["Combat", "Talon cast Shatter on approaching guards, dealing 18 damage to both."]]}, {"t": 9648, "kind": "boss", "title": "The Barrow Captain and His Priests", "line": "Tycerus — an elf with pale skin, sunken eyes and cheeks raised by thick scars — fought with a mace and chain whip he could animate, while priests answered with radiant magic.", "facets": [["Combat", "A priest cast Spirit Guardians, dealing radiant damage to the party."], ["New lore", "The operation involves priests who use radiant magic."], ["Character", "The priests wear white robes."]]}, {"t": 10108, "kind": "scene", "title": "Tom Breaks His Chains", "line": "Tom broke free of his chains and began freeing other prisoners, while Rune Willow's Cacophonic Shield deafened one enemy and disrupted a priest's concentration.", "facets": [["House ruling", "Cacophonic Shield required Constitution saves and deafened a failed save."]]}, {"t": 10976, "kind": "combat", "title": "Grovel and Thunder", "line": "Talon used Command to force enemies to grovel, and Vera used her flail to deal massive damage and cast Thunder Wave.", "facets": [["House ruling", "Command required Wisdom saves and forced enemies to grovel."], ["Combat", "Vera used Battle Master maneuvers including Distracting Strike."], ["House ruling", "Ruling on spell casting: only one spell slot per turn, but cantrips don't count as spell slots."]]}, {"t": 13410, "kind": "boss", "title": "Frostbite Ends the Barrow Captain", "line": "Rune Willow killed Tycerus with Frostbite, and the party defeated the guards and priests.", "facets": [["Combat", "Ponzi used Wails of the Grave to damage multiple enemies."], ["World state", "An unknown number of prisoners have been freed from forced labor, and freeing them will likely spread the Kin's reputation."]]}, {"t": 13730, "kind": "dread", "title": "\"Cave It In\"", "line": "As they freed the prisoners they heard Tycerus's order to \"cave it in,\" and explosions began as the embersap barrels were detonated.", "facets": [["Threat", "The immediate threat is escaping the tunnels as they collapse from embersap explosions."], ["World state", "Tunnels beneath the city are collapsing, potentially affecting the city above."], ["Threat", "Having disrupted their operation, the party may face retaliation from Callestus forces."]]}], "threads": [{"u": "hi", "q": "Purpose of Embersap Barrels: Why are barrels of embersap being placed around fissures in the stone beneath Eden Moor?", "t": 6800}, {"u": "hi", "q": "Fungal Growth: What is the significance of the fungal growth in the tunnels that resembles Vesh's spores but seems \"less dominating\"?", "t": 6426}, {"u": "hi", "q": "Callestus Operations: What other operations does Callestus have in Eden Moor and why are they capturing miners and stonemasons?", "t": 6108}, {"u": "md", "q": "Protective Inscriptions: What is the purpose of the protective inscriptions on the north wall of the tunnels?", "t": 6905}, {"u": "md", "q": "Howjaws Remnants: What happened to the remaining Howjaws after their leader was defeated?", "t": 3600}, {"u": "lo", "q": "Vera's Vendetta: What specifically did Callestus do to Vera that caused her hatred?", "t": 2996}, {"u": "lo", "q": "Rune Willow's Staff: What will happen to Rune Willow's burned staff of flowers that she buried in the greenhouse?", "t": 799}], "next": ["Escape the collapsing tunnels with as many prisoners as possible", "Ensure Tom's safety and learn what he knows about the operation", "Investigate the purpose of the embersap barrels and protective inscriptions", "Determine the connection between the Court of Blades, Callestus, and the underground operation", "Return to Eden Moor to follow up on the disappearances and potentially warn citizens", "Consider the implications of Vesh's fungal presence in the tunnels", "Return to Nastra Antheon to secure their base and plan next steps"], "entities": [{"name": "Ponzi", "kind": "pc", "note": "Set up his poisoner's equipment on the second floor, forged the Blood Father documents from his criminal background, carries the bag of sundrops, and used Necrotic Shroud and Wails of the Grave in combat.", "t": 5413, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Talon", "kind": "pc", "note": "Repaired the tower with Mending, played dulcimer on watch, cast Zone of Truth on the guards, and used Shatter and Command in combat.", "t": 5132, "reveal": "Talon's real name is Tanner."}, {"name": "Rune Willow", "kind": "pc", "note": "Summoned homunculi with ground gem powder, buried her burned staff next to Scar, identified the tunnel fungus, and killed Tycerus with Frostbite.", "t": 13410}, {"name": "Nyx", "kind": "pc", "note": "Absent this session; shares the tower's second floor with Ponzi, honoring their promise to Scar to grow closer.", "t": 1913, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Vera", "kind": "npc", "note": "Also given as Virag Zik, full name Suresnya Verag. Half-orc with dark hair, green skin and small tusks, listed in the party roster as a guest character and in the NPC index as a temporary ally seeking the party's help; fights with a large round buckler and heavy flail.", "t": 1515}, {"name": "Tom", "kind": "npc", "note": "Blue-scaled dragonborn guard of the Court of Blades and guard prefect of the Low Tide district in Eden Moor; found stripped of armor and chained in the mine, broke free and helped free other prisoners. Ally to the party.", "t": 7460}, {"name": "Tycerus", "kind": "npc", "note": "Elf with pale skin, sunken eyes and cheeks raised by thick scars; Barrow Captain of Callestus, leader of the operation beneath Eden Moor. Used a mace and chain whip he could animate, and ordered the tunnels collapsed when defeated.", "t": 6645}, {"name": "Josh", "kind": "npc", "note": "Guard at the mine entrance, loyal to the Court of Blades; deceived by the party.", "t": 6623}, {"name": "Priests", "kind": "npc", "note": "Multiple priests working in the tunnels, wearing white robes and casting radiant magic including Spirit Guardians.", "t": 9881}, {"name": "Scar", "kind": "pc", "note": "Referenced only: the session opens after Scar's rest, Rune Willow buried her burned staff next to Scar in the greenhouse and read her books there, and Ponzi and Nyx honored a promise to Scar to grow closer.", "t": 799}, {"name": "Vayon", "kind": "npc", "note": "The greenhouse and tower at Nastra Antheon previously belonged to Vayon; the greenhouse was a sanctuary of Vayon and floral dryads blessed by Vayon returned to it.", "t": 120}, {"name": "Vesh", "kind": "npc", "note": "The greenhouse has been cleansed of Vesh's influence, but the tunnels beneath Eden Moor contain fungal growth similar to Vesh's spores.", "t": 120}, {"name": "Nastra Antheon", "kind": "place", "note": "The Driftwood Kin's new keep: a stained glass greenhouse with a stone tower attached, the tower having a basement and three circular levels about 50 feet across, in disrepair but being fixed.", "t": 156}, {"name": "Eden Moor", "kind": "place", "note": "City where miners are disappearing, currently ruled by Callestus alongside Tostrain, with tunnels running roughly 2.5 miles beneath it.", "t": 2122}, {"name": "Mine Outside Eden Moor", "kind": "place", "note": "Located east and slightly south of Eden Moor, about a day and a half from Nastra Antheon, at the edge of woods where there's a level change in topography; several dozen tents, crates and carts outside, but staged with no real mining.", "t": 2808}, {"name": "Tunnel System", "kind": "place", "note": "Beyond a false ending and tight switchback, a straight dark path lit by sparse oil lanterns and wide enough for carts, extending about 2.5 miles toward Eden Moor and opening into a vertical cavern with prisoner alcoves 75-200 feet apart.", "t": 6329}, {"name": "Giovanni's Tavern", "kind": "place", "note": "Where the Driftwood Kin's performance in the trials built the reputation that brought Vera to them.", "t": 1999}, {"name": "Driftwood Kin", "kind": "faction", "note": "The party's organization, now based at Nastra Antheon and known for their performance in trials at Giovanni's Tavern.", "t": 156}, {"name": "Court of Blades", "kind": "faction", "note": "The guard of Eden Moor, whose emblem the mine guards wear; involved in the operation beneath the city and connected to the disappearances of miners and stonemasons.", "t": 6018}, {"name": "Callestus", "kind": "nation", "note": "One of the five nations, currently ruling Eden Moor alongside Tostrain; has Barrow Captains like Tycerus, is trying to hide the operation beneath Eden Moor, and is the target of Vera's vendetta.", "t": 4242}, {"name": "Tostrain", "kind": "faction", "note": "One of the five nations; rules Eden Moor alongside Callestus, and one of the lands Talon traveled through.", "t": 2352}, {"name": "Va", "kind": "faction", "note": "One of the five nations named alongside Callestus, Tostrain, Caberos and Escana; one of the lands Talon traveled through.", "t": 4242}, {"name": "Cauberos", "kind": "nation", "note": "One of the five nations named alongside Callestus, Tostrain, Va and Escana; one of the lands Talon traveled through.", "t": 4242, "alias": "Caberos"}, {"name": "Escana", "kind": "faction", "note": "One of the five nations named alongside Callestus, Tostrain, Va and Caberos.", "t": 4242}, {"name": "The Blood Father", "kind": "npc", "note": "Connected to the Howjaws; the party possesses his letters and used his name to bluff their way into the mine.", "t": 5627}, {"name": "Howjaws", "kind": "faction", "note": "Formerly a danger in the plains along with wolves; Ponzi theorizes they have scattered after losing their central figure but could regroup.", "t": 3600}], "gaps": ["SESSION INFO lists both Date and Location as \"Not specified\"; the only date available is the note's front-matter timestamp (12/07/2025 00:39).", "No explanation is given for Nyx's absence, and Nyx takes no action in the note despite being on the roster.", "The initiative list gives numbers only for Ponzi (23), Talon (18) and Vera (15); guards, priests, Tycerus, Tom and Rune Willow are listed in order with no rolls.", "No HP totals, damage taken, or downed-character information is recorded for the party; the only damage number in the note is Talon's Shatter (18 to both guards).", "The number of prisoners freed is never stated — the note says only \"an unknown number\".", "Vera's name appears three ways (Vera, Virag Zik, and \"Full name: Suresnya Verag\") with no clarification of which is correct."], "iso": "2025-12-07", "pretty": "7 Dec 2025", "audio": false, "legendary": true, "timecodesReliable": true, "n": 2}, {"slug": "session-8-what-grows-in-the-vault", "title": "Session 8: “What Grows in the Vault”", "date": "09/12/2025 00:08", "runtime": "2h 59min 43s", "nottaId": "84956fbe-9b99-4fbe-b249-848bf37085ac", "url": "https://app.notta.ai/7366972874555052032/dashboard/84956fbe-9b99-4fbe-b249-848bf37085ac", "template": "General", "hasTimecodes": true, "durationSec": 10783, "subtitle": "A brand, a debt, a note at dawn", "logline": "The Driftwood Kin win a bloody hunt for Parryton antlers while Nyx is captured and branded by Dawson, binding the party to a debt.", "recap": "The session begins with the party in combat against Parrytons and giant badgers, with Scar, Ponzi and Runewillow all knocked unconscious before the creatures are defeated. Runewillow examines glowing runes carved into stones, identifies them as giant magic runes, and copies them for later study while the others harvest Paryton antlers, claws and other trophies. Meanwhile Nyx is confronted by a dwarf who calls him a liar, is shackled and carried to Dawson's vault, where Dawson, a gold-scaled dragonborn, brands him as a sign of debt or ownership. The party returns to Fausti, sells its monster parts to the merchant Fosse for enchanted arrows and daggers, then goes to Dawson's vault to find Nyx, where Scar is knocked unconscious by a drow woman's sleep spell. Reunited at the Mirth in Valor, they spend the evening drumming up excitement for the next day's delve, sleep, and wake to find a note from Dawson pinned to their door, visible only to Nyx.", "dm": null, "party": ["Scar", "Runewillow", "Ponzi", "Ketsa", "Nyx", "Talon"], "opens": "The party mid-combat against Parrytons and giant badgers.", "closes": "The party wakes the next morning to a note from Dawson pinned to their door, visible only to Nyx.", "cards": {"changed": {"headline": "Nyx leaves Dawson's vault branded", "detail": "Dawson brands Nyx on the back of the neck as a sign of ownership or debt, positioned so it will always be visible above his shirt collar. Runewillow understands that Nyx's debt to Dawson may now extend to the entire party.", "t": 6956}, "learned": {"headline": "The carved stones are giant magic runes", "detail": "Runewillow examines glowing runes carved into stones, rolls an Arcana check, and recognizes them as giant magic runes — inherently magical rather than just housing magic. She uses her forgery kit to copy them for later study.", "t": 3433}, "who": {"headline": "Nyx — taken, branded, and marked out", "detail": "Separated from the party, Nyx fights and then negotiates with a dwarf, is shackled and carried to Dawson's vault, is branded by Dawson, and is the only one who can see the note left on their door the next morning.", "t": 782}, "cost": {"headline": "Three party members down, and a debt taken on", "detail": "Scar, Ponzi and Runewillow are knocked unconscious in the Parryton fight; Scar is later knocked unconscious again by a drow woman's sleep spell at Dawson's vault; and Nyx carries out a brand marking a debt to Dawson that may extend to the whole party.", "t": 8104}, "hanging": {"headline": "What does Dawson's note say?", "detail": "A note from Dawson is pinned to the party's door, visible only to Nyx, on the morning of the delve. Nyx has not yet read it.", "t": 10756}}, "beats": [{"t": 0, "kind": "combat", "title": "Combat with Parrytons and Giant Badgers", "line": "The party is already in combat against Parrytons when the session opens, and the fight goes badly before it goes well.", "facets": [["Combat", "Runewillow casts \"Shatter,\" killing one Parryton, then uses \"Blade Song\" and moves away from danger."], ["Combat", "Ponzi shoots at a Parryton but misses; Scar throws hand axes at a Parryton, hitting it twice; Talon gives Ketsa bardic inspiration."], ["Combat", "The Parrytons severely injure Scar and knock him unconscious, then knock Ponzi unconscious; giant badgers join the fight, attacking Runewillow and Talon."], ["Character", "Ketsa remains in a tree, shooting arrows at the creatures."], ["Combat", "The party struggles but eventually defeats all the Parrytons and badgers."]]}, {"t": 782, "kind": "combat", "title": "Nyx's Confrontation with a Dwarf", "line": "Elsewhere, a dwarf calls Nyx a liar, and the argument turns into a fight Nyx can only end by bargaining.", "facets": [["Check", "Nyx casts Entangle but the dwarf succeeds on his saving throw; a later attempt to charm the dwarf also fails."], ["Combat", "Nyx draws a flaming sword and tries to talk his way out; the dwarf attacks but misses."], ["Magic", "Nyx uses his ability \"Fate\" to teleport 15 feet away and casts Entangle again, successfully restraining the dwarf."], ["Decision", "Nyx negotiates with the dwarf and agrees to meet someone named Dawson."], ["Character", "The dwarf shackles Nyx and knocks him unconscious before carrying him away."]]}, {"t": 3433, "kind": "lore", "title": "Recovery and Examination of Runes", "line": "With the field cleared, the party patches itself up and Runewillow reads the glowing stones.", "facets": [["Character", "Talon heals Ponzi and Scar, while Scar stabilizes Runewillow."], ["Check", "Runewillow rolls an Arcana check on glowing runes carved into stones in the area."], ["New lore", "The runes are giant magic runes, which are inherently magical rather than just housing magic."], ["Item", "Runewillow uses her forgery kit to copy the runes for later study."], ["Item", "Other party members harvest the Parryton antlers they were hunting for, as well as claws and other trophies."]]}, {"t": 4082, "kind": "item", "title": "Return to Fausti and Trading with Fosse", "line": "The party reaches the city of Fausti before nightfall and turns monster parts into magic.", "facets": [["Major NPC", "Fosse, a merchant, buys the party's collected monster parts."], ["Item", "In return the party receives two +1 daggers, five +1 arrows, and an enchantment on Talon's daggers."], ["Decision", "Ponzi takes both +1 daggers initially but considers giving one to Ketsa."], ["Character", "The party takes a short rest to recover from their injuries."]]}, {"t": 5660, "kind": "scene", "title": "Search for Nyx", "line": "Word of Nyx's capture sends the party to Dawson's vault, where Scar swings first and pays for it.", "facets": [["Major NPC", "Giovanni, a tavern keeper, tells the party that Nyx has been captured and taken to Dawson's vault."], ["Combat", "Scar takes the lead, asks guards about Nyx, confronts a dragonborn guard and punches him; more guards arrive."], ["Magic", "A drow woman casts a sleep spell on Scar, knocking him unconscious."], ["Character", "Runewillow and Ponzi are escorted out of the vault, while Ketsa manages to avoid being associated with them."]]}, {"t": 6956, "kind": "dread", "title": "Nyx's Encounter with Dawson", "line": "In a cell beneath the vault, Nyx tries to sell himself as valuable and is marked as property instead.", "facets": [["Major NPC", "Dawson is a gold-scaled dragonborn wearing luxurious clothing and jewelry."], ["Character", "Nyx tries to appear mysterious and valuable, suggesting he might be useful to Dawson; Dawson is unimpressed."], ["Character", "Dawson brands Nyx on the back of the neck as a sign of ownership or debt, then has him thrown out of the vault."], ["Environment", "The brand is positioned so it will always be visible above his shirt collar."]]}, {"t": 7862, "kind": "social", "title": "Reunion and Evening at the Tavern", "line": "The party puts itself back together outside the vault, and the brand tells them what Nyx won't.", "facets": [["Character", "Nyx downplays his encounter with Dawson but shows the others his brand."], ["Character", "Runewillow is upset, understanding that Nyx's debt to Dawson may now extend to the entire party."], ["Decision", "They return to the Mirth in Valor tavern to spend the evening drumming up excitement for their upcoming \"delve\" (dungeon expedition) scheduled for the next day."]]}, {"t": 8650, "kind": "social", "title": "Preparations for the Delve", "line": "Each of them works the room in their own way, selling the delve to the tavern.", "facets": [["Character", "Scar tells exaggerated tales of their recent adventures; Nyx avoids talking about his encounter with Dawson."], ["Character", "Runewillow spends two hours in their room transcribing a spell."], ["Character", "Ponzi performs music with Talon, drawing a crowd."], ["Major NPC", "After the performance Ponzi returns a viola to a man named Jephth, telling him \"your father says he's proud of you,\" which moves Jephth to tears."], ["Character", "Ketsa paints runes representing courage, ingenuity, or luck on patrons' hands, creating excitement and engagement."]]}, {"t": 9953, "kind": "item", "title": "Gifts and Final Preparations", "line": "The night winds down with gifts, an apology, a cat on a shoulder, and a note waiting at dawn.", "facets": [["Major NPC", "Ulf, a shop owner, gives Scar a small, leather-bound book with metallic green embossing."], ["Item", "The book is a \"book of the tender,\" enchanted so that Scar, who cannot normally read, can understand its contents."], ["Major NPC", "Ulf apologizes to Runewillow for treating her as a curiosity and offers to sell her an \"amulet, proof against detection and location\" at his shop."], ["Magic", "Nyx transforms into a cat as a final display to impress the tavern patrons, then perches on Scar's shoulder."], ["Decision", "The party goes to sleep knowing they will enter the dungeon the next day at sunset."], ["Environment", "When they wake the next morning, they find a note from Dawson pinned to their door, visible only to Nyx."]]}], "threads": [{"u": "hi", "q": "What does the note from Dawson say, and why is it visible only to Nyx?", "t": 10756}, {"u": "hi", "q": "Does Nyx's debt to Dawson now extend to the entire party?", "t": 8104}, {"u": "hi", "q": "What waits in the dungeon the party enters at sunset?", "t": 10726}, {"u": "md", "q": "What do the giant magic runes Runewillow copied actually say or do?", "t": 3433}, {"u": "md", "q": "Will Runewillow buy the \"amulet, proof against detection and location\" from Ulf's shop?", "t": 10583}, {"u": "md", "q": "Will Fosse have the enchantment on Talon's daggers ready before the delve?", "t": 5190}, {"u": "lo", "q": "Will Ponzi give one of the two +1 daggers to Ketsa?", "t": 4082}, {"u": "lo", "q": "What is in the \"book of the tender\" Ulf gave Scar?", "t": 9953}], "next": ["The party needs to complete their delve (dungeon expedition) scheduled for the next day at sunset.", "Runewillow plans to visit Ulf's shop to look at the \"amulet, proof against detection and location.\"", "Nyx needs to address his debt to Dawson, which may now extend to the entire party.", "The party needs to collect payment from Fosse for the enchantment on Talon's daggers, which he said would be ready before their delve.", "Nyx needs to read the note from Dawson that was pinned to their door."], "entities": [{"name": "Driftwood Kin", "kind": "faction", "note": "The party, consisting of Scar, Runewillow (or Runewill), Ponzi, Ketsa, Nyx, and Talon.", "t": null}, {"name": "Scar", "kind": "pc", "note": "Throws hand axes; knocked unconscious by Parrytons and later by a sleep spell at Dawson's vault; cannot normally read; given the \"book of the tender\" by Ulf.", "t": 0}, {"name": "Rune Willow", "kind": "pc", "note": "Also given as Runewill. Casts Shatter and Blade Song; identifies and copies the giant magic runes; upset about Nyx's debt.", "t": 0, "alias": "Runewillow"}, {"name": "Ponzi", "kind": "pc", "note": "Knocked unconscious in the Parryton fight; takes both +1 daggers; performs music with Talon and returns a viola to Jephth.", "t": 0, "reveal": "Ponzi's real name is Asher — named by the Solemn Keeper of the Prisons."}, {"name": "Ketza", "kind": "pc", "note": "Remains in a tree shooting arrows through most of the combat; avoids being associated with the party at the vault; paints runes on patrons' hands.", "t": 0, "alias": "Ketsa"}, {"name": "Nyx", "kind": "pc", "note": "Separated from the party; captured by a dwarf, branded by Dawson, and the only one who can see Dawson's note. Transforms into a cat.", "t": 782, "reveal": "Nyx is a Changeling. His true name is Khaonn Lochai."}, {"name": "Talon", "kind": "pc", "note": "Gives Ketsa bardic inspiration, heals Ponzi and Scar, has daggers enchanted by Fosse, performs music with Ponzi.", "t": 0, "reveal": "Talon's real name is Tanner."}, {"name": "Parrytons", "kind": "creature", "note": "Also given as Perringtons. Creatures the party fights and hunts for their antlers (spelled \"Paryton antlers\" in the source).", "t": 0}, {"name": "giant badgers", "kind": "creature", "note": "Join the Parryton fight, attacking Runewillow and Talon.", "t": 0}, {"name": "Dawson", "kind": "npc", "note": "A gold-scaled dragonborn in luxurious clothing and jewelry who brands Nyx as a sign of ownership or debt.", "t": 6956}, {"name": "Fosse", "kind": "npc", "note": "Merchant in Fausti who buys the party's monster parts and pays in magic items and enchantment.", "t": 4082}, {"name": "Giovanni", "kind": "npc", "note": "Tavern keeper who tells the party Nyx has been captured and taken to Dawson's vault.", "t": 5660}, {"name": "Ulf", "kind": "npc", "note": "Shop owner who gifts Scar the \"book of the tender\" and offers Runewillow an amulet.", "t": 9953}, {"name": "Jephth", "kind": "npc", "note": "A man Ponzi returns a viola to, telling him \"your father says he's proud of you,\" which moves him to tears.", "t": 8650}, {"name": "Fausti", "kind": "place", "note": "The city the party returns to before nightfall to trade with Fosse.", "t": 4082}, {"name": "Dawson's vault", "kind": "place", "note": "Where Nyx is held in a cell and branded, and where Scar is put to sleep by a drow woman.", "t": 782}, {"name": "Mirth in Valor", "kind": "place", "note": "The tavern where the party reunites and spends the evening drumming up excitement for the delve.", "t": 7862}, {"name": "book of the tender", "kind": "item", "note": "A small, leather-bound book with metallic green embossing, enchanted so Scar can understand its contents.", "t": 9953}, {"name": "amulet, proof against detection and location", "kind": "item", "note": "Offered for sale to Runewillow by Ulf at his shop.", "t": 9953}, {"name": "Paryton antlers", "kind": "item", "note": "The trophy the party was specifically hunting for; harvested with claws and other trophies.", "t": 3433}], "gaps": ["The DM is never named in the source, so `dm` is null.", "No player names, character classes, levels, races or HP totals are given for any party member.", "Runewillow's name is given two ways in the source (\"Runewillow (or Runewill)\"), and the creatures appear as both \"Parrytons\" and \"Perringtons\", with the harvested antlers spelled \"Paryton antlers\".", "The dwarf who captures Nyx and the drow woman who casts sleep on Scar are both unnamed in the source.", "The contents of Dawson's note are not stated, only that it is visible to Nyx alone.", "No dice results, DCs, damage numbers or house rulings are recorded, only that natural 20s and natural 1s affected the narrative."], "iso": "2025-09-12", "pretty": "12 Sep 2025", "audio": false, "legendary": true, "timecodesReliable": true, "n": 1}];
